/**
 * Pratos do cardápio com a quantidade de cada ingrediente nas 4 fases: q = [fase 1, fase 2, fase 3, fase 4].
 * Arquivo gerado por scripts/gerar-pratos.ts. Para mudar um prato, edite a base lá e rode o script.
 */
import type { IdAlimento } from './alimentos'

export type Categoria = 'pre' | 'cafe' | 'lanche' | 'almoco' | 'jantar' | 'ceia'

export interface ItemDoPrato {
  a: IdAlimento
  q: readonly [number, number, number, number]
}

export type Etiqueta = 'doce' | 'salgado' | 'besteira' | 'marmita' | 'vegetariano'

export interface Prato {
  nome: string
  categoria: Categoria
  itens: readonly ItemDoPrato[]
  /** Resumo de uma frase, mostrado no cardápio do dia. */
  preparo: string
  /** Preparo de domingo em RECEITAS, quando o prato sai de uma receita feita para a semana. */
  receita?: string
  /** Minutos até estar pronto para comer. */
  tempo: number
  passos: readonly string[]
  etiquetas: readonly Etiqueta[]
  /** Ingredientes sem peso na conta: sal, alho em pó, orégano. */
  temperos?: readonly string[]
  /** Como levar para o trabalho. */
  levar?: string
  /** Versão na airfryer de quem leva fritura. */
  airfryer?: string
}

/** Calorias de cada categoria por fase. Três lanches por dia. */
export const ORCAMENTO: Record<Categoria, readonly [number, number, number, number]> = {pre:[180,200,210,170],cafe:[480,530,560,450],lanche:[230,260,280,215],almoco:[620,690,730,600],jantar:[520,570,610,495],ceia:[260,280,300,240]}

export const PRATOS = {
  pre1: { nome: "Banana com pasta de amendoim", categoria: 'pre', itens: [{ a: 'banana', q: [1, 1, 1, 1] }, { a: 'pastaAmendoim', q: [15, 20, 20, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó misturados em meio copo de água.", tempo: 3, passos: ["Descasque a banana.","Passe a pasta de amendoim em fio sobre a banana, ou mergulhe cada pedaço na pasta.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre2: { nome: "Pão com mel", categoria: 'pre', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'mel', q: [10, 20, 20, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó misturados em meio copo de água.", tempo: 3, passos: ["Passe o mel em uma fatia de pão de forma.","Cubra com a outra fatia e feche como sanduíche.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre3: { nome: "Suco de laranja com aveia", categoria: 'pre', itens: [{ a: 'sucoLaranja', q: [250, 250, 300, 250] }, { a: 'aveia', q: [20, 25, 25, 20] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata tudo junto e beba.", tempo: 3, passos: ["Coloque o suco de laranja no liquidificador.","Junte a aveia, a beterraba e o guaraná em pó.","Bata por 30 segundos.","Beba logo, antes de a aveia assentar."], etiquetas: ["doce","vegetariano"] },
  pre4: { nome: "Vitamina rápida de Mucilon", categoria: 'pre', itens: [{ a: 'leite', q: [150, 150, 150, 150] }, { a: 'mucilon', q: [20, 25, 30, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata tudo junto e beba.", tempo: 3, passos: ["Coloque o leite e o Mucilon no liquidificador.","Junte a beterraba e o guaraná em pó no liquidificador.","Bata por 30 segundos e beba."], etiquetas: ["doce","vegetariano"] },
  pre5: { nome: "Banana amassada com aveia e mel", categoria: 'pre', itens: [{ a: 'banana', q: [1, 1, 1, 1] }, { a: 'aveia', q: [15, 15, 20, 15] }, { a: 'mel', q: [10, 15, 10, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó misturados em meio copo de água.", tempo: 3, passos: ["Amasse a banana com um garfo em uma tigela.","Misture a aveia e o mel até formar um creme grosso.","Coma de colher.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  cafe1: { nome: "Ovos mexidos, pão e shake de whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [2, 2, 2, 2] }, { a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 200, 250, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Bata os ovos com uma pitada de sal.","Despeje em frigideira antiaderente em fogo baixo e mexa sem parar por 2 a 3 minutos, até firmar cremoso.","Abra o pão francês ao meio e aqueça na frigideira ou na sanduicheira por 1 minuto.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe2: { nome: "Vitamina de whey, banana e aveia", categoria: 'cafe', itens: [{ a: 'leite', q: [250, 300, 300, 250] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'aveia', q: [30, 35, 40, 20] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'maca', q: [5, 5, 5, 5] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Bata tudo no liquidificador.", receita: 'shakePosTreino', tempo: 4, passos: ["Coloque no liquidificador o leite, a banana, a aveia, o whey e a maca.","Bata por 30 segundos.","Junte a creatina por último e bata mais 5 segundos.","Beba logo depois do treino."], etiquetas: ["doce","vegetariano"] },
  cafe3: { nome: "Misto quente e shake de whey", categoria: 'cafe', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'presunto', q: [2, 2, 2, 2] }, { a: 'leite', q: [100, 200, 250, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 8, passos: ["Monte o sanduíche: pão, presunto e mussarela, outra fatia de pão.","Leve à sanduicheira por 3 a 4 minutos, até dourar e o queijo derreter.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos.","Corte ao meio e coma com o shake."], etiquetas: ["salgado"] },
  cafe4: { nome: "Panqueca de aveia e banana com whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [2, 2, 2, 2] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'aveia', q: [20, 25, 30, 15] }, { a: 'leite', q: [100, 150, 150, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite, para beber junto.", receita: 'panquecaAveia', tempo: 12, passos: ["Amasse a banana com um garfo e misture com os ovos e a aveia.","Aqueça a frigideira antiaderente em fogo médio.","Despeje a massa e deixe 2 minutos de cada lado, até dourar.","Bata no liquidificador o leite, o whey e a creatina.","Sirva a panqueca com o shake."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  cafe5: { nome: "Pão de queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'paoQueijo', q: [2, 2, 2, 2] }, { a: 'leite', q: [200, 250, 300, 150] }, { a: 'achocolatado', q: [5, 10, 10, 5] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey, creatina e achocolatado batidos no leite.", tempo: 15, passos: ["Leve os pães de queijo à airfryer a 180 graus por 8 minutos, ou ao forno a 200 graus por 12 minutos, se forem congelados.","Bata no liquidificador o leite, o achocolatado, o whey e a creatina.","Sirva os pães quentes com o shake."], etiquetas: ["salgado","vegetariano"] },
  cafe6: { nome: "Pão com ovo e queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [150, 250, 300, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Frite o ovo em frigideira antiaderente com uma pitada de sal, até a clara firmar.","Torre as fatias de pão na frigideira ou na torradeira.","Monte o sanduíche com o ovo e a mussarela; aqueça 1 minuto para derreter o queijo.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  lanche1: { nome: "Sanduíche de presunto e queijo", categoria: 'lanche', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'presunto', q: [2, 2, 2, 1] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [5, 15, 25, 5] }], preparo: "Monte em casa e leve embrulhado.", tempo: 5, passos: ["Passe o requeijão em uma fatia de pão de forma.","Cubra com o presunto e a mussarela.","Feche com a outra fatia e pressione de leve.","Embrulhe bem apertado em papel alumínio ou filme."], etiquetas: ["salgado"], levar: "Embrulhado, vai na mochila até 3 horas. Passou disso, deixe na geladeira do trabalho." },
  lanche2: { nome: "Sanduíche de pasta de amendoim", categoria: 'lanche', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'pastaAmendoim', q: [20, 25, 25, 15] }], preparo: "Monte em casa e leve embrulhado.", tempo: 3, passos: ["Espalhe a pasta de amendoim em uma fatia de pão de forma.","Feche com a outra fatia.","Corte ao meio e embrulhe em papel alumínio."], etiquetas: ["doce","vegetariano"], levar: "Aguenta o dia todo na mochila, sem geladeira." },
  lanche3: { nome: "Vitamina de Farinha Láctea na garrafa", categoria: 'lanche', itens: [{ a: 'leite', q: [200, 250, 250, 200] }, { a: 'farinhaLactea', q: [25, 25, 30, 20] }], preparo: "Bata de manhã e leve em garrafa térmica.", receita: 'vitaminaFarinhaLactea', tempo: 5, passos: ["Aqueça uma garrafa térmica com água quente por 1 minuto e descarte a água.","Bata o leite e a Farinha Láctea no liquidificador por 30 segundos.","Despeje na garrafa térmica e feche bem."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica, bebida em até 5 horas. Se for gelada, leve na bolsa térmica com gelo." },
  lanche4: { nome: "Banana, pasta de amendoim e leite", categoria: 'lanche', itens: [{ a: 'banana', q: [1, 1, 1, 1] }, { a: 'pastaAmendoim', q: [10, 10, 15, 10] }, { a: 'leite', q: [150, 200, 200, 150] }], preparo: "Leite em garrafa térmica; a pasta vai num potinho.", tempo: 3, passos: ["Despeje o leite na garrafa térmica.","Coloque a pasta de amendoim em um potinho com tampa.","Leve a banana inteira, com casca.","Na hora, passe a pasta na banana e beba o leite junto."], etiquetas: ["doce","vegetariano"], levar: "Leite em garrafa térmica gelada, pasta no potinho. A banana vai inteira, na mochila." },
  lanche5: { nome: "Iogurte com aveia e mel", categoria: 'lanche', itens: [{ a: 'iogurte', q: [160, 190, 220, 170] }, { a: 'aveia', q: [30, 30, 35, 25] }, { a: 'mel', q: [10, 15, 10, 10] }], preparo: "Leve a aveia separada e misture na hora.", tempo: 3, passos: ["Coloque o iogurte em um pote com tampa.","Ponha a aveia em um potinho separado.","Leve o mel em um potinho pequeno.","Na hora de comer, misture a aveia e o mel no iogurte."], etiquetas: ["doce","vegetariano"], levar: "Iogurte na geladeira do trabalho. Aveia e mel separados na mochila." },
  lanche6: { nome: "Esfiha de carne e suco", categoria: 'lanche', itens: [{ a: 'esfiha', q: [1, 1, 1, 1] }, { a: 'sucoLaranja', q: [100, 200, 250, 100] }], preparo: "Vale comprar pronto na padaria.", tempo: 15, passos: ["Compre a esfiha de carne pronta na padaria ou use uma esfiha caseira do freezer.","Aqueça em forno ou airfryer a 180 graus por 5 minutos, para ficar crocante.","Deixe amornar 5 minutos e embrulhe em papel alumínio.","Esprema 2 laranjas num copinho com tampa."], etiquetas: ["salgado","besteira"], levar: "Esfiha embrulhada para comer em até 3 horas. Suco no copinho, na geladeira do trabalho.", airfryer: "Airfryer a 180 graus por 5 minutos." },
  lanche7: { nome: "Biscoito com queijo minas", categoria: 'lanche', itens: [{ a: 'creamCracker', q: [35, 40, 40, 25] }, { a: 'minas', q: [30, 35, 40, 40] }], preparo: "Queijo em fatias num pote.", tempo: 3, passos: ["Corte o queijo minas em fatias finas.","Guarde o queijo em um pote com tampa.","Separe o cream cracker em outro pote, para não amolecer.","Na hora, monte o biscoito com uma fatia de queijo."], etiquetas: ["salgado","vegetariano"], levar: "Queijo na geladeira do trabalho. Biscoito em pote fechado na mochila." },
  lanche8: { nome: "Sanduíche de frango desfiado", categoria: 'lanche', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'frango', q: [35, 60, 70, 35] }, { a: 'requeijao', q: [10, 5, 5, 5] }], preparo: "Use o frango da marmita, desfiado com requeijão.", tempo: 8, passos: ["Desfie o frango da marmita com um garfo.","Misture o frango com o requeijão e uma pitada de sal.","Abra o pão francês e recheie com a mistura.","Embrulhe em papel alumínio."], etiquetas: ["salgado"], temperos: ["sal"], levar: "Embrulhado, na geladeira do trabalho se passar de 3 horas. Come frio, sem esquentar." },
  lanche9: { nome: "Vitamina de Mucilon na garrafa", categoria: 'lanche', itens: [{ a: 'leite', q: [200, 250, 250, 250] }, { a: 'mucilon', q: [30, 30, 35, 15] }], preparo: "Bata de manhã e leve em garrafa térmica.", tempo: 5, passos: ["Aqueça uma garrafa térmica com água quente por 1 minuto e descarte a água.","Bata o leite e o Mucilon no liquidificador por 30 segundos.","Despeje na garrafa térmica e feche bem."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica, bebida em até 5 horas." },
  lanche10: { nome: "Leite com achocolatado e biscoito", categoria: 'lanche', itens: [{ a: 'leite', q: [150, 200, 200, 150] }, { a: 'achocolatado', q: [15, 15, 20, 15] }, { a: 'creamCracker', q: [20, 20, 20, 15] }], preparo: "Leite já batido com o achocolatado, na garrafa térmica.", tempo: 3, passos: ["Bata o leite com o achocolatado até dissolver.","Despeje na garrafa térmica.","Coloque o cream cracker em um pote com tampa.","Na hora, beba o leite e coma o biscoito."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica com leite gelado ou na bolsa com gelo. Biscoito em pote fechado." },
  lanche11: { nome: "Sanduíche de ovo", categoria: 'lanche', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [10, 25, 30, 5] }], preparo: "Ovo cozido amassado com o requeijão.", tempo: 15, passos: ["Cozinhe o ovo em água fervente por 10 minutos.","Esfrie em água corrente, descasque e amasse com um garfo.","Misture com o requeijão e uma pitada de sal.","Recheie o pão de forma, feche e embrulhe."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"], levar: "Ovo cozido estraga rápido: leve na geladeira do trabalho e coma em até 4 horas." },
  almoco1: { nome: "Arroz, bife e batata", categoria: 'almoco', itens: [{ a: 'arroz', q: [200, 210, 220, 150] }, { a: 'patinho', q: [100, 120, 130, 130] }, { a: 'batata', q: [190, 220, 230, 150] }, { a: 'azeite', q: [5, 5, 5, 5] }], preparo: "Batata assada na airfryer, com o azeite.", receita: 'batataAssada', tempo: 45, passos: ["Arroz da semana: veja o preparo de domingo.","Tempere os bifes com sal e alho em pó e sele em frigideira antiaderente bem quente, 2 minutos de cada lado. Corte em tiras.","Misture os gomos de batata com o azeite, sal e páprica. Airfryer a 200 graus por 20 a 25 minutos, sacudindo na metade.","Deixe esfriar 10 minutos com a tampa aberta, para não suar dentro do pote.","Monte cada pote com arroz de um lado, bife e batata do outro."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica"], levar: "Pote com tampa na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta, mexendo na metade.", airfryer: "Batata em gomos na airfryer a 200 graus por 20 a 25 minutos." },
  almoco2: { nome: "Arroz com carne moída e ovo", categoria: 'almoco', itens: [{ a: 'arroz', q: [230, 270, 280, 180] }, { a: 'moida', q: [120, 130, 140, 140] }, { a: 'ovo', q: [1, 1, 1, 1] }], preparo: "Ovo cozido, para aguentar a marmita.", receita: 'carneMoida', tempo: 35, passos: ["Carne moída da semana e arroz da semana: veja o preparo de domingo.","Cozinhe os ovos por 9 minutos em água fervente, passe em água gelada e descasque.","Divida o arroz nos potes e coloque a carne ao lado.","Ovo cozido inteiro por cima, sem cortar, para não ressecar."], etiquetas: ["salgado","marmita"], temperos: ["sal","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos; o ovo só esquenta junto, sem estourar, com a tampa entreaberta." },
  almoco3: { nome: "Macarrão à bolonhesa", categoria: 'almoco', itens: [{ a: 'macarrao', q: [230, 260, 280, 190] }, { a: 'moida', q: [80, 90, 90, 100] }, { a: 'molhoTomate', q: [60, 70, 90, 60] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Queijo por cima, derrete no micro-ondas.", receita: 'bolonhesa', tempo: 40, passos: ["Molho à bolonhesa: veja o preparo de domingo.","Cozinhe o macarrão em água com sal, 2 minutos a menos que o tempo da embalagem. Escorra e passe em água fria.","Divida o macarrão nos potes e cubra com o molho à bolonhesa.","Coloque a fatia de mussarela por cima de cada pote."], etiquetas: ["salgado","marmita"], temperos: ["sal","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta; mexa na metade para derreter o queijo no molho." },
  almoco4: { nome: "Frango, purê e arroz", categoria: 'almoco', itens: [{ a: 'frango', q: [120, 140, 140, 160] }, { a: 'pure', q: [210, 220, 250, 170] }, { a: 'arroz', q: [170, 190, 200, 140] }], preparo: "Frango em cubos, grelhado.", receita: 'pureBatata', tempo: 45, passos: ["Purê de batata e arroz da semana: veja o preparo de domingo.","Corte o frango em cubos, tempere com sal, alho em pó e páprica e grelhe em frigideira antiaderente, 4 minutos de cada lado.","Divida arroz, purê e frango nos potes, cada um no seu canto.","Feche só depois de esfriar por 10 minutos."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco5: { nome: "Sobrecoxa assada, arroz e batata", categoria: 'almoco', itens: [{ a: 'sobrecoxa', q: [120, 130, 140, 140] }, { a: 'arroz', q: [200, 220, 240, 160] }, { a: 'batata', q: [160, 200, 190, 130] }], preparo: "Sobrecoxa e batata assadas juntas.", receita: 'arrozDaSemana', tempo: 55, passos: ["Arroz da semana: veja o preparo de domingo.","Tempere as sobrecoxas com sal, alho em pó e páprica. Tire a pele.","Em assadeira, junte a sobrecoxa e os gomos de batata temperados com sal. Forno a 200 graus por 40 minutos, virando na metade.","Deixe esfriar e desosse a sobrecoxa, para caber bem no pote.","Monte os potes com arroz, carne desfiada em pedaços e batata."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta." },
  almoco6: { nome: "Escondidinho de carne moída", categoria: 'almoco', itens: [{ a: 'pure', q: [300, 320, 360, 230] }, { a: 'moida', q: [90, 110, 110, 110] }, { a: 'mussarela', q: [2, 2, 2, 2] }], preparo: "Camada de carne, purê por cima e queijo.", receita: 'pureBatata', tempo: 45, passos: ["Carne moída da semana e purê de batata: veja o preparo de domingo.","Em refratários individuais ou potes que vão ao micro-ondas, espalhe a carne moída no fundo.","Cubra com o purê, alisando com as costas da colher, e risque com um garfo.","Distribua a mussarela por cima. Gratine no forno a 220 graus por 10 minutos, até dourar.","Deixe esfriar antes de tampar."], etiquetas: ["salgado","marmita"], temperos: ["sal"], levar: "Pote na geladeira do trabalho, ou congelado na noite anterior. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco7: { nome: "Macarrão com frango e requeijão", categoria: 'almoco', itens: [{ a: 'macarrao', q: [260, 290, 310, 220] }, { a: 'frango', q: [100, 110, 110, 130] }, { a: 'requeijao', q: [10, 15, 15, 10] }, { a: 'molhoTomate', q: [70, 60, 80, 60] }], preparo: "Misture o requeijão no molho quente.", receita: 'frangoCremoso', tempo: 40, passos: ["Frango cremoso com requeijão: veja o preparo de domingo.","Cozinhe o macarrão em água com sal, 2 minutos a menos que o tempo da embalagem. Escorra e passe em água fria.","Misture o frango cremoso com o molho de tomate restante e deixe ferver 2 minutos.","Divida o macarrão nos potes e cubra com o frango cremoso."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade para o molho cobrir o macarrão." },
  almoco8: { nome: "Estrogonofe de frango com arroz", categoria: 'almoco', itens: [{ a: 'frango', q: [130, 140, 150, 160] }, { a: 'cremeLeite', q: [25, 30, 35, 20] }, { a: 'molhoTomate', q: [35, 50, 50, 50] }, { a: 'arroz', q: [270, 300, 310, 220] }], preparo: "Creme de leite por último, com o fogo desligado.", receita: 'estrogonofe', tempo: 40, passos: ["Estrogonofe de frango e arroz da semana: veja o preparo de domingo.","Guarde o estrogonofe separado do arroz até a hora de montar.","Divida o arroz nos potes e coloque o estrogonofe ao lado, não por cima, para o arroz não empapar.","Feche depois de esfriar."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade. Dura até 3 dias." },
  almoco9: { nome: "Sobrecoxa, arroz e purê", categoria: 'almoco', itens: [{ a: 'sobrecoxa', q: [100, 120, 120, 130] }, { a: 'arroz', q: [170, 180, 200, 130] }, { a: 'pure', q: [170, 180, 190, 130] }], preparo: "Sobrecoxa assada sem pele.", receita: 'pureBatata', tempo: 55, passos: ["Purê de batata e arroz da semana: veja o preparo de domingo.","Tempere as sobrecoxas com sal, alho em pó e páprica e tire a pele.","Forno a 200 graus por 40 minutos, virando na metade.","Desosse depois de fria e corte em pedaços.","Monte os potes com arroz, purê e frango."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco10: { nome: "Arroz de forno com frango e queijo", categoria: 'almoco', itens: [{ a: 'arroz', q: [240, 280, 290, 200] }, { a: 'frango', q: [100, 110, 120, 120] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'requeijao', q: [10, 10, 15, 10] }], preparo: "Arroz misturado ao frango desfiado e requeijão, queijo por cima.", receita: 'frangoDaSemana', tempo: 50, passos: ["Arroz da semana e frango grelhado: veja o preparo de domingo. Desfie o frango.","Misture o arroz, o frango desfiado e o requeijão, com sal e orégano.","Divida em potes que vão ao micro-ondas e cubra com a mussarela.","Forno a 200 graus por 15 minutos, até o queijo dourar.","Deixe esfriar antes de tampar."], etiquetas: ["salgado","marmita"], temperos: ["sal","orégano"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco11: { nome: "Lasanha de carne moída", categoria: 'almoco', itens: [{ a: 'macarrao', q: [190, 220, 220, 140] }, { a: 'moida', q: [60, 70, 90, 90] }, { a: 'molhoTomate', q: [90, 90, 90, 80] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'presunto', q: [2, 2, 2, 2] }], preparo: "Camadas de massa, molho com carne, presunto e queijo. Assa no domingo e corta em porções.", receita: 'lasanha', tempo: 60, passos: ["Lasanha de carne moída: veja o preparo de domingo, que já rende as porções da semana.","Espere a lasanha esfriar por 30 minutos antes de cortar, para não desmanchar.","Corte em porções e passe cada uma para um pote com a espátula.","Guarde o que vai ser comido depois de 4 dias no congelador."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (6 se vier do congelador), tampa entreaberta." },
  jantar1: { nome: "Hambúrguer caseiro no pão", categoria: 'jantar', itens: [{ a: 'moida', q: [140, 170, 190, 130] }, { a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Um disco de carne moída, 4 minutos de cada lado.", receita: 'hamburguer', tempo: 15, passos: ["Misture a carne moída crua com sal e alho em pó e modele um disco achatado, do tamanho do pão.","Aqueça a frigideira bem quente, sem óleo, e grelhe o disco 4 minutos de cada lado.","Ponha a mussarela por cima nos últimos 30 segundos e tampe para derreter.","Abra o pão, aqueça na frigideira por 1 minuto e monte o hambúrguer."], etiquetas: ["salgado","besteira"], temperos: ["sal","alho em pó"] },
  jantar2: { nome: "Bife com batata frita e arroz", categoria: 'jantar', itens: [{ a: 'patinho', q: [70, 80, 80, 90] }, { a: 'batataFrita', q: [100, 100, 110, 80] }, { a: 'arroz', q: [80, 100, 110, 70] }], preparo: "Na Fase 4, troque a batata frita pela assada.", tempo: 22, passos: ["Tempere o bife com sal e alho em pó.","Ponha a batata frita congelada na airfryer a 200 graus por 15 minutos, sacudindo na metade.","Aqueça a frigideira bem quente e grelhe o bife 3 minutos de cada lado.","Esquente o arroz no micro-ondas por 2 minutos e monte o prato."], etiquetas: ["salgado","besteira"], temperos: ["sal","alho em pó"], airfryer: "Batata frita na airfryer a 200 graus por 15 minutos, sacudindo na metade. Fica crocante sem óleo." },
  jantar3: { nome: "Omelete de queijo com arroz", categoria: 'jantar', itens: [{ a: 'ovo', q: [3, 3, 3, 3] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'arroz', q: [130, 170, 200, 110] }], preparo: "Pronto em 8 minutos.", receita: 'omelete', tempo: 8, passos: ["Bata os ovos com uma pitada de sal.","Aqueça uma frigideira antiaderente em fogo médio e despeje os ovos.","Quando firmar embaixo, ponha a mussarela no meio e dobre o omelete.","Esquente o arroz no micro-ondas por 2 minutos e sirva junto."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  jantar4: { nome: "Macarrão alho e óleo com frango", categoria: 'jantar', itens: [{ a: 'macarrao', q: [210, 230, 260, 180] }, { a: 'frango', q: [90, 100, 100, 110] }, { a: 'azeite', q: [5, 5, 5, 5] }], preparo: "Alho em pó no azeite, sem pedaços.", receita: 'frangoDaSemana', tempo: 15, passos: ["Cozinhe o macarrão em água com sal conforme a embalagem e escorra.","Aqueça o frango da semana no micro-ondas por 1 minuto e desfie.","Na frigideira, aqueça o azeite em fogo baixo com alho em pó por 30 segundos.","Junte o macarrão e o frango e mexa por 1 minuto."], etiquetas: ["salgado"], temperos: ["sal","alho em pó","água"] },
  jantar5: { nome: "Arroz, frango e ovo", categoria: 'jantar', itens: [{ a: 'arroz', q: [210, 240, 260, 170] }, { a: 'frango', q: [110, 120, 130, 130] }, { a: 'ovo', q: [1, 1, 1, 1] }], preparo: "Ovo frito por cima.", receita: 'frangoDaSemana', tempo: 10, passos: ["Esquente o arroz e o frango da semana no micro-ondas por 2 minutos.","Quebre o ovo em um ramequim untado e leve à airfryer a 180 graus por 5 minutos.","Tempere com sal e monte o prato com o ovo por cima."], etiquetas: ["salgado"], temperos: ["sal"], airfryer: "Ovo em ramequim na airfryer a 180 graus por 5 minutos, até a clara firmar." },
  jantar6: { nome: "Purê com carne moída", categoria: 'jantar', itens: [{ a: 'pure', q: [290, 320, 330, 220] }, { a: 'moida', q: [110, 120, 130, 130] }], preparo: "Sobra da marmita serve.", receita: 'pureBatata', tempo: 6, passos: ["Esquente o purê no micro-ondas por 3 minutos, mexendo na metade.","Esquente a carne moída da marmita por 2 minutos.","Ponha a carne por cima do purê e tempere com sal e pimenta-do-reino."], etiquetas: ["salgado"], temperos: ["sal","pimenta-do-reino"] },
  jantar7: { nome: "Churrasco com arroz", categoria: 'jantar', itens: [{ a: 'picanha', q: [100, 110, 120, 110] }, { a: 'arroz', q: [180, 200, 210, 140] }], preparo: "Picanha na frigideira bem quente.", tempo: 15, passos: ["Tempere a picanha com sal grosso e deixe fora da geladeira enquanto aquece a frigideira.","Com a frigideira bem quente, sem óleo, grelhe a picanha 3 minutos de cada lado.","Deixe descansar 2 minutos e corte em tiras finas.","Esquente o arroz no micro-ondas por 2 minutos e sirva."], etiquetas: ["salgado"], temperos: ["sal"] },
  jantar8: { nome: "Sanduíche quente de ovo e queijo", categoria: 'jantar', itens: [{ a: 'paoFrances', q: [2, 2, 2, 2] }, { a: 'ovo', q: [2, 2, 2, 1] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [50, 100, 150, 100] }], preparo: "Pronto em 8 minutos, na frigideira. Leite para acompanhar.", tempo: 8, passos: ["Abra os pães e aqueça na frigideira por 1 minuto de cada lado.","Na mesma frigideira, quebre os ovos e mexa em fogo médio até firmar.","Monte com ovo e mussarela dentro do pão e tampe a frigideira 1 minuto para derreter.","Sirva com o leite."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  jantar9: { nome: "Macarrão na manteiga com carne moída", categoria: 'jantar', itens: [{ a: 'macarrao', q: [200, 220, 240, 170] }, { a: 'moida', q: [80, 90, 90, 90] }, { a: 'manteiga', q: [5, 5, 5, 5] }], preparo: "A carne moída da semana vai por cima.", receita: 'carneMoida', tempo: 12, passos: ["Cozinhe o macarrão em água com sal conforme a embalagem e escorra.","Esquente a carne moída da semana no micro-ondas por 2 minutos.","Misture a manteiga ao macarrão quente até derreter.","Ponha a carne por cima e tempere com pimenta-do-reino."], etiquetas: ["salgado"], temperos: ["sal","pimenta-do-reino","água"] },
  jantar10: { nome: "Batata recheada com frango e requeijão", categoria: 'jantar', itens: [{ a: 'batata', q: [410, 450, 490, 320] }, { a: 'frango', q: [120, 130, 140, 140] }, { a: 'requeijao', q: [20, 25, 25, 15] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Batata no micro-ondas por 8 minutos, aberta e recheada.", receita: 'frangoDaSemana', tempo: 15, passos: ["Lave a batata, fure com um garfo e leve ao micro-ondas por 8 minutos, virando na metade.","Esquente o frango da semana por 1 minuto e desfie misturando com o requeijão.","Abra a batata ao meio e recheie com o frango.","Cubra com a mussarela e volte ao micro-ondas por 1 minuto."], etiquetas: ["salgado"], temperos: ["sal"] },
  ceia1: { nome: "Vitamina de Mucilon com banana", categoria: 'ceia', itens: [{ a: 'leite', q: [200, 200, 250, 200] }, { a: 'mucilon', q: [15, 20, 20, 10] }, { a: 'banana', q: [1, 1, 1, 1] }], preparo: "Bata e beba devagar.", receita: 'mucilonNoturno', tempo: 4, passos: ["Coloque no liquidificador o leite, o Mucilon e a banana em pedaços.","Bata por 30 segundos, até ficar liso e cremoso.","Se quiser morna, aqueça o copo no micro-ondas por 40 segundos antes de beber.","Beba devagar, sentado, uns 30 minutos antes de dormir."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia2: { nome: "Vitamina de Farinha Láctea", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 300, 250] }, { a: 'farinhaLactea', q: [25, 30, 30, 20] }], preparo: "Bata e beba devagar.", receita: 'vitaminaFarinhaLactea', tempo: 3, passos: ["Coloque o leite e a Farinha Láctea no liquidificador.","Bata por 30 segundos, até dissolver tudo.","Sirva gelada ou aqueça o copo no micro-ondas por 40 segundos.","Beba devagar, sem pressa."], etiquetas: ["doce","vegetariano"] },
  ceia3: { nome: "Iogurte batido com aveia e mel", categoria: 'ceia', itens: [{ a: 'iogurte', q: [180, 210, 210, 170] }, { a: 'leite', q: [100, 100, 100, 100] }, { a: 'aveia', q: [20, 20, 25, 15] }, { a: 'mel', q: [10, 10, 10, 10] }], preparo: "Bata até ficar cremoso.", tempo: 4, passos: ["Coloque o iogurte, o leite, a aveia e o mel no liquidificador.","Bata por 40 segundos, até a aveia sumir e ficar cremoso.","Deixe descansar 1 minuto para a aveia hidratar e engrossar.","Beba em copo alto, devagar."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia4: { nome: "Leite com achocolatado e pasta de amendoim", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 300, 300, 250] }, { a: 'achocolatado', q: [20, 15, 20, 15] }, { a: 'pastaAmendoim', q: [5, 5, 5, 5] }], preparo: "Bata para dissolver a pasta.", tempo: 4, passos: ["Coloque o leite, o achocolatado e a pasta de amendoim no liquidificador.","Bata por 40 segundos, até a pasta dissolver por completo.","Sirva gelado ou aqueça o copo no micro-ondas por 45 segundos.","Beba devagar."], etiquetas: ["doce","vegetariano"] },
  ceia5: { nome: "Vitamina de banana com aveia", categoria: 'ceia', itens: [{ a: 'leite', q: [200, 250, 250, 200] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'aveia', q: [15, 10, 20, 10] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Quebre a banana em pedaços e coloque no liquidificador com o leite e a aveia.","Bata por 40 segundos, até ficar liso.","Deixe descansar 1 minuto: a aveia engrossa e a vitamina fica mais cremosa.","Beba devagar, uns 30 minutos antes de dormir."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  pre6: { nome: "Maçã com pasta de amendoim", categoria: 'pre', itens: [{ a: 'macaFruta', q: [1, 1, 1, 1] }, { a: 'pastaAmendoim', q: [15, 20, 20, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Lave a maçã e corte em gomos, sem tirar a casca.","Passe a pasta de amendoim em cada gomo ou use como molho.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre7: { nome: "Tapioca com mel", categoria: 'pre', itens: [{ a: 'tapioca', q: [50, 60, 60, 50] }, { a: 'mel', q: [15, 15, 15, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Tapioca na frigideira seca, 1 minuto de cada lado.", tempo: 4, passos: ["Aqueça uma frigideira antiaderente em fogo médio, sem óleo.","Espalhe a goma de tapioca em camada fina e uniforme.","Espere 1 minuto, vire e deixe mais 1 minuto até firmar.","Regue com o mel e dobre ao meio.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre8: { nome: "Torradas com geleia", categoria: 'pre', itens: [{ a: 'torrada', q: [3, 3, 3, 3] }, { a: 'geleia', q: [20, 30, 35, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Passe a geleia sobre as torradas.","Coma em seguida, para manter o crocante.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre9: { nome: "Banana com granola", categoria: 'pre', itens: [{ a: 'banana', q: [1, 1, 1, 1] }, { a: 'granola', q: [20, 25, 30, 20] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Descasque a banana e corte em rodelas em uma tigela.","Cubra com a granola.","Coma na hora, para a granola ficar crocante.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre10: { nome: "Iogurte com mel", categoria: 'pre', itens: [{ a: 'iogurte', q: [200, 210, 230, 180] }, { a: 'mel', q: [20, 25, 25, 20] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Coloque o iogurte em um copo ou tigela.","Regue com o mel e mexa.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre11: { nome: "Vitamina de mamão", categoria: 'pre', itens: [{ a: 'leite', q: [150, 150, 150, 150] }, { a: 'mamao', q: [110, 120, 140, 80] }, { a: 'mel', q: [10, 15, 15, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata tudo junto, com os pós.", tempo: 4, passos: ["Coloque o leite, o mamão e o mel no liquidificador.","Junte a beterraba e o guaraná em pó no liquidificador.","Bata por 40 segundos até ficar liso.","Beba na hora."], etiquetas: ["doce","vegetariano"] },
  pre12: { nome: "Pão francês com geleia", categoria: 'pre', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'geleia', q: [5, 15, 20, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Abra o pão francês ao meio.","Passe a geleia nas duas metades e feche.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre13: { nome: "Cuscuz com manteiga", categoria: 'pre', itens: [{ a: 'cuscuz', q: [110, 130, 140, 110] }, { a: 'manteiga', q: [5, 5, 5, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Cuscuz de micro-ondas: 3 minutos.", tempo: 5, passos: ["Coloque o cuscuz em um pote próprio para micro-ondas.","Leve ao micro-ondas por 3 minutos.","Junte a manteiga e mexa com um garfo até derreter.","Salgue a gosto e coma quente.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"] },
  pre14: { nome: "Bisnaguinha com requeijão", categoria: 'pre', itens: [{ a: 'bisnaguinha', q: [2, 2, 2, 2] }, { a: 'requeijao', q: [20, 25, 30, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Abra as bisnaguinhas ao meio.","Passe o requeijão nas duas metades.","Feche e coma.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["salgado","vegetariano"], temperos: ["água"] },
  pre15: { nome: "Suco de laranja com torradas", categoria: 'pre', itens: [{ a: 'sucoLaranja', q: [150, 200, 250, 150] }, { a: 'torrada', q: [3, 3, 3, 3] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Os pós vão dentro do suco.", tempo: 3, passos: ["Coloque o suco de laranja em um copo.","Misture a beterraba e o guaraná em pó dentro do suco.","Beba o suco e coma as torradas em seguida."], etiquetas: ["doce","vegetariano"] },
  pre16: { nome: "Banana com doce de leite", categoria: 'pre', itens: [{ a: 'banana', q: [1, 1, 1, 1] }, { a: 'doceLeite', q: [30, 35, 40, 25] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Descasque a banana e corte ao meio no sentido do comprimento.","Espalhe o doce de leite sobre as metades.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre17: { nome: "Cereal com leite", categoria: 'pre', itens: [{ a: 'cerealMatinal', q: [30, 25, 30, 25] }, { a: 'leite', q: [100, 150, 150, 100] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Coloque o cereal em uma tigela.","Cubra com o leite gelado.","Coma na hora, para o cereal não amolecer.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre18: { nome: "Vitamina rápida de morango", categoria: 'pre', itens: [{ a: 'leite', q: [150, 200, 200, 150] }, { a: 'morango', q: [90, 110, 140, 110] }, { a: 'mel', q: [15, 10, 10, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata tudo junto, com os pós.", tempo: 4, passos: ["Lave o morango e tire as folhinhas.","Coloque o leite, o morango e o mel no liquidificador.","Junte a beterraba e o guaraná em pó no liquidificador.","Bata por 40 segundos e beba."], etiquetas: ["doce","vegetariano"] },
  pre19: { nome: "Biscoito maisena com leite", categoria: 'pre', itens: [{ a: 'maisena', q: [25, 20, 25, 20] }, { a: 'leite', q: [100, 150, 150, 100] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Coloque o leite em um copo.","Mergulhe o biscoito maisena no leite e coma aos poucos.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre20: { nome: "Pão de forma com pasta de amendoim", categoria: 'pre', itens: [{ a: 'paoForma', q: [1, 1, 1, 1] }, { a: 'pastaAmendoim', q: [15, 20, 20, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Passe a pasta de amendoim na fatia de pão de forma.","Dobre o pão ao meio.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre21: { nome: "Manga com iogurte", categoria: 'pre', itens: [{ a: 'manga', q: [150, 170, 180, 130] }, { a: 'iogurte', q: [110, 120, 130, 120] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Corte a manga em cubos e coloque em uma tigela.","Junte o iogurte e mexa.","Coma de colher.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre22: { nome: "Torradas com requeijão", categoria: 'pre', itens: [{ a: 'torrada', q: [3, 3, 3, 3] }, { a: 'requeijao', q: [20, 30, 30, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Passe o requeijão sobre as torradas.","Coma em seguida, para manter o crocante.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["salgado","vegetariano"], temperos: ["água"] },
  pre23: { nome: "Paçoca com leite", categoria: 'pre', itens: [{ a: 'pacoca', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 150, 150, 100] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Esmigalhe a paçoca dentro de um copo.","Junte o leite e mexa para dissolver.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre24: { nome: "Barra de cereal e suco", categoria: 'pre', itens: [{ a: 'barraCereal', q: [1, 1, 1, 1] }, { a: 'sucoLaranja', q: [250, 300, 300, 200] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Os pós vão dentro do suco.", tempo: 3, passos: ["Misture a beterraba e o guaraná em pó no suco de laranja.","Beba o suco.","Coma a barra de cereal em seguida."], etiquetas: ["doce","vegetariano"] },
  pre25: { nome: "Tapioca com banana", categoria: 'pre', itens: [{ a: 'tapioca', q: [40, 40, 50, 30] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Banana amassada como recheio.", tempo: 5, passos: ["Aqueça uma frigideira antiaderente em fogo médio, sem óleo.","Espalhe a goma de tapioca em camada fina e deixe 1 minuto de cada lado.","Amasse a banana com um garfo e espalhe sobre a tapioca.","Dobre ao meio e coma.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre26: { nome: "Mingau rápido de Farinha Láctea", categoria: 'pre', itens: [{ a: 'leite', q: [150, 150, 150, 150] }, { a: 'farinhaLactea', q: [20, 25, 25, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Leite morno, mexa e beba.", tempo: 4, passos: ["Esquente o leite no micro-ondas por 1 minuto.","Junte a Farinha Láctea e mexa com uma colher até desmanchar.","Espere 1 minuto para engrossar.","Misture a beterraba e o guaraná em pó no mingau e mexa bem."], etiquetas: ["doce","vegetariano"] },
  pre27: { nome: "Torradas com manteiga e mel", categoria: 'pre', itens: [{ a: 'torrada', q: [3, 3, 3, 3] }, { a: 'manteiga', q: [5, 5, 10, 5] }, { a: 'mel', q: [5, 10, 5, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Passe a manteiga fina nas torradas.","Regue com o mel.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre28: { nome: "Vitamina rápida de abacate", categoria: 'pre', itens: [{ a: 'leite', q: [150, 150, 200, 150] }, { a: 'abacate', q: [40, 50, 30, 35] }, { a: 'mel', q: [10, 15, 15, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata tudo junto, com os pós.", tempo: 4, passos: ["Tire a polpa do abacate com uma colher.","Coloque no liquidificador com o leite e o mel.","Junte a beterraba e o guaraná em pó no liquidificador.","Bata por 40 segundos até ficar cremoso e beba."], etiquetas: ["doce","vegetariano"] },
  pre29: { nome: "Aveia com leite e mel", categoria: 'pre', itens: [{ a: 'leite', q: [150, 150, 150, 150] }, { a: 'aveia', q: [15, 20, 20, 10] }, { a: 'mel', q: [5, 5, 10, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Deixe a aveia amolecer 2 minutos.", tempo: 5, passos: ["Coloque o leite e a aveia em uma tigela própria para micro-ondas.","Leve ao micro-ondas por 1 minuto e meio e mexa.","Junte o mel e deixe a aveia amolecer por 2 minutos.","Coma de colher.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre30: { nome: "Biscoito cream cracker com geleia", categoria: 'pre', itens: [{ a: 'creamCracker', q: [25, 30, 30, 25] }, { a: 'geleia', q: [25, 20, 25, 20] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Beterraba e guaraná em pó em meio copo de água.", tempo: 3, passos: ["Passe a geleia sobre os biscoitos cream cracker.","Monte como mini sanduíches, se quiser.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  cafe7: { nome: "Tapioca com ovo e queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'tapioca', q: [50, 60, 70, 40] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [150, 200, 200, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Espalhe a goma de tapioca em frigideira antiaderente seca, em fogo médio, formando um disco.","Quando firmar, 1 minuto, vire por mais 30 segundos.","Em outra frigideira, frite o ovo com uma pitada de sal.","Recheie a tapioca com o ovo e a mussarela, dobre e deixe 1 minuto para derreter.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe8: { nome: "Cuscuz com ovos e shake de whey", categoria: 'cafe', itens: [{ a: 'cuscuz', q: [140, 150, 150, 110] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'leite', q: [100, 150, 200, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Misture o flocão com uma pitada de sal e água suficiente para umedecer, cerca de meio copo; deixe 2 minutos.","Cozinhe no micro-ondas em pote tampado por 3 minutos.","Mexa os ovos na frigideira antiaderente em fogo baixo por 2 a 3 minutos.","Sirva o cuscuz com os ovos por cima.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"] },
  cafe9: { nome: "Pão com queijo minas e shake de whey", categoria: 'cafe', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'minas', q: [35, 40, 40, 35] }, { a: 'leite', q: [200, 250, 300, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 6, passos: ["Abra o pão francês ao meio e aqueça na frigideira ou na sanduicheira por 1 minuto.","Recheie com o queijo minas em fatias.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"] },
  cafe10: { nome: "Mingau de aveia com whey", categoria: 'cafe', itens: [{ a: 'leite', q: [250, 300, 350, 250] }, { a: 'aveia', q: [35, 40, 40, 25] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina entram com o mingau já morno, para não empelotar.", tempo: 8, passos: ["Aqueça o leite no micro-ondas por 2 minutos, sem ferver.","Misture a aveia e cozinhe mais 1 minuto, mexendo.","Deixe amornar 2 minutos e junte o whey e a creatina, mexendo bem.","Corte a banana por cima."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  cafe11: { nome: "Omelete de presunto e queijo com torradas", categoria: 'cafe', itens: [{ a: 'ovo', q: [2, 2, 2, 2] }, { a: 'presunto', q: [2, 2, 2, 2] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'torrada', q: [1, 1, 1, 1] }, { a: 'leite', q: [150, 200, 250, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Bata os ovos com uma pitada de sal.","Despeje em frigideira antiaderente em fogo médio e distribua o presunto picado e a mussarela.","Dobre a omelete quando firmar por baixo e tampe por 1 minuto.","Torre a torrada.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal"] },
  cafe12: { nome: "Pão com peito de peru e shake de whey", categoria: 'cafe', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'requeijao', q: [15, 10, 10, 15] }, { a: 'peitoPeru', q: [3, 3, 3, 3] }, { a: 'leite', q: [250, 350, 400, 200] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 6, passos: ["Passe o requeijão nas fatias de pão.","Distribua o peito de peru e feche o sanduíche.","Se quiser quente, aqueça 3 minutos na sanduicheira.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"] },
  cafe13: { nome: "Iogurte com granola, banana e whey", categoria: 'cafe', itens: [{ a: 'iogurte', q: [220, 240, 210, 210] }, { a: 'granola', q: [40, 50, 60, 35] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina misturados no iogurte.", tempo: 5, passos: ["Misture o whey e a creatina no iogurte até ficar liso.","Corte a banana em rodelas.","Monte no pote: iogurte, banana e granola por cima, para não amolecer."], etiquetas: ["doce","vegetariano"] },
  cafe14: { nome: "Crepioca de queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'tapioca', q: [35, 40, 40, 20] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'queijoPrato', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 150, 200, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Ovo batido com a goma, na frigideira.", tempo: 10, passos: ["Misture a goma de tapioca com os ovos e uma pitada de sal.","Despeje em frigideira antiaderente em fogo médio e espalhe em disco.","Quando firmar embaixo, 2 minutos, ponha o queijo prato, dobre e deixe 1 minuto.","Bata o shake de whey e creatina no leite e beba junto."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe15: { nome: "Torradas com ovos mexidos e shake de whey", categoria: 'cafe', itens: [{ a: 'torrada', q: [4, 4, 4, 4] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'leite', q: [100, 200, 250, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Bata os ovos com uma pitada de sal.","Mexa na frigideira antiaderente em fogo baixo por 2 a 3 minutos.","Torre as torradas e sirva os ovos por cima.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe16: { nome: "Vitamina de morango com whey e aveia", categoria: 'cafe', itens: [{ a: 'leite', q: [300, 350, 350, 300] }, { a: 'morango', q: [130, 200, 230, 160] }, { a: 'aveia', q: [35, 35, 40, 25] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Bata tudo no liquidificador.", tempo: 4, passos: ["Lave os morangos e tire as folhas.","Coloque no liquidificador o leite, os morangos, a aveia e o whey.","Bata por 40 segundos e junte a creatina por último."], etiquetas: ["doce","vegetariano"] },
  cafe17: { nome: "Pão na chapa e shake de whey com achocolatado", categoria: 'cafe', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'manteiga', q: [5, 5, 10, 5] }, { a: 'leite', q: [200, 300, 250, 200] }, { a: 'achocolatado', q: [15, 10, 15, 5] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 8, passos: ["Abra o pão francês ao meio e passe a manteiga nas duas metades.","Doure na frigideira antiaderente em fogo médio, com o lado da manteiga para baixo, por 2 minutos.","Bata no liquidificador o leite, o achocolatado, o whey e a creatina.","Sirva o pão quente com o shake."], etiquetas: ["salgado","vegetariano"] },
  cafe18: { nome: "Sanduíche de ovo e queijo prato e shake de whey", categoria: 'cafe', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'queijoPrato', q: [1, 1, 1, 1] }, { a: 'leite', q: [150, 250, 300, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Frite o ovo em frigideira antiaderente com uma pitada de sal.","Monte o sanduíche com o ovo e o queijo prato entre as fatias de pão.","Leve à sanduicheira por 3 minutos, até o queijo derreter.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe19: { nome: "Cereal com leite, banana e whey", categoria: 'cafe', itens: [{ a: 'cerealMatinal', q: [35, 40, 50, 25] }, { a: 'leite', q: [250, 300, 300, 250] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite antes de pôr o cereal.", tempo: 5, passos: ["Bata o leite com o whey e a creatina até dissolver.","Despeje numa tigela e junte o cereal.","Corte a banana por cima e coma na hora, para o cereal não amolecer."], etiquetas: ["doce","vegetariano"] },
  cafe20: { nome: "Vitamina de abacate com whey", categoria: 'cafe', itens: [{ a: 'leite', q: [400, 450, 500, 400] }, { a: 'abacate', q: [70, 80, 80, 60] }, { a: 'mel', q: [15, 20, 20, 10] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Bata tudo no liquidificador.", tempo: 4, passos: ["Tire a polpa do abacate e coloque no liquidificador.","Junte o leite, o mel e o whey.","Bata por 40 segundos e acrescente a creatina por último."], etiquetas: ["doce","vegetariano"] },
  cafe21: { nome: "Bolo simples, banana e shake de whey", categoria: 'cafe', itens: [{ a: 'bolo', q: [1, 1, 1, 1] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'leite', q: [150, 250, 300, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 5, passos: ["Bata o leite com o whey e a creatina por 20 segundos.","Sirva a fatia de bolo e a banana ao lado.","Coma e beba o shake em seguida."], etiquetas: ["doce","vegetariano"] },
  cafe22: { nome: "Cuscuz com queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'cuscuz', q: [140, 170, 180, 110] }, { a: 'minas', q: [30, 35, 30, 30] }, { a: 'leite', q: [200, 200, 250, 200] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Misture o flocão com uma pitada de sal e meio copo de água; deixe 2 minutos.","Cozinhe no micro-ondas em pote tampado por 3 minutos.","Corte o queijo minas em cubos e misture ao cuscuz quente para amolecer.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"] },
  cafe23: { nome: "Pão de queijo com ovo e shake de whey", categoria: 'cafe', itens: [{ a: 'paoQueijo', q: [2, 2, 2, 2] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 200, 250, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 14, passos: ["Leve os pães de queijo à airfryer a 180 graus por 8 minutos, ou ao forno a 200 graus por 12 minutos, se forem congelados.","Frite o ovo em frigideira antiaderente com uma pitada de sal.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos.","Coma o ovo com os pães de queijo e o shake."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe24: { nome: "Mingau de Mucilon com whey", categoria: 'cafe', itens: [{ a: 'leite', q: [250, 300, 350, 250] }, { a: 'mucilon', q: [35, 40, 40, 25] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina entram com o mingau já morno.", tempo: 8, passos: ["Aqueça o leite no micro-ondas por 2 minutos, sem ferver.","Misture o Mucilon e cozinhe mais 1 minuto, mexendo.","Deixe amornar 2 minutos e junte o whey e a creatina, mexendo bem.","Corte a banana por cima."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  cafe25: { nome: "Bisnaguinhas com presunto e queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'bisnaguinha', q: [3, 3, 3, 3] }, { a: 'presunto', q: [2, 2, 2, 2] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [150, 200, 250, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 8, passos: ["Abra as bisnaguinhas ao meio.","Recheie cada uma com presunto e mussarela.","Leve à sanduicheira por 2 a 3 minutos, ou aqueça no micro-ondas por 20 segundos.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"] },
  cafe26: { nome: "Vitamina de mamão, aveia e whey", categoria: 'cafe', itens: [{ a: 'leite', q: [300, 300, 350, 300] }, { a: 'mamao', q: [150, 170, 170, 120] }, { a: 'aveia', q: [30, 40, 40, 25] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Bata tudo no liquidificador.", tempo: 4, passos: ["Corte o mamão em cubos, sem casca nem sementes.","Coloque no liquidificador com o leite, a aveia e o whey.","Bata por 40 segundos e junte a creatina por último."], etiquetas: ["doce","vegetariano"] },
  cafe27: { nome: "Wrap de ovo e queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'wrap', q: [1, 1, 1, 1] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [150, 250, 300, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Frite o ovo em frigideira antiaderente com uma pitada de sal.","Aqueça o disco de wrap 20 segundos na frigideira.","Coloque o ovo e a mussarela no centro, dobre e deixe 1 minuto para derreter.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe28: { nome: "Pão com pasta de amendoim, banana e shake de whey", categoria: 'cafe', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'pastaAmendoim', q: [10, 15, 15, 10] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'leite', q: [150, 200, 250, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 6, passos: ["Torre as fatias de pão, se quiser.","Passe a pasta de amendoim e coloque a banana em rodelas.","Feche o sanduíche.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["doce","vegetariano"] },
  cafe29: { nome: "Iogurte batido com whey, banana e mel", categoria: 'cafe', itens: [{ a: 'iogurte', q: [270, 330, 350, 280] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'mel', q: [15, 15, 15, 10] }, { a: 'aveia', q: [25, 30, 35, 20] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Bata tudo no liquidificador.", tempo: 5, passos: ["Coloque no liquidificador o iogurte, a banana, o mel, a aveia e o whey.","Bata por 40 segundos.","Junte a creatina por último e bata mais 5 segundos."], etiquetas: ["doce","vegetariano"] },
  cafe30: { nome: "Ovos mexidos com queijo, torradas e shake de whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [2, 2, 2, 2] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'torrada', q: [2, 2, 2, 2] }, { a: 'leite', q: [100, 200, 250, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Whey e creatina batidos no leite.", tempo: 10, passos: ["Bata os ovos com uma pitada de sal.","Mexa na frigideira antiaderente em fogo baixo e, quando estiver quase firme, junte a mussarela picada.","Torre as torradas e sirva os ovos por cima.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  lanche12: { nome: "Maçã com amendoim", categoria: 'lanche', itens: [{ a: 'macaFruta', q: [1, 1, 1, 1] }, { a: 'amendoim', q: [25, 30, 35, 25] }], preparo: "Amendoim num potinho.", tempo: 3, passos: ["Lave a maçã e seque bem.","Coloque o amendoim em um potinho com tampa.","Leve a maçã inteira na mochila."], etiquetas: ["doce","vegetariano"], levar: "Aguenta o dia todo na mochila, sem geladeira." },
  lanche13: { nome: "Barra de cereal e iogurte", categoria: 'lanche', itens: [{ a: 'barraCereal', q: [1, 1, 1, 1] }, { a: 'iogurte', q: [280, 340, 380, 250] }], preparo: "Iogurte de garrafinha.", tempo: 2, passos: ["Coloque o iogurte de garrafinha na bolsa térmica.","Leve a barra de cereal separada, na mochila.","Na hora, coma a barra junto com o iogurte."], etiquetas: ["doce","vegetariano"], levar: "Iogurte na geladeira do trabalho ou na bolsa com gelo. Barra na mochila." },
  lanche14: { nome: "Sanduíche de peito de peru e requeijão", categoria: 'lanche', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'peitoPeru', q: [3, 3, 3, 3] }, { a: 'requeijao', q: [20, 35, 40, 15] }], preparo: "Monte em casa e leve embrulhado.", tempo: 5, passos: ["Passe o requeijão em uma fatia de pão de forma.","Cubra com o peito de peru dobrado.","Feche com a outra fatia.","Embrulhe apertado em papel alumínio."], etiquetas: ["salgado"], levar: "Embrulhado, aguenta 3 horas na mochila. Depois disso, geladeira do trabalho." },
  lanche15: { nome: "Bisnaguinhas com requeijão", categoria: 'lanche', itens: [{ a: 'bisnaguinha', q: [3, 3, 3, 3] }, { a: 'requeijao', q: [20, 30, 40, 15] }], preparo: "Já recheadas, num pote.", tempo: 5, passos: ["Abra cada bisnaguinha ao meio sem separar as metades.","Passe requeijão no miolo de cada uma.","Feche e arrume em um pote com tampa."], etiquetas: ["salgado","vegetariano"], levar: "Pote fechado, aguenta 3 horas na mochila. Depois, geladeira do trabalho." },
  lanche16: { nome: "Paçoca e leite", categoria: 'lanche', itens: [{ a: 'pacoca', q: [1, 1, 1, 1] }, { a: 'leite', q: [200, 250, 300, 200] }], preparo: "Leite em garrafa térmica.", tempo: 3, passos: ["Despeje o leite gelado na garrafa térmica.","Embrulhe a paçoca no próprio papel dentro de um pote.","Na hora, esfarele a paçoca no leite ou coma ao lado."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica com leite gelado. Paçoca na mochila." },
  lanche17: { nome: "Iogurte com granola", categoria: 'lanche', itens: [{ a: 'iogurte', q: [160, 180, 220, 170] }, { a: 'granola', q: [35, 40, 40, 30] }], preparo: "Granola separada, mistura na hora.", tempo: 3, passos: ["Coloque o iogurte em um pote com tampa.","Ponha a granola em um potinho separado, para não amolecer.","Na hora, misture a granola no iogurte."], etiquetas: ["doce","vegetariano"], levar: "Iogurte na geladeira do trabalho. Granola em potinho na mochila." },
  lanche18: { nome: "Bolo simples e suco", categoria: 'lanche', itens: [{ a: 'bolo', q: [1, 1, 1, 1] }, { a: 'sucoLaranja', q: [150, 200, 300, 100] }], preparo: "Fatia embrulhada em papel.", tempo: 5, passos: ["Corte uma fatia de bolo simples e embrulhe em papel alumínio.","Esprema 1 laranja num copinho com tampa.","Feche bem o copinho."], etiquetas: ["doce","vegetariano"], levar: "Bolo embrulhado na mochila. Suco na geladeira do trabalho, bebido no mesmo dia." },
  lanche19: { nome: "Torradas com queijo minas", categoria: 'lanche', itens: [{ a: 'torrada', q: [3, 3, 3, 3] }, { a: 'minas', q: [40, 60, 60, 40] }], preparo: "Queijo em fatias num pote.", tempo: 3, passos: ["Corte o queijo minas em fatias finas.","Guarde o queijo em um pote com tampa.","Coloque as torradas em outro pote, para não amolecerem.","Na hora, monte cada torrada com uma fatia de queijo."], etiquetas: ["salgado","vegetariano"], levar: "Queijo na geladeira do trabalho. Torradas em pote fechado na mochila." },
  lanche20: { nome: "Wrap de frango", categoria: 'lanche', itens: [{ a: 'wrap', q: [1, 1, 1, 1] }, { a: 'frango', q: [60, 70, 80, 50] }, { a: 'requeijao', q: [5, 15, 15, 10] }], preparo: "Frango desfiado com requeijão, enrolado e embrulhado.", tempo: 10, passos: ["Desfie o frango e misture com o requeijão e uma pitada de sal.","Espalhe sobre o disco de wrap, deixando uma borda livre.","Dobre as laterais e enrole bem apertado.","Embrulhe em papel alumínio."], etiquetas: ["salgado"], temperos: ["sal"], levar: "Embrulhado, na geladeira do trabalho se passar de 3 horas. Come frio." },
  lanche21: { nome: "Banana com doce de leite e leite", categoria: 'lanche', itens: [{ a: 'banana', q: [1, 1, 1, 1] }, { a: 'doceLeite', q: [30, 30, 35, 25] }, { a: 'leite', q: [100, 150, 150, 100] }], preparo: "Doce de leite num potinho.", tempo: 3, passos: ["Despeje o leite na garrafa térmica.","Coloque o doce de leite em um potinho com tampa.","Leve a banana inteira.","Na hora, passe o doce de leite na banana em pedaços."], etiquetas: ["doce","vegetariano"], levar: "Leite em garrafa térmica gelada, doce no potinho. Banana inteira na mochila." },
  lanche22: { nome: "Vitamina de morango na garrafa", categoria: 'lanche', itens: [{ a: 'leite', q: [250, 300, 300, 250] }, { a: 'morango', q: [100, 100, 170, 110] }, { a: 'mel', q: [15, 15, 15, 10] }], preparo: "Bata de manhã e leve em garrafa térmica.", tempo: 5, passos: ["Bata o leite, o morango lavado e o mel no liquidificador por 40 segundos.","Passe pela peneira se quiser sem sementes.","Despeje na garrafa térmica gelada e feche bem."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica com gelo por dentro ou bolsa térmica. Beba em até 4 horas." },
  lanche23: { nome: "Sanduíche de mortadela", categoria: 'lanche', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'mortadela', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [25, 35, 40, 20] }], preparo: "Monte em casa e leve embrulhado.", tempo: 5, passos: ["Passe o requeijão em uma fatia de pão de forma.","Cubra com a mortadela.","Feche com a outra fatia.","Embrulhe em papel alumínio."], etiquetas: ["salgado"], levar: "Embrulhado, aguenta 3 horas na mochila. Depois, geladeira do trabalho." },
  lanche24: { nome: "Biscoito maisena e iogurte", categoria: 'lanche', itens: [{ a: 'maisena', q: [30, 35, 35, 25] }, { a: 'iogurte', q: [190, 210, 240, 200] }], preparo: "Iogurte de garrafinha.", tempo: 2, passos: ["Coloque o iogurte na bolsa térmica.","Leve o biscoito maisena em um pote fechado.","Na hora, coma o biscoito com o iogurte."], etiquetas: ["doce","vegetariano"], levar: "Iogurte na geladeira do trabalho ou na bolsa com gelo. Biscoito em pote na mochila." },
  lanche25: { nome: "Pão com doce de leite", categoria: 'lanche', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'doceLeite', q: [25, 35, 40, 20] }], preparo: "Monte em casa e leve embrulhado.", tempo: 3, passos: ["Abra o pão francês ao meio.","Passe o doce de leite nas duas metades.","Feche e embrulhe em papel alumínio."], etiquetas: ["doce","vegetariano"], levar: "Embrulhado, aguenta o dia todo na mochila." },
  lanche26: { nome: "Queijo com goiabada e torradas", categoria: 'lanche', itens: [{ a: 'minas', q: [25, 30, 40, 30] }, { a: 'goiabada', q: [30, 35, 35, 20] }, { a: 'torrada', q: [2, 2, 2, 2] }], preparo: "Queijo e goiabada em cubos, num pote.", tempo: 5, passos: ["Corte o queijo minas e a goiabada em cubos.","Arrume em um pote com tampa, alternando queijo e goiabada.","Coloque as torradas em outro pote.","Na hora, monte as torradas com queijo e goiabada."], etiquetas: ["doce","vegetariano"], levar: "Pote com queijo e goiabada na geladeira do trabalho. Torradas em pote fechado." },
  lanche27: { nome: "Vitamina de abacate na garrafa", categoria: 'lanche', itens: [{ a: 'leite', q: [250, 250, 300, 250] }, { a: 'abacate', q: [30, 50, 50, 35] }, { a: 'mel', q: [15, 20, 15, 10] }], preparo: "Bata de manhã e leve em garrafa térmica.", tempo: 5, passos: ["Bata o leite, o abacate maduro e o mel no liquidificador por 40 segundos.","Despeje na garrafa térmica gelada.","Feche bem e beba até no máximo 4 horas depois."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica com gelo ou bolsa térmica. Abacate escurece com o tempo, então beba cedo." },
  lanche28: { nome: "Amendoim com banana", categoria: 'lanche', itens: [{ a: 'amendoim', q: [25, 30, 35, 25] }, { a: 'banana', q: [1, 1, 1, 1] }], preparo: "O lanche mais fácil de carregar.", tempo: 2, passos: ["Coloque o amendoim em um potinho com tampa.","Leve a banana inteira, com casca.","Na hora, coma a banana alternando com o amendoim."], etiquetas: ["doce","vegetariano"], levar: "Aguenta o dia todo na mochila, sem geladeira." },
  lanche29: { nome: "Cuscuz com ovo no pote", categoria: 'lanche', itens: [{ a: 'cuscuz', q: [140, 170, 180, 130] }, { a: 'ovo', q: [1, 1, 1, 1] }], preparo: "Ovo cozido picado por cima.", tempo: 15, passos: ["Hidrate o cuscuz com água quente e uma pitada de sal; ele já deve estar pronto do dia anterior ou de domingo.","Cozinhe o ovo em água fervente por 10 minutos.","Esfrie, descasque e pique o ovo.","Coloque o cuscuz no pote e cubra com o ovo picado."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"], levar: "Pote fechado na geladeira do trabalho. Come frio ou morno, e consome em até 4 horas." },
  lanche30: { nome: "Pão com presunto e requeijão", categoria: 'lanche', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'presunto', q: [2, 2, 2, 2] }, { a: 'requeijao', q: [20, 30, 40, 15] }], preparo: "Monte em casa e leve embrulhado.", tempo: 5, passos: ["Passe o requeijão no pão francês aberto ao meio.","Recheie com as fatias de presunto.","Feche e embrulhe em papel alumínio."], etiquetas: ["salgado"], levar: "Embrulhado, aguenta 3 horas na mochila. Depois, geladeira do trabalho." },
  almoco12: { nome: "Arroz, frango grelhado e batata", categoria: 'almoco', itens: [{ a: 'arroz', q: [230, 260, 270, 190] }, { a: 'frango', q: [130, 140, 150, 160] }, { a: 'batata', q: [230, 260, 280, 200] }], preparo: "Frango em tiras, batata em cubos assada.", receita: 'frangoDaSemana', tempo: 40, passos: ["Arroz da semana e frango grelhado: veja o preparo de domingo.","Gomos de batata com sal e páprica na airfryer a 200 graus por 20 a 25 minutos, sacudindo na metade.","Corte o frango em tiras e deixe esfriar com a batata, tampa aberta.","Monte os potes com arroz, frango e batata."], etiquetas: ["salgado","marmita"], temperos: ["sal","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta, mexendo na metade.", airfryer: "Batata em gomos na airfryer a 200 graus por 20 a 25 minutos." },
  almoco13: { nome: "Arroz com linguiça e ovo", categoria: 'almoco', itens: [{ a: 'arroz', q: [260, 290, 300, 200] }, { a: 'linguica', q: [90, 100, 110, 110] }, { a: 'ovo', q: [1, 1, 1, 1] }], preparo: "Linguiça em rodelas, ovo cozido.", receita: 'arrozDaSemana', tempo: 35, passos: ["Cozinhe o arroz da semana: veja o preparo de domingo.","Corte a linguiça em rodelas e doure em frigideira antiaderente por 6 minutos, no próprio óleo dela.","Cozinhe os ovos por 9 minutos, passe em água gelada e descasque.","Misture a linguiça ao arroz e divida nos potes. Ovo cozido por cima."], etiquetas: ["salgado","marmita"], temperos: ["sal","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta.", airfryer: "A linguiça também fica boa na airfryer a 180 graus por 10 minutos." },
  almoco14: { nome: "Nhoque à bolonhesa", categoria: 'almoco', itens: [{ a: 'nhoque', q: [210, 250, 260, 180] }, { a: 'moida', q: [70, 70, 80, 90] }, { a: 'molhoTomate', q: [70, 60, 60, 50] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Molho por cima só na hora de esquentar.", receita: 'bolonhesa', tempo: 35, passos: ["Molho à bolonhesa: veja o preparo de domingo.","Cozinhe o nhoque em água fervente com sal até boiar, cerca de 2 minutos. Escorra e passe em água fria.","Divida o nhoque nos potes, sem misturar com o molho.","Ponha a mussarela sobre o nhoque e o molho em um potinho separado, com tampa. Feche e leve."], etiquetas: ["salgado","marmita"], temperos: ["sal","água"], levar: "Pote na geladeira do trabalho. Na hora de esquentar, despeje o molho sobre o nhoque e leve ao micro-ondas por 2 minutos e meio, tampa entreaberta; o molho por cima evita o nhoque ressecar." },
  almoco15: { nome: "Arroz, carne de panela e batata", categoria: 'almoco', itens: [{ a: 'arroz', q: [230, 250, 270, 180] }, { a: 'carnePanela', q: [110, 120, 130, 140] }, { a: 'batata', q: [220, 260, 250, 190] }], preparo: "Carne e batata cozidas juntas na pressão, 25 minutos.", receita: 'arrozDaSemana', tempo: 55, passos: ["Arroz da semana e carne de panela: veja o preparo de domingo. A carne e a batata podem cozinhar juntas na panela de pressão.","Panela de pressão: carne, batata em cubos, sal, alho em pó e água até cobrir. Depois da pressão, 25 minutos.","Desfie a carne e reserve um pouco do caldo.","Monte os potes com arroz, carne e batata, e regue com uma colher do caldo para não ressecar."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","cominho","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco16: { nome: "Frango à milanesa com arroz e purê", categoria: 'almoco', itens: [{ a: 'milanesaFrango', q: [100, 110, 120, 130] }, { a: 'arroz', q: [170, 200, 200, 140] }, { a: 'pure', q: [180, 190, 210, 130] }], preparo: "Milanesa assada na airfryer, sem fritar.", receita: 'pureBatata', tempo: 45, passos: ["Purê de batata e arroz da semana: veja o preparo de domingo.","Passe a milanesa de frango na airfryer a 200 graus por 12 minutos, virando na metade.","Deixe esfriar em grade, para não amolecer.","Monte os potes com arroz e purê de um lado e a milanesa em cima. Se preferir crocante, leve a milanesa em outro pote."], etiquetas: ["salgado","marmita"], temperos: ["sal"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta; a milanesa amolece um pouco, mas continua boa.", airfryer: "Milanesa de frango na airfryer a 200 graus por 12 minutos, virando na metade." },
  almoco17: { nome: "Lombo assado com arroz e batata", categoria: 'almoco', itens: [{ a: 'lombo', q: [110, 120, 130, 130] }, { a: 'arroz', q: [220, 240, 250, 180] }, { a: 'batata', q: [210, 250, 260, 190] }], preparo: "Lombo fatiado fino depois de frio.", receita: 'arrozDaSemana', tempo: 70, passos: ["Tempere o lombo com sal, alho em pó e páprica. Forno a 200 graus por 50 minutos, coberto com papel-alumínio nos primeiros 30.","Gomos de batata com sal na assadeira ao lado nos últimos 30 minutos.","Deixe o lombo esfriar por 15 minutos e fatie fino, com a faca bem afiada.","Arroz da semana: veja o preparo de domingo.","Monte os potes com arroz, fatias de lombo e batata."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta." },
  almoco18: { nome: "Macarrão ao molho branco com frango", categoria: 'almoco', itens: [{ a: 'macarrao', q: [250, 270, 290, 200] }, { a: 'frango', q: [80, 90, 100, 110] }, { a: 'cremeLeite', q: [15, 25, 20, 20] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Creme de leite e queijo derretidos sobre o frango.", tempo: 40, passos: ["Cozinhe o macarrão em água com sal, 2 minutos a menos que o tempo da embalagem. Escorra.","Frigideira antiaderente: frango em cubos, sal e alho em pó, 6 minutos, mexendo.","Baixe o fogo, junte o creme de leite e a metade da mussarela picada e mexa até derreter.","Misture o molho ao macarrão e divida nos potes, com o resto da mussarela por cima."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade. Se estiver seco, 1 colher de água." },
  almoco19: { nome: "Arroz carreteiro", categoria: 'almoco', itens: [{ a: 'arroz', q: [300, 330, 360, 240] }, { a: 'carnePanela', q: [90, 100, 110, 120] }, { a: 'calabresa', q: [20, 25, 20, 20] }], preparo: "Carne desfiada e calabresa refogadas com o arroz.", tempo: 50, passos: ["Em panela média, doure a carne de panela desfiada e a calabresa picada por 5 minutos.","Junte o arroz cozido, sal, alho em pó, cominho e 1 copo de água. Mexa por 5 minutos, até secar.","Corrija o sal e acerte a água: o carreteiro deve ficar úmido, não seco.","Divida nos potes e deixe esfriar antes de tampar."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","cominho","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta, mexendo na metade." },
  almoco20: { nome: "Polenta com molho de carne moída", categoria: 'almoco', itens: [{ a: 'polenta', q: [340, 370, 400, 260] }, { a: 'moida', q: [80, 100, 100, 110] }, { a: 'molhoTomate', q: [90, 80, 110, 90] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Polenta firme no fundo, molho por cima.", receita: 'carneMoida', tempo: 45, passos: ["Molho de carne moída: veja o preparo de domingo, com a carne moída da semana e o molho de tomate.","Cozinhe a polenta pronta em cubos, ou aqueça a polenta em fatias no micro-ondas por 2 minutos, e amasse.","Espalhe a polenta no fundo de cada pote, formando uma base lisa.","Cubra com o molho de carne moída e a mussarela, e deixe esfriar antes de tampar."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade para o queijo derreter." },
  almoco21: { nome: "Bife à milanesa com arroz e batata", categoria: 'almoco', itens: [{ a: 'milanesaBoi', q: [80, 90, 100, 100] }, { a: 'arroz', q: [190, 210, 210, 140] }, { a: 'batata', q: [180, 200, 210, 130] }], preparo: "Milanesa assada na airfryer, sem fritar.", receita: 'arrozDaSemana', tempo: 50, passos: ["Arroz da semana: veja o preparo de domingo.","Passe a milanesa de boi na airfryer a 200 graus por 12 minutos, virando na metade, e deixe esfriar em grade.","Gomos de batata com sal e páprica na airfryer a 200 graus por 20 a 25 minutos, sacudindo na metade.","Monte os potes com arroz e batata de um lado e a milanesa do outro."], etiquetas: ["salgado","marmita"], temperos: ["sal","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta; a milanesa amolece um pouco, mas continua boa.", airfryer: "Milanesa de boi na airfryer a 200 graus por 12 minutos e batata a 200 graus por 20 a 25 minutos." },
  almoco22: { nome: "Cuscuz com frango desfiado e ovo", categoria: 'almoco', itens: [{ a: 'cuscuz', q: [330, 370, 390, 270] }, { a: 'frango', q: [90, 100, 110, 120] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [10, 15, 15, 10] }], preparo: "Frango com requeijão por cima do cuscuz.", receita: 'frangoDaSemana', tempo: 45, passos: ["Frango grelhado da semana: veja o preparo de domingo. Desfie o frango.","Cozinhe os ovos por 9 minutos, passe em água gelada, descasque e pique.","Hidrate o cuscuz flocão com água e sal e cozinhe no micro-ondas por 3 minutos, tampado. Solte com um garfo.","Misture o frango desfiado com o requeijão.","Divida o cuscuz nos potes, cubra com o frango cremoso e o ovo picado."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos, tampa entreaberta, com 1 colher de água para não ressecar." },
  almoco23: { nome: "Almôndegas ao sugo com arroz", categoria: 'almoco', itens: [{ a: 'moida', q: [110, 120, 130, 140] }, { a: 'molhoTomate', q: [110, 140, 120, 90] }, { a: 'arroz', q: [270, 300, 320, 210] }], preparo: "Bolinhas de carne moída assadas e depois no molho.", receita: 'arrozDaSemana', tempo: 55, passos: ["Misture a carne moída com sal, alho em pó e orégano e modele bolinhas do tamanho de uma noz.","Asse em forno a 200 graus por 15 minutos, até dourar por fora.","Aqueça o molho de tomate com 1 copo de água, junte as almôndegas e deixe 8 minutos em fogo baixo.","Arroz da semana: veja o preparo de domingo.","Divida o arroz nos potes e coloque as almôndegas com o molho por cima."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","orégano","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco24: { nome: "Coxa de frango assada com arroz e batata", categoria: 'almoco', itens: [{ a: 'coxa', q: [120, 130, 140, 140] }, { a: 'arroz', q: [200, 230, 240, 170] }, { a: 'batata', q: [200, 220, 230, 160] }], preparo: "Coxa desossada depois de assada, para caber no pote.", receita: 'arrozDaSemana', tempo: 55, passos: ["Tempere as coxas com sal, alho em pó e páprica. Forno a 200 graus por 40 minutos, virando na metade.","Gomos de batata com sal na mesma assadeira nos últimos 25 minutos.","Deixe esfriar e desosse as coxas, tirando a pele, para caber no pote.","Arroz da semana: veja o preparo de domingo.","Monte os potes com arroz, frango desfiado em pedaços e batata."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco25: { nome: "Macarrão com calabresa e queijo", categoria: 'almoco', itens: [{ a: 'macarrao', q: [260, 290, 290, 210] }, { a: 'calabresa', q: [40, 50, 60, 60] }, { a: 'molhoTomate', q: [70, 50, 80, 70] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Calabresa em cubos pequenos, dourada antes do molho.", tempo: 35, passos: ["Cozinhe o macarrão em água com sal, 2 minutos a menos que o tempo da embalagem. Escorra.","Corte a calabresa em cubos pequenos e doure em frigideira antiaderente por 5 minutos, até soltar a gordura.","Junte o molho de tomate e uma pitada de orégano e deixe 3 minutos.","Misture ao macarrão, divida nos potes e cubra com a mussarela."], etiquetas: ["salgado","marmita"], temperos: ["sal","orégano","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta; mexa na metade para o queijo derreter." },
  almoco26: { nome: "Bisteca de porco com arroz e purê", categoria: 'almoco', itens: [{ a: 'bisteca', q: [90, 100, 100, 110] }, { a: 'arroz', q: [170, 190, 210, 140] }, { a: 'pure', q: [150, 170, 180, 110] }], preparo: "Bisteca sem osso, em tiras.", receita: 'pureBatata', tempo: 45, passos: ["Purê de batata e arroz da semana: veja o preparo de domingo.","Tempere a bisteca com sal e alho em pó. Frigideira antiaderente bem quente, 5 minutos de cada lado.","Deixe descansar 5 minutos, tire o osso e corte em tiras.","Monte os potes com arroz, purê e tiras de bisteca."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco27: { nome: "Arroz com frango desfiado e queijo", categoria: 'almoco', itens: [{ a: 'arroz', q: [310, 340, 370, 260] }, { a: 'frango', q: [100, 120, 120, 130] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Tudo misturado, queijo por cima.", receita: 'frangoDaSemana', tempo: 35, passos: ["Arroz da semana e frango grelhado: veja o preparo de domingo. Desfie o frango.","Misture o arroz com o frango desfiado, sal e alho em pó.","Divida nos potes e cubra com a mussarela picada.","Deixe esfriar antes de tampar."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta, mexendo na metade." },
  almoco28: { nome: "Panqueca de carne moída", categoria: 'almoco', itens: [{ a: 'wrap', q: [2, 2, 2, 2] }, { a: 'moida', q: [110, 140, 160, 100] }, { a: 'molhoTomate', q: [60, 80, 70, 60] }, { a: 'mussarela', q: [2, 2, 2, 2] }], preparo: "Massa pronta, recheio de carne, molho e queijo por cima.", receita: 'carneMoida', tempo: 50, passos: ["Carne moída da semana: veja o preparo de domingo.","Aqueça os discos de wrap 15 segundos no micro-ondas para não quebrarem.","Recheie cada disco com a carne moída e enrole firme, como um rocambole.","Arrume em refratário, cubra com o molho de tomate temperado com orégano e a mussarela e leve ao forno a 200 graus por 12 minutos.","Deixe esfriar e divida em potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","orégano"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco29: { nome: "Costela assada com arroz e batata", categoria: 'almoco', itens: [{ a: 'costela', q: [70, 80, 80, 90] }, { a: 'arroz', q: [200, 220, 240, 150] }, { a: 'batata', q: [200, 210, 240, 140] }], preparo: "Costela desfiada, sem osso.", receita: 'arrozDaSemana', tempo: 80, passos: ["Tempere a costela com sal, alho em pó, páprica e cominho e embrulhe em papel-alumínio.","Forno a 180 graus por 1 hora e meia, até soltar do osso. Gomos de batata com sal na assadeira por 40 minutos.","Deixe esfriar embrulhada e desfie, descartando osso e gordura.","Arroz da semana: veja o preparo de domingo.","Monte os potes com arroz, costela desfiada e batata."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica","cominho"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco30: { nome: "Frango ao molho de tomate com macarrão", categoria: 'almoco', itens: [{ a: 'frango', q: [90, 110, 110, 120] }, { a: 'molhoTomate', q: [100, 70, 100, 90] }, { a: 'macarrao', q: [280, 310, 330, 240] }], preparo: "Frango em cubos cozido no molho.", tempo: 45, passos: ["Cozinhe o macarrão em água com sal, 2 minutos a menos que o tempo da embalagem. Escorra.","Corte o frango em cubos, tempere com sal e alho em pó e doure em frigideira antiaderente por 6 minutos.","Junte o molho de tomate, uma pitada de orégano e 1 copo de água e cozinhe por 8 minutos em fogo baixo.","Divida o macarrão nos potes e cubra com o frango ao molho."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","orégano","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  jantar11: { nome: "Pizza de pão de forma", categoria: 'jantar', itens: [{ a: 'paoForma', q: [3, 3, 3, 3] }, { a: 'molhoTomate', q: [35, 15, 30, 50] }, { a: 'mussarela', q: [3, 3, 3, 3] }, { a: 'presunto', q: [2, 2, 2, 2] }, { a: 'leite', q: [150, 250, 300, 100] }], preparo: "Na frigideira tampada ou airfryer, 5 minutos. Leite para acompanhar.", tempo: 12, passos: ["Passe o molho de tomate em 3 fatias de pão de forma e tempere com orégano.","Cubra com mussarela e presunto.","Leve à frigideira tampada em fogo baixo por 5 minutos, até o queijo derreter.","Sirva com o leite."], etiquetas: ["salgado","besteira"], temperos: ["orégano"], airfryer: "Na airfryer a 180 graus por 5 minutos, até o queijo derreter e a borda dourar." },
  jantar12: { nome: "Tapioca de frango e queijo", categoria: 'jantar', itens: [{ a: 'tapioca', q: [110, 120, 130, 80] }, { a: 'frango', q: [80, 90, 100, 110] }, { a: 'mussarela', q: [2, 2, 2, 2] }], preparo: "Frango desfiado da semana como recheio.", tempo: 8, passos: ["Aqueça uma frigideira antiaderente e espalhe a tapioca hidratada em camada fina.","Quando soltar do fundo, vire e distribua o frango desfiado e a mussarela em uma metade.","Dobre ao meio e tampe 1 minuto para o queijo derreter."], etiquetas: ["salgado"], temperos: ["sal"] },
  jantar13: { nome: "Cachorro-quente caseiro com batata", categoria: 'jantar', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'salsicha', q: [2, 2, 2, 2] }, { a: 'molhoTomate', q: [35, 40, 40, 40] }, { a: 'batata', q: [190, 270, 280, 140] }], preparo: "Salsicha fervida 3 minutos no molho; batata de micro-ondas.", tempo: 15, passos: ["Lave a batata e leve ao micro-ondas por 6 minutos, virando na metade.","Ferva as salsichas no molho de tomate com orégano por 3 minutos.","Aqueça o pão por 1 minuto na frigideira e recheie com as salsichas e o molho.","Corte a batata em gomos e tempere com sal."], etiquetas: ["salgado"], temperos: ["sal","orégano"] },
  jantar14: { nome: "Misto quente duplo com leite", categoria: 'jantar', itens: [{ a: 'paoForma', q: [4, 4, 4, 4] }, { a: 'presunto', q: [3, 3, 3, 3] }, { a: 'mussarela', q: [3, 3, 3, 3] }, { a: 'leite', q: [50, 150, 200, 50] }], preparo: "Dois sanduíches na frigideira.", tempo: 10, passos: ["Monte dois sanduíches com presunto e mussarela entre as fatias de pão.","Aqueça uma frigideira antiaderente em fogo médio.","Doure os sanduíches 2 minutos de cada lado, apertando com a espátula.","Sirva com o leite."], etiquetas: ["salgado"] },
  jantar15: { nome: "Nhoque com frango e requeijão", categoria: 'jantar', itens: [{ a: 'nhoque', q: [210, 230, 250, 180] }, { a: 'frango', q: [70, 70, 80, 90] }, { a: 'requeijao', q: [10, 15, 10, 10] }], preparo: "Nhoque pronto: 2 minutos na água fervente.", receita: 'frangoDaSemana', tempo: 8, passos: ["Ferva água com sal e cozinhe o nhoque por 2 minutos, até subir.","Escorra e volte à panela em fogo baixo.","Junte o frango da semana desfiado e o requeijão e mexa até formar um molho.","Tempere com pimenta-do-reino."], etiquetas: ["salgado"], temperos: ["sal","pimenta-do-reino","água"] },
  jantar16: { nome: "Linguiça com purê", categoria: 'jantar', itens: [{ a: 'linguica', q: [90, 100, 110, 110] }, { a: 'pure', q: [300, 330, 340, 230] }], preparo: "Linguiça na airfryer, 12 minutos.", tempo: 18, passos: ["Fure a linguiça com um garfo e leve à airfryer a 180 graus por 12 minutos, virando na metade.","Esquente o purê no micro-ondas por 3 minutos, mexendo na metade.","Corte a linguiça em rodelas e sirva sobre o purê."], etiquetas: ["salgado"], temperos: ["sal"], airfryer: "Linguiça furada na airfryer a 180 graus por 12 minutos, virando na metade." },
  jantar17: { nome: "Wrap de carne moída e queijo", categoria: 'jantar', itens: [{ a: 'wrap', q: [2, 2, 2, 2] }, { a: 'moida', q: [70, 100, 120, 60] }, { a: 'mussarela', q: [2, 2, 2, 2] }], preparo: "Carne moída da semana, enrola e doura.", receita: 'carneMoida', tempo: 8, passos: ["Esquente a carne moída da semana no micro-ondas por 2 minutos.","Ponha a carne e a mussarela no centro de cada wrap e enrole.","Doure os wraps na frigideira seca, 1 minuto de cada lado, com a emenda para baixo primeiro."], etiquetas: ["salgado"] },
  jantar18: { nome: "Cuscuz com carne moída", categoria: 'jantar', itens: [{ a: 'cuscuz', q: [310, 340, 350, 250] }, { a: 'moida', q: [80, 90, 100, 100] }], preparo: "Cuscuz de micro-ondas e a carne por cima.", receita: 'carneMoida', tempo: 8, passos: ["Hidrate o cuscuz em um pote com água e sal conforme a embalagem.","Leve ao micro-ondas por 3 minutos, tampado, e solte com um garfo.","Esquente a carne moída da marmita por 2 minutos.","Cubra o cuscuz com a carne."], etiquetas: ["salgado"], temperos: ["sal","água"] },
  jantar19: { nome: "Polenta cremosa com frango", categoria: 'jantar', itens: [{ a: 'polenta', q: [310, 340, 360, 250] }, { a: 'frango', q: [70, 80, 90, 90] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [10, 10, 10, 10] }], preparo: "Polenta instantânea: 5 minutos mexendo.", receita: 'frangoDaSemana', tempo: 10, passos: ["Ferva água com sal e despeje a polenta aos poucos, mexendo sem parar por 5 minutos.","Esquente o frango da semana por 1 minuto e desfie.","Junte a mussarela e o requeijão à polenta quente e mexa até ficar cremoso.","Sirva com o frango por cima."], etiquetas: ["salgado"], temperos: ["sal","água"] },
  jantar20: { nome: "X-burguer com batata", categoria: 'jantar', itens: [{ a: 'paoHamburguer', q: [1, 1, 1, 1] }, { a: 'moida', q: [70, 80, 100, 80] }, { a: 'queijoPrato', q: [1, 1, 1, 1] }, { a: 'batataFrita', q: [60, 70, 70, 40] }], preparo: "Disco de carne, 4 minutos de cada lado.", tempo: 20, passos: ["Modele a carne moída crua com sal e alho em pó em um disco um pouco maior que o pão.","Ponha a batata frita congelada na airfryer a 200 graus por 12 minutos, sacudindo na metade.","Grelhe o disco na frigideira bem quente, 4 minutos de cada lado, e ponha o queijo por cima no final.","Aqueça o pão por 1 minuto e monte o sanduíche."], etiquetas: ["salgado","besteira"], temperos: ["sal","alho em pó"], airfryer: "Batata frita na airfryer a 200 graus por 12 minutos, sacudindo na metade." },
  jantar21: { nome: "Frango à milanesa com purê", categoria: 'jantar', itens: [{ a: 'milanesaFrango', q: [110, 120, 130, 130] }, { a: 'pure', q: [280, 300, 320, 210] }], preparo: "Milanesa na airfryer, 12 minutos.", tempo: 18, passos: ["Ponha a milanesa de frango na airfryer a 200 graus por 12 minutos, virando na metade.","Esquente o purê no micro-ondas por 3 minutos, mexendo na metade.","Sirva a milanesa sobre ou ao lado do purê."], etiquetas: ["salgado"], temperos: ["sal"], airfryer: "Milanesa na airfryer a 200 graus por 12 minutos, virando na metade, sem óleo." },
  jantar22: { nome: "Macarrão com almôndegas", categoria: 'jantar', itens: [{ a: 'macarrao', q: [210, 230, 240, 170] }, { a: 'moida', q: [70, 80, 90, 90] }, { a: 'molhoTomate', q: [110, 100, 110, 100] }], preparo: "Almôndegas da semana, esquentadas no molho.", tempo: 12, passos: ["Cozinhe o macarrão em água com sal conforme a embalagem e escorra.","Esquente o molho de tomate numa panela pequena com orégano.","Junte as almôndegas da semana ao molho e deixe 4 minutos em fogo baixo, tampadas.","Misture o macarrão ao molho e sirva."], etiquetas: ["salgado"], temperos: ["sal","orégano","água"] },
  jantar23: { nome: "Omelete de presunto com batata", categoria: 'jantar', itens: [{ a: 'ovo', q: [3, 4, 4, 4] }, { a: 'presunto', q: [2, 2, 3, 2] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'batata', q: [400, 350, 400, 210] }], preparo: "Batata de micro-ondas, 6 minutos.", tempo: 15, passos: ["Lave a batata, corte em cubos pequenos e cozinhe no micro-ondas por 6 minutos, com tampa.","Bata os ovos com sal e junte o presunto picado.","Despeje na frigideira antiaderente, ponha a mussarela e dobre quando firmar.","Tempere a batata com sal e sirva junto."], etiquetas: ["salgado"], temperos: ["sal"] },
  jantar24: { nome: "Lombo com arroz", categoria: 'jantar', itens: [{ a: 'lombo', q: [100, 110, 120, 120] }, { a: 'arroz', q: [240, 260, 280, 190] }], preparo: "Sobra do lombo da semana.", tempo: 6, passos: ["Esquente o arroz no micro-ondas por 2 minutos.","Esquente o lombo da semana fatiado por 1 minuto e meio.","Tempere com sal e pimenta-do-reino e monte o prato."], etiquetas: ["salgado"], temperos: ["sal","pimenta-do-reino"] },
  jantar25: { nome: "Sanduíche quente de frango com requeijão", categoria: 'jantar', itens: [{ a: 'paoFrances', q: [2, 2, 2, 2] }, { a: 'frango', q: [110, 140, 170, 100] }, { a: 'requeijao', q: [20, 20, 15, 15] }], preparo: "Frango com requeijão, pão aquecido.", receita: 'frangoDaSemana', tempo: 8, passos: ["Esquente o frango da semana por 1 minuto, desfie e misture com o requeijão.","Abra os pães e recheie com o frango.","Aqueça uma frigideira antiaderente e doure os sanduíches 2 minutos de cada lado, apertando."], etiquetas: ["salgado"] },
  jantar26: { nome: "Arroz de forno com carne moída", categoria: 'jantar', itens: [{ a: 'arroz', q: [200, 230, 240, 150] }, { a: 'moida', q: [60, 70, 80, 80] }, { a: 'mussarela', q: [2, 2, 2, 2] }], preparo: "Micro-ondas até o queijo derreter.", receita: 'carneMoida', tempo: 10, passos: ["Misture o arroz e a carne moída da semana em um prato fundo.","Cubra com a mussarela.","Leve ao micro-ondas por 3 minutos, até o queijo derreter.","Tempere com orégano."], etiquetas: ["salgado"], temperos: ["orégano"] },
  jantar27: { nome: "Bisteca com batata assada", categoria: 'jantar', itens: [{ a: 'bisteca', q: [110, 130, 130, 130] }, { a: 'batata', q: [410, 400, 470, 250] }], preparo: "Bisteca na frigideira, 4 minutos de cada lado.", tempo: 22, passos: ["Lave a batata, corte em gomos e cozinhe no micro-ondas por 5 minutos, com tampa.","Passe os gomos para a airfryer a 200 graus por 10 minutos, com sal e páprica.","Tempere a bisteca com sal e alho em pó e grelhe na frigideira bem quente, 5 a 6 minutos de cada lado, até não ter rosa no centro."], etiquetas: ["salgado"], temperos: ["sal","alho em pó","páprica"] },
  jantar28: { nome: "Macarrão com queijo e frango", categoria: 'jantar', itens: [{ a: 'macarrao', q: [190, 220, 230, 150] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'requeijao', q: [10, 10, 15, 10] }, { a: 'frango', q: [40, 40, 50, 60] }], preparo: "Queijo e requeijão derretidos no macarrão quente.", receita: 'frangoDaSemana', tempo: 12, passos: ["Cozinhe o macarrão em água com sal conforme a embalagem e escorra.","Volte à panela em fogo baixo e junte o requeijão e a mussarela picada, mexendo até derreter.","Esquente o frango da semana por 1 minuto, desfie e misture.","Tempere com pimenta-do-reino."], etiquetas: ["salgado"], temperos: ["sal","pimenta-do-reino","água"] },
  jantar29: { nome: "Coxa de frango com purê", categoria: 'jantar', itens: [{ a: 'coxa', q: [120, 130, 140, 140] }, { a: 'pure', q: [260, 290, 310, 190] }], preparo: "Coxa na airfryer, 25 minutos.", tempo: 30, passos: ["Tempere a coxa com sal, alho em pó e páprica.","Leve à airfryer a 180 graus por 25 minutos, virando na metade.","Enquanto isso, esquente o purê no micro-ondas por 3 minutos.","Sirva a coxa sobre o purê."], etiquetas: ["salgado"], temperos: ["sal","alho em pó","páprica"], airfryer: "Coxa na airfryer a 180 graus por 25 minutos, virando na metade." },
  jantar30: { nome: "Pão com linguiça", categoria: 'jantar', itens: [{ a: 'paoFrances', q: [2, 2, 2, 2] }, { a: 'linguica', q: [90, 110, 130, 80] }], preparo: "Linguiça aberta ao meio, na frigideira.", tempo: 12, passos: ["Abra a linguiça ao meio no sentido do comprimento.","Doure na frigideira, 4 minutos de cada lado, até ficar bem cozida.","Aqueça os pães por 1 minuto e recheie com a linguiça."], etiquetas: ["salgado"], airfryer: "Linguiça aberta na airfryer a 180 graus por 10 minutos." },
  ceia6: { nome: "Vitamina de morango", categoria: 'ceia', itens: [{ a: 'leite', q: [300, 300, 300, 250] }, { a: 'morango', q: [150, 220, 240, 140] }, { a: 'mel', q: [10, 10, 15, 15] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Lave os morangos e tire as folhinhas.","Coloque no liquidificador com o leite e o mel.","Bata por 40 segundos, até ficar rosa e liso.","Se os morangos estiverem em temperatura ambiente, junte 2 pedras de gelo."], etiquetas: ["doce","vegetariano"], temperos: ["gelo"] },
  ceia7: { nome: "Vitamina de mamão com aveia", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 250, 250] }, { a: 'mamao', q: [120, 170, 170, 120] }, { a: 'aveia', q: [15, 15, 20, 10] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Tire a casca e as sementes do mamão e corte em cubos.","Coloque no liquidificador com o leite e a aveia.","Bata por 40 segundos, até ficar liso.","Beba logo, enquanto está cremoso."], etiquetas: ["doce","vegetariano"] },
  ceia8: { nome: "Vitamina de abacate", categoria: 'ceia', itens: [{ a: 'leite', q: [300, 300, 300, 250] }, { a: 'abacate', q: [50, 50, 60, 40] }, { a: 'mel', q: [10, 15, 20, 15] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Tire a casca e o caroço do abacate e pegue a polpa madura.","Coloque a polpa no liquidificador com o leite e o mel.","Bata por 40 segundos, até ficar sem pedaços.","Sirva gelada, em copo alto."], etiquetas: ["doce","vegetariano"], temperos: ["gelo"] },
  ceia9: { nome: "Leite com achocolatado e aveia", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 300, 250] }, { a: 'achocolatado', q: [15, 15, 15, 10] }, { a: 'aveia', q: [10, 15, 15, 10] }], preparo: "Bata para a aveia sumir.", tempo: 4, passos: ["Coloque o leite, o achocolatado e a aveia no liquidificador.","Bata por 40 segundos, até a aveia sumir.","Sirva gelado ou aqueça o copo no micro-ondas por 45 segundos.","Beba devagar."], etiquetas: ["doce","vegetariano"] },
  ceia10: { nome: "Iogurte batido com banana", categoria: 'ceia', itens: [{ a: 'iogurte', q: [270, 270, 310, 260] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'mel', q: [15, 20, 20, 10] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Coloque o iogurte, a banana em pedaços e o mel no liquidificador.","Bata por 30 segundos, até ficar liso.","Sirva logo, em copo alto.","Beba devagar."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia11: { nome: "Vitamina de maçã com aveia", categoria: 'ceia', itens: [{ a: 'leite', q: [200, 250, 250, 200] }, { a: 'macaFruta', q: [1, 1, 1, 1] }, { a: 'aveia', q: [15, 15, 20, 10] }], preparo: "Maçã sem casca, para ficar lisa.", tempo: 5, passos: ["Descasque a maçã, tire o miolo e corte em cubos pequenos.","Coloque no liquidificador com o leite e a aveia.","Bata por 1 minuto, até a maçã ficar lisa, sem pedaços.","Polvilhe canela e beba devagar."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia12: { nome: "Mingau ralo de aveia", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 300, 250] }, { a: 'aveia', q: [25, 25, 25, 20] }, { a: 'mel', q: [5, 10, 5, 5] }], preparo: "Morno, para dar sono.", tempo: 8, passos: ["Misture o leite e a aveia em uma panela pequena.","Leve ao fogo baixo e mexa por 4 a 5 minutos, até engrossar de leve.","Desligue o fogo e adoce com o mel.","Deixe amornar 2 minutos e tome de colher ou de caneca."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia13: { nome: "Vitamina de manga", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 300, 250] }, { a: 'manga', q: [150, 180, 160, 120] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Descasque a manga e corte a polpa em cubos, longe do caroço.","Coloque no liquidificador com o leite.","Bata por 40 segundos, até ficar sem fiapos.","Sirva gelada."], etiquetas: ["doce","vegetariano"], temperos: ["gelo"] },
  ceia14: { nome: "Leite com mel e pasta de amendoim", categoria: 'ceia', itens: [{ a: 'leite', q: [300, 350, 350, 300] }, { a: 'mel', q: [15, 10, 20, 10] }, { a: 'pastaAmendoim', q: [5, 5, 5, 5] }], preparo: "Bata para dissolver a pasta.", tempo: 4, passos: ["Coloque o leite, o mel e a pasta de amendoim no liquidificador.","Bata por 40 segundos, até a pasta dissolver.","Aqueça o copo no micro-ondas por 45 segundos, se quiser morno.","Beba devagar, uns 30 minutos antes de dormir."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia15: { nome: "Vitamina de banana com leite em pó", categoria: 'ceia', itens: [{ a: 'leite', q: [200, 200, 250, 200] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'leitePo', q: [10, 15, 15, 10] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Coloque o leite, o leite em pó e a banana em pedaços no liquidificador.","Bata por 40 segundos, até não restar grumo de leite em pó.","Sirva gelada.","Beba devagar."], etiquetas: ["doce","vegetariano"] },
  ceia16: { nome: "Iogurte batido com morango e mel", categoria: 'ceia', itens: [{ a: 'iogurte', q: [280, 310, 330, 290] }, { a: 'morango', q: [180, 200, 230, 150] }, { a: 'mel', q: [20, 20, 20, 15] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Lave os morangos e tire as folhinhas.","Coloque no liquidificador com o iogurte e o mel.","Bata por 30 segundos, até ficar liso.","Sirva logo, em copo alto."], etiquetas: ["doce","vegetariano"] },
  ceia17: { nome: "Shake de doce de leite", categoria: 'ceia', itens: [{ a: 'leite', q: [300, 300, 350, 300] }, { a: 'doceLeite', q: [25, 30, 30, 20] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Coloque o leite e o doce de leite no liquidificador.","Bata por 40 segundos, até o doce dissolver por inteiro.","Sirva gelado ou aqueça o copo no micro-ondas por 45 segundos.","Beba devagar."], etiquetas: ["doce","vegetariano"] },
  ceia18: { nome: "Vitamina de mamão com Farinha Láctea", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 250, 250] }, { a: 'mamao', q: [110, 110, 110, 60] }, { a: 'farinhaLactea', q: [15, 20, 25, 15] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Tire a casca e as sementes do mamão e corte em cubos.","Coloque no liquidificador com o leite e a Farinha Láctea.","Bata por 40 segundos, até ficar liso.","Beba devagar, sentado."], etiquetas: ["doce","vegetariano"] },
  ceia19: { nome: "Leite com Mucilon e mel", categoria: 'ceia', itens: [{ a: 'leite', q: [300, 300, 300, 250] }, { a: 'mucilon', q: [15, 20, 25, 15] }, { a: 'mel', q: [5, 5, 10, 10] }], preparo: "Morno, mexendo bem.", tempo: 8, passos: ["Dissolva o Mucilon em um pouco do leite frio, em uma panela pequena.","Junte o resto do leite e leve ao fogo baixo, mexendo sempre.","Cozinhe por 3 a 4 minutos, até engrossar de leve.","Desligue, adoce com o mel e deixe amornar 2 minutos."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia20: { nome: "Vitamina de abacate com aveia", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 300, 300, 250] }, { a: 'abacate', q: [30, 40, 40, 30] }, { a: 'aveia', q: [20, 15, 20, 15] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Tire a casca e o caroço do abacate e pegue a polpa madura.","Coloque no liquidificador com o leite e a aveia.","Bata por 40 segundos, até ficar cremoso.","Deixe descansar 1 minuto para engrossar e beba devagar."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia21: { nome: "Iogurte batido com manga", categoria: 'ceia', itens: [{ a: 'iogurte', q: [250, 260, 290, 240] }, { a: 'manga', q: [160, 180, 190, 140] }, { a: 'mel', q: [5, 5, 5, 5] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Descasque a manga e corte a polpa em cubos.","Coloque no liquidificador com o iogurte e o mel.","Bata por 40 segundos, até ficar sem fiapos.","Sirva gelada, em copo alto."], etiquetas: ["doce","vegetariano"], temperos: ["gelo"] },
  ceia22: { nome: "Vitamina de banana e pasta de amendoim", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 300, 200] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'pastaAmendoim', q: [5, 10, 5, 5] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Quebre a banana em pedaços e coloque no liquidificador com o leite.","Junte a pasta de amendoim.","Bata por 40 segundos, até a pasta dissolver.","Beba devagar, uns 30 minutos antes de dormir."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia23: { nome: "Leite com leite condensado e aveia", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 250, 250] }, { a: 'leiteCondensado', q: [15, 20, 30, 15] }, { a: 'aveia', q: [15, 15, 15, 10] }], preparo: "Morno, mexendo bem.", tempo: 7, passos: ["Misture o leite, o leite condensado e a aveia em uma panela pequena.","Leve ao fogo baixo e mexa por 3 a 4 minutos, até a aveia amaciar e o leite ficar morno.","Não deixe ferver forte, para não formar nata nem grudar.","Passe para uma caneca e deixe amornar 1 minuto."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia24: { nome: "Vitamina de maçã e banana", categoria: 'ceia', itens: [{ a: 'leite', q: [200, 200, 250, 150] }, { a: 'macaFruta', q: [1, 1, 1, 1] }, { a: 'banana', q: [1, 1, 1, 1] }], preparo: "Bata e beba devagar.", tempo: 5, passos: ["Descasque a maçã, tire o miolo e corte em cubos pequenos.","Coloque no liquidificador com o leite e a banana em pedaços.","Bata por 1 minuto, até ficar sem pedaços de maçã.","Beba logo, devagar."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia25: { nome: "Iogurte batido com aveia e doce de leite", categoria: 'ceia', itens: [{ a: 'iogurte', q: [270, 270, 310, 260] }, { a: 'aveia', q: [15, 20, 20, 15] }, { a: 'doceLeite', q: [20, 20, 20, 15] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Coloque o iogurte, a aveia e o doce de leite no liquidificador.","Bata por 40 segundos, até o doce dissolver e a aveia sumir.","Deixe descansar 1 minuto para engrossar.","Beba devagar, em copo alto."], etiquetas: ["doce","vegetariano"] },
  ceia26: { nome: "Shake de paçoca", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 300, 350, 250] }, { a: 'pacoca', q: [1, 1, 1, 1] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Esfarele a paçoca dentro do liquidificador.","Junte o leite.","Bata por 40 segundos, até ficar liso.","Sirva gelado ou aqueça o copo no micro-ondas por 45 segundos."], etiquetas: ["doce","vegetariano"] },
  ceia27: { nome: "Vitamina de morango com Farinha Láctea", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 250, 250] }, { a: 'morango', q: [80, 150, 150, 80] }, { a: 'farinhaLactea', q: [20, 20, 25, 15] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Lave os morangos e tire as folhinhas.","Coloque no liquidificador com o leite e a Farinha Láctea.","Bata por 40 segundos, até ficar liso e cor-de-rosa.","Sirva gelada, em copo alto."], etiquetas: ["doce","vegetariano"], temperos: ["gelo"] },
  ceia28: { nome: "Vitamina de cereal", categoria: 'ceia', itens: [{ a: 'leite', q: [300, 300, 300, 250] }, { a: 'cerealMatinal', q: [20, 25, 30, 25] }], preparo: "Bata até o cereal sumir.", tempo: 4, passos: ["Coloque o leite e o cereal matinal no liquidificador.","Deixe o cereal de molho por 2 minutos, para amolecer.","Bata por 40 segundos, até o cereal sumir.","Beba logo, antes de engrossar demais."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia29: { nome: "Vitamina de mamão e banana", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 300, 200] }, { a: 'mamao', q: [70, 120, 100, 100] }, { a: 'banana', q: [1, 1, 1, 1] }], preparo: "Bata e beba devagar.", tempo: 4, passos: ["Tire a casca e as sementes do mamão e corte em cubos.","Coloque no liquidificador com o leite e a banana em pedaços.","Bata por 40 segundos, até ficar liso.","Beba devagar, uns 30 minutos antes de dormir."], etiquetas: ["doce","vegetariano"] },
  ceia30: { nome: "Iogurte batido com granola", categoria: 'ceia', itens: [{ a: 'iogurte', q: [230, 270, 280, 230] }, { a: 'granola', q: [30, 30, 30, 25] }, { a: 'mel', q: [5, 5, 10, 5] }], preparo: "Bata bem, para a granola não ficar em pedaços.", tempo: 4, passos: ["Coloque o iogurte e o mel no liquidificador.","Junte a granola e bata por 20 segundos em velocidade baixa, só para quebrar os pedaços.","Aumente a velocidade por mais 20 segundos, até ficar cremoso.","Sirva logo, em copo alto."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  pre31: { nome: "Tapioca com doce de leite", categoria: 'pre', itens: [{ a: 'tapioca', q: [50, 50, 50, 40] }, { a: 'doceLeite', q: [15, 20, 25, 20] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Tapioca na frigideira seca com doce de leite; pós em meio copo de água.", tempo: 5, passos: ["Aqueça uma frigideira antiaderente em fogo médio, sem óleo.","Espalhe a goma de tapioca em camada fina e uniforme.","Espere 1 minuto, vire e deixe mais 1 minuto até firmar.","Espalhe o doce de leite e dobre ao meio.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre32: { nome: "Pão de queijo com mel", categoria: 'pre', itens: [{ a: 'paoQueijo', q: [1, 1, 1, 1] }, { a: 'mel', q: [20, 25, 30, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Pão de queijo pequeno, quente, com fio de mel; pós em meio copo de água.", tempo: 4, passos: ["Separe os pães de queijo já assados, do dia anterior ou do congelador.","Esquente no micro-ondas por 30 a 40 segundos, ou na airfryer a 180 graus por 4 minutos.","Abra ao meio e regue com o mel.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre33: { nome: "Açaí pequeno com banana", categoria: 'pre', itens: [{ a: 'acai', q: [80, 80, 70, 60] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'aveia', q: [10, 15, 20, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Açaí batido com banana, aveia por cima; pós misturados na batida.", tempo: 5, passos: ["Deixe a polpa de açaí 2 minutos fora do congelador para amolecer.","Bata no liquidificador o açaí com metade da banana, pulsando até ficar espesso.","Junte a beterraba e o guaraná em pó e bata mais 10 segundos.","Passe para uma tigela e corte o resto da banana em rodelas por cima.","Finalize com a aveia e coma de colher."], etiquetas: ["doce","vegetariano"] },
  pre34: { nome: "Vitamina rápida de banana com iogurte", categoria: 'pre', itens: [{ a: 'leite', q: [100, 100, 150, 100] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'iogurte', q: [30, 60, 30, 30] }, { a: 'mel', q: [5, 5, 5, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata tudo junto, com os pós, e beba.", tempo: 3, passos: ["Coloque o leite, o iogurte e o mel no liquidificador.","Junte a banana descascada e em pedaços.","Junte a beterraba e o guaraná em pó no liquidificador.","Bata por 40 segundos até ficar liso e beba na hora."], etiquetas: ["doce","vegetariano"] },
  pre35: { nome: "Vitamina de manga com iogurte", categoria: 'pre', itens: [{ a: 'leite', q: [100, 100, 100, 100] }, { a: 'manga', q: [90, 100, 100, 70] }, { a: 'iogurte', q: [50, 70, 60, 60] }, { a: 'mel', q: [5, 5, 10, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata o leite, a manga, o iogurte e o mel, com os pós, e beba.", tempo: 4, passos: ["Corte a manga em cubos, sem casca.","Coloque o leite, o iogurte e o mel no liquidificador e junte a manga.","Junte a beterraba e o guaraná em pó no liquidificador.","Bata por 40 segundos até ficar liso e beba na hora."], etiquetas: ["doce","vegetariano"] },
  pre36: { nome: "Vitamina gelada de maçã e aveia", categoria: 'pre', itens: [{ a: 'leite', q: [100, 100, 100, 100] }, { a: 'macaFruta', q: [1, 1, 1, 1] }, { a: 'aveia', q: [10, 15, 15, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata o leite, a maçã e a aveia, com os pós, e beba.", tempo: 4, passos: ["Lave a maçã e corte em pedaços, sem tirar a casca.","Coloque o leite e a aveia no liquidificador e junte a maçã.","Junte a beterraba e o guaraná em pó no liquidificador.","Bata por 1 minuto para triturar bem a casca e beba na hora."], etiquetas: ["doce","vegetariano"] },
  pre37: { nome: "Vitamina de morango com banana", categoria: 'pre', itens: [{ a: 'leite', q: [100, 150, 150, 100] }, { a: 'morango', q: [90, 50, 80, 50] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata o leite, o morango e a banana, com os pós, e beba.", tempo: 4, passos: ["Lave o morango e tire as folhinhas.","Coloque o leite, o morango e a banana descascada no liquidificador.","Junte a beterraba e o guaraná em pó no liquidificador.","Bata por 40 segundos até ficar cremoso e beba na hora."], etiquetas: ["doce","vegetariano"] },
  pre38: { nome: "Vitamina gelada de mamão, aveia e mel", categoria: 'pre', itens: [{ a: 'leite', q: [100, 150, 150, 100] }, { a: 'mamao', q: [80, 100, 70, 60] }, { a: 'aveia', q: [10, 10, 15, 10] }, { a: 'mel', q: [10, 5, 5, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Bata o leite, o mamão, a aveia e o mel, com os pós, e beba.", tempo: 4, passos: ["Tire a casca e as sementes do mamão e corte em cubos.","Coloque o leite, a aveia e o mel no liquidificador e junte o mamão.","Junte a beterraba e o guaraná em pó no liquidificador.","Bata por 40 segundos e beba logo, antes de a aveia assentar."], etiquetas: ["doce","vegetariano"] },
  pre39: { nome: "Torradas com pasta de amendoim e mel", categoria: 'pre', itens: [{ a: 'torrada', q: [2, 2, 2, 2] }, { a: 'pastaAmendoim', q: [10, 10, 15, 10] }, { a: 'mel', q: [10, 15, 10, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Torradas com pasta de amendoim e fio de mel; pós em meio copo de água.", tempo: 3, passos: ["Passe a pasta de amendoim sobre as torradas.","Regue com o mel.","Coma em seguida, para manter o crocante.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre40: { nome: "Sanduíche de banana com doce de leite", categoria: 'pre', itens: [{ a: 'paoForma', q: [1, 1, 1, 1] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'doceLeite', q: [10, 15, 15, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Fatia de pão com doce de leite e banana amassada; pós em meio copo de água.", tempo: 3, passos: ["Amasse a banana com um garfo em um prato.","Espalhe o doce de leite na fatia de pão de forma.","Cubra com a banana amassada e dobre o pão ao meio.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre41: { nome: "Pão francês com requeijão", categoria: 'pre', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [5, 15, 20, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Pão francês aberto com requeijão; pós em meio copo de água.", tempo: 3, passos: ["Abra o pão francês ao meio.","Passe o requeijão nas duas metades.","Feche e coma.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["salgado","vegetariano"], temperos: ["água"] },
  pre42: { nome: "Tapioca de queijo minas", categoria: 'pre', itens: [{ a: 'tapioca', q: [50, 50, 60, 35] }, { a: 'minas', q: [15, 25, 20, 25] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Tapioca na frigideira seca com queijo minas em lascas; pós em meio copo de água.", tempo: 5, passos: ["Aqueça uma frigideira antiaderente em fogo médio, sem óleo.","Espalhe a goma de tapioca em camada fina e uniforme.","Espere 1 minuto, vire e deixe mais 1 minuto até firmar.","Coloque o queijo minas em lascas finas no centro, dobre ao meio e deixe 30 segundos para amolecer.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["salgado","vegetariano"], temperos: ["água"] },
  pre43: { nome: "Tapioca com iogurte e morango", categoria: 'pre', itens: [{ a: 'tapioca', q: [35, 40, 40, 30] }, { a: 'iogurte', q: [60, 70, 60, 70] }, { a: 'morango', q: [70, 70, 70, 50] }, { a: 'mel', q: [10, 10, 15, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Tapioca na frigideira seca recheada com iogurte, morango e mel; pós em meio copo de água.", tempo: 6, passos: ["Lave o morango, tire as folhinhas e corte em fatias.","Aqueça uma frigideira antiaderente em fogo médio, sem óleo.","Espalhe a goma de tapioca, espere 1 minuto, vire e deixe mais 1 minuto.","Recheie com o iogurte e o morango, regue com o mel e dobre ao meio.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre44: { nome: "Cuscuz doce com leite e canela", categoria: 'pre', itens: [{ a: 'cuscuz', q: [90, 110, 120, 80] }, { a: 'leite', q: [100, 100, 100, 100] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Cuscuz de micro-ondas com leite quente e canela; pós em meio copo de água.", tempo: 5, passos: ["Coloque o cuscuz em um pote próprio para micro-ondas.","Hidrate o cuscuz com 3 colheres de sopa de água e uma pitada de sal (ou de açúcar), mexa e deixe 2 minutos.","Tampe e leve ao micro-ondas por 2 minutos.","Esquente o leite por 40 segundos e despeje sobre o cuscuz.","Polvilhe canela a gosto e mexa com um garfo.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["canela","sal","água"] },
  pre45: { nome: "Iogurte com banana e aveia", categoria: 'pre', itens: [{ a: 'iogurte', q: [90, 130, 150, 110] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'aveia', q: [10, 10, 10, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Iogurte com banana amassada e aveia; pós em meio copo de água.", tempo: 3, passos: ["Coloque o iogurte em uma tigela.","Amasse a banana com um garfo e misture ao iogurte.","Polvilhe a aveia por cima e coma de colher.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre46: { nome: "Iogurte com granola e morango", categoria: 'pre', itens: [{ a: 'iogurte', q: [130, 120, 140, 110] }, { a: 'granola', q: [20, 25, 25, 20] }, { a: 'morango', q: [50, 60, 60, 50] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Iogurte com morango fatiado e granola crocante; pós em meio copo de água.", tempo: 4, passos: ["Lave o morango, tire as folhinhas e corte em fatias.","Coloque o iogurte em uma tigela e junte o morango.","Cubra com a granola na hora de comer, para ficar crocante.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre47: { nome: "Mamão com aveia e mel", categoria: 'pre', itens: [{ a: 'mamao', q: [140, 150, 160, 150] }, { a: 'aveia', q: [20, 20, 25, 20] }, { a: 'mel', q: [10, 15, 10, 5] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Mamão em cubos com aveia e mel; pós em meio copo de água.", tempo: 4, passos: ["Tire a casca e as sementes do mamão e corte em cubos em uma tigela.","Polvilhe a aveia por cima.","Regue com o mel e coma de colher.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre48: { nome: "Manga com aveia e leite", categoria: 'pre', itens: [{ a: 'manga', q: [90, 120, 130, 80] }, { a: 'leite', q: [100, 100, 100, 100] }, { a: 'aveia', q: [10, 10, 10, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Manga em cubos com leite gelado e aveia; pós misturados no leite.", tempo: 4, passos: ["Corte a manga em cubos, sem casca, e coloque em uma tigela.","Junte a aveia.","Misture a beterraba e o guaraná em pó no leite gelado.","Despeje o leite sobre a manga e a aveia e coma de colher."], etiquetas: ["doce","vegetariano"] },
  pre49: { nome: "Maçã com iogurte e mel", categoria: 'pre', itens: [{ a: 'macaFruta', q: [1, 1, 1, 1] }, { a: 'iogurte', q: [90, 130, 120, 100] }, { a: 'mel', q: [15, 15, 20, 10] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Maçã em cubos com iogurte e mel; pós em meio copo de água.", tempo: 4, passos: ["Lave a maçã e corte em cubos pequenos, sem tirar a casca.","Coloque o iogurte em uma tigela e junte a maçã.","Regue com o mel e mexa.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  pre50: { nome: "Mamão com iogurte e granola", categoria: 'pre', itens: [{ a: 'mamao', q: [100, 110, 110, 90] }, { a: 'iogurte', q: [80, 110, 90, 110] }, { a: 'granola', q: [20, 20, 25, 15] }, { a: 'beterraba', q: [5, 5, 5, 5] }, { a: 'guarana', q: [2, 2, 2, 2] }], preparo: "Mamão em cubos com iogurte e granola crocante; pós em meio copo de água.", tempo: 4, passos: ["Tire a casca e as sementes do mamão e corte em cubos.","Coloque o iogurte em uma tigela e junte o mamão.","Cubra com a granola na hora de comer, para ficar crocante.","Misture a beterraba e o guaraná em pó em meio copo de água e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["água"] },
  cafe31: { nome: "Tapioca de frango com catupiry e shake de whey", categoria: 'cafe', itens: [{ a: 'tapioca', q: [60, 70, 80, 50] }, { a: 'frango', q: [35, 50, 40, 40] }, { a: 'catupiry', q: [15, 15, 10, 10] }, { a: 'leite', q: [200, 200, 250, 200] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Tapioca recheada com frango desfiado e catupiry, shake de whey ao lado.", tempo: 10, passos: ["Desfie o frango (use o da marmita ou aqueça 1 minuto no micro-ondas) e misture com o catupiry e uma pitada de sal.","Espalhe a goma de tapioca em frigideira antiaderente seca, em fogo médio, formando um disco.","Quando firmar, 1 minuto, vire por 30 segundos.","Recheie com o frango, dobre ao meio e deixe 30 segundos.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal"] },
  cafe32: { nome: "Tapioca de queijo coalho e shake de whey", categoria: 'cafe', itens: [{ a: 'tapioca', q: [60, 60, 60, 30] }, { a: 'queijoCoalho', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 150, 200, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Tapioca recheada com queijo coalho derretido, shake de whey ao lado.", tempo: 10, passos: ["Corte o queijo coalho em fatias finas.","Espalhe a goma de tapioca em frigideira antiaderente seca, em fogo médio, formando um disco.","Quando firmar, 1 minuto, vire e distribua o queijo em metade do disco.","Dobre e deixe 1 minuto, até o queijo amolecer.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"] },
  cafe33: { nome: "Tapioca de presunto e queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'tapioca', q: [60, 80, 80, 50] }, { a: 'presunto', q: [2, 2, 2, 2] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [200, 200, 250, 200] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Tapioca recheada com presunto e mussarela, shake de whey ao lado.", tempo: 8, passos: ["Espalhe a goma de tapioca em frigideira antiaderente seca, em fogo médio, formando um disco.","Quando firmar, 1 minuto, vire e cubra metade com o presunto e a mussarela.","Dobre e deixe 1 minuto, até o queijo derreter.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"] },
  cafe34: { nome: "Crepioca de frango com catupiry e shake de whey", categoria: 'cafe', itens: [{ a: 'tapioca', q: [35, 40, 40, 20] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'frango', q: [25, 30, 30, 30] }, { a: 'catupiry', q: [10, 10, 10, 10] }, { a: 'leite', q: [100, 150, 200, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Crepioca recheada com frango e catupiry, shake de whey ao lado.", tempo: 12, passos: ["Desfie o frango e misture com o catupiry.","Bata os ovos com a goma de tapioca e uma pitada de sal.","Despeje em frigideira antiaderente em fogo médio e espalhe em disco.","Quando firmar embaixo, 2 minutos, vire por 1 minuto.","Recheie com o frango, dobre e deixe 30 segundos.","Bata o shake de whey e creatina no leite e beba junto."], etiquetas: ["salgado"], temperos: ["sal"] },
  cafe35: { nome: "Cuscuz recheado com ovo e queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'cuscuz', q: [80, 120, 150, 80] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 100, 100, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Cuscuz com ovo mexido e queijo derretido no meio, shake de whey ao lado.", tempo: 12, passos: ["Misture o flocão com uma pitada de sal e só a água necessária para umedecer; deixe 2 minutos.","Cozinhe no micro-ondas em pote tampado por 3 minutos e solte com um garfo.","Mexa os ovos na frigideira antiaderente em fogo baixo por 2 a 3 minutos.","Monte em camadas no prato: metade do cuscuz, os ovos e a mussarela, e o resto do cuscuz por cima. Deixe 1 minuto tampado para derreter.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"] },
  cafe36: { nome: "Sanduíche natural de frango com cenoura e shake de whey", categoria: 'cafe', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'frango', q: [50, 60, 60, 50] }, { a: 'cenoura', q: [30, 40, 40, 35] }, { a: 'requeijao', q: [5, 5, 5, 5] }, { a: 'alface', q: [2, 2, 2, 2] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'leite', q: [200, 250, 300, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Frango desfiado com cenoura ralada e requeijão, com alface e tomate.", tempo: 8, passos: ["Desfie o frango e misture com a cenoura ralada, o requeijão e uma pitada de sal.","Passe a pasta em uma fatia de pão.","Coloque a alface e as rodelas de tomate e feche com a outra fatia.","Corte ao meio na diagonal.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal"] },
  cafe37: { nome: "Pão francês na chapa com ovo e queijo e shake de whey", categoria: 'cafe', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'manteiga', q: [5, 5, 5, 5] }, { a: 'ovo', q: [1, 2, 2, 1] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [50, 50, 50, 50] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Pão com manteiga dourado na chapa, recheado com ovo e queijo.", tempo: 10, passos: ["Abra o pão ao meio e passe a manteiga nas duas metades.","Doure na frigideira antiaderente em fogo médio, com o lado da manteiga para baixo, por 2 minutos.","Na mesma frigideira, frite o ovo com uma pitada de sal.","Monte com o ovo e a mussarela e aqueça 1 minuto tampado, para derreter.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe38: { nome: "Ovo pochê no micro-ondas com torradas e shake de whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [2, 2, 2, 2] }, { a: 'torrada', q: [3, 3, 3, 3] }, { a: 'leite', q: [150, 250, 300, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Ovos cozidos na água no micro-ondas, servidos sobre torradas.", tempo: 10, passos: ["Coloque meio copo de água e uma pitada de sal em uma xícara e quebre um ovo dentro, com cuidado. Fure a gema com um palito.","Cubra com um pires e cozinhe no micro-ondas por 50 a 60 segundos, até a clara firmar. Repita com o outro ovo.","Retire o ovo da água com uma escumadeira e escorra bem.","Torre as torradas e coloque os ovos por cima.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"] },
  cafe39: { nome: "Ovo cozido com pão francês e requeijão e shake de whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [1, 1, 1, 1] }, { a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [10, 15, 15, 10] }, { a: 'leite', q: [200, 250, 300, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Ovo cozido, pão francês com requeijão e shake de whey.", tempo: 12, passos: ["Cubra o ovo com água fria numa panela pequena, junte uma pitada de sal e leve ao fogo.","Quando ferver, conte 8 minutos, escorra e passe o ovo em água fria para descascar fácil.","Abra o pão francês, aqueça 1 minuto na frigideira e passe o requeijão.","Corte o ovo em rodelas e coloque dentro do pão.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"] },
  cafe40: { nome: "Ovos mexidos cremosos com requeijão e torradas e shake de whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [2, 2, 2, 2] }, { a: 'requeijao', q: [15, 25, 25, 15] }, { a: 'torrada', q: [3, 3, 3, 3] }, { a: 'leite', q: [100, 150, 200, 50] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Ovos mexidos com requeijão, que deixa cremoso, e torradas.", tempo: 10, passos: ["Bata os ovos com uma pitada de sal.","Mexa na frigideira antiaderente em fogo baixo por 2 minutos.","Quando estiver quase firme, desligue o fogo e misture o requeijão para ficar cremoso.","Torre as torradas e sirva os ovos por cima.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe41: { nome: "Omelete de queijo coalho e tomate com torradas e shake de whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [1, 2, 2, 1] }, { a: 'queijoCoalho', q: [1, 1, 1, 1] }, { a: 'tomate', q: [3, 3, 3, 3] }, { a: 'torrada', q: [2, 1, 2, 1] }, { a: 'leite', q: [100, 100, 100, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Omelete recheada com queijo coalho em cubos e tomate, com torradas.", tempo: 12, passos: ["Corte o queijo coalho em cubinhos e as rodelas de tomate em pedaços pequenos.","Bata os ovos com uma pitada de sal e um pouco de orégano.","Despeje em frigideira antiaderente em fogo médio e distribua o queijo e o tomate sobre a metade da massa.","Dobre a omelete quando firmar por baixo e tampe por 2 minutos, até o queijo amolecer.","Torre as torradas.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","orégano"] },
  cafe42: { nome: "Omelete de peito de peru com catupiry e shake de whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [2, 2, 2, 2] }, { a: 'peitoPeru', q: [3, 3, 4, 3] }, { a: 'catupiry', q: [15, 25, 20, 15] }, { a: 'leite', q: [200, 250, 300, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Omelete recheada com peito de peru picado e catupiry.", tempo: 10, passos: ["Pique o peito de peru em tiras finas e misture com o catupiry.","Bata os ovos com uma pitada de sal.","Despeje em frigideira antiaderente em fogo médio e, quando começar a firmar, ponha o recheio de peru e catupiry no centro.","Dobre a omelete e tampe por 1 minuto.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal"] },
  cafe43: { nome: "Omelete de peito de peru e queijo prato com shake de whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [2, 2, 2, 2] }, { a: 'peitoPeru', q: [3, 3, 3, 3] }, { a: 'queijoPrato', q: [1, 1, 1, 1] }, { a: 'leite', q: [150, 250, 300, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Omelete leve com peito de peru picado e queijo prato derretido.", tempo: 10, passos: ["Pique o peito de peru em tiras.","Bata os ovos com uma pitada de sal e pimenta-do-reino.","Despeje em frigideira antiaderente em fogo médio e distribua o peru e o queijo prato.","Dobre quando firmar por baixo e tampe por 1 minuto.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal","pimenta-do-reino"] },
  cafe44: { nome: "Sanduíche quente de frango com queijo prato e shake de whey", categoria: 'cafe', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'frango', q: [25, 40, 40, 40] }, { a: 'queijoPrato', q: [1, 1, 1, 1] }, { a: 'leite', q: [200, 250, 300, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Pão de forma na sanduicheira, recheado com frango desfiado e queijo prato.", tempo: 8, passos: ["Desfie o frango e tempere com uma pitada de sal.","Espalhe o frango em uma fatia de pão, cubra com o queijo prato e feche com a outra fatia.","Leve à sanduicheira por 3 a 4 minutos, até dourar e o queijo derreter.","Corte ao meio na diagonal.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal"] },
  cafe45: { nome: "Sanduíche frio de peito de peru com alface e tomate e shake de whey", categoria: 'cafe', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'peitoPeru', q: [4, 4, 4, 4] }, { a: 'requeijao', q: [5, 10, 10, 5] }, { a: 'alface', q: [2, 2, 2, 2] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'leite', q: [250, 300, 350, 200] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Sanduíche frio com peito de peru, requeijão, alface e tomate.", tempo: 6, passos: ["Passe o requeijão nas duas fatias de pão.","Distribua o peito de peru e cubra com as folhas de alface e as rodelas de tomate.","Tempere o tomate com uma pitada de sal e feche o sanduíche.","Corte ao meio na diagonal.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal"] },
  cafe46: { nome: "Pão sírio quente com ovo e mussarela e shake de whey", categoria: 'cafe', itens: [{ a: 'paoSirio', q: [1, 1, 1, 1] }, { a: 'ovo', q: [1, 2, 2, 1] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 100, 100, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Pão sírio recheado com ovo mexido e mussarela derretida.", tempo: 10, passos: ["Mexa os ovos na frigideira antiaderente com uma pitada de sal, em fogo baixo, por 2 minutos.","Abra o pão sírio ao meio e ponha a mussarela dentro.","Recheie com os ovos mexidos.","Aqueça o pão sírio na frigideira seca por 1 minuto de cada lado, até o queijo derreter.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  cafe47: { nome: "Wrap de ovo mexido, catupiry e alface e shake de whey", categoria: 'cafe', itens: [{ a: 'wrap', q: [1, 1, 1, 1] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'catupiry', q: [15, 10, 10, 10] }, { a: 'alface', q: [2, 2, 2, 2] }, { a: 'leite', q: [100, 200, 250, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Wrap quente com ovo mexido, catupiry e alface.", tempo: 8, passos: ["Mexa os ovos com uma pitada de sal na frigideira antiaderente, em fogo baixo, por 2 minutos, e misture o catupiry no fim.","Aqueça o disco de wrap 20 segundos de cada lado na frigideira.","Coloque as folhas de alface e o ovo com catupiry no centro.","Dobre as laterais, enrole e deixe 1 minuto na frigideira com a emenda para baixo.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal"] },
  cafe48: { nome: "Wrap de peito de peru, queijo prato e tomate e shake de whey", categoria: 'cafe', itens: [{ a: 'wrap', q: [1, 1, 1, 1] }, { a: 'peitoPeru', q: [3, 3, 3, 3] }, { a: 'queijoPrato', q: [1, 1, 1, 1] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'leite', q: [200, 300, 350, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Wrap com peito de peru, queijo prato e tomate, aquecido na frigideira.", tempo: 8, passos: ["Aqueça o disco de wrap 20 segundos na frigideira.","Coloque o queijo prato, o peito de peru e as rodelas de tomate no centro.","Enrole firme e leve à frigideira com a emenda para baixo por 1 a 2 minutos, até o queijo amolecer.","Corte ao meio.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"] },
  cafe49: { nome: "Panqueca de maçã com canela e shake de whey", categoria: 'cafe', itens: [{ a: 'ovo', q: [2, 2, 2, 2] }, { a: 'aveia', q: [20, 35, 35, 15] }, { a: 'macaFruta', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 100, 150, 100] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Panqueca de ovo e aveia com maçã ralada e canela.", tempo: 12, passos: ["Rale a maçã com casca.","Misture a maçã com os ovos, a aveia e uma pitada de canela.","Aqueça a frigideira antiaderente em fogo médio e despeje a massa.","Deixe 2 minutos de cada lado, até dourar.","Bata o shake de whey e creatina no leite e beba junto."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  cafe50: { nome: "Tapioca de carne seca com requeijão e shake de whey", categoria: 'cafe', itens: [{ a: 'tapioca', q: [60, 60, 70, 40] }, { a: 'carneSeca', q: [20, 25, 30, 30] }, { a: 'requeijao', q: [10, 15, 10, 10] }, { a: 'leite', q: [200, 250, 250, 200] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Tapioca recheada com carne seca desfiada e requeijão.", tempo: 10, passos: ["Pegue a carne seca já dessalgada e desfiada no preparo da semana e aqueça na frigideira por 2 minutos, ou 40 segundos no micro-ondas.","Espalhe a goma de tapioca em frigideira antiaderente seca, em fogo médio, formando um disco.","Quando firmar, 1 minuto, vire e passe o requeijão em metade do disco.","Coloque a carne seca, dobre e deixe 30 segundos.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"] },
  cafe51: { nome: "Cuscuz nordestino com carne seca e ovo e shake de whey", categoria: 'cafe', itens: [{ a: 'cuscuz', q: [140, 160, 170, 90] }, { a: 'carneSeca', q: [20, 20, 25, 20] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 150, 150, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Cuscuz de milho com carne seca desfiada e ovo frito.", tempo: 12, passos: ["Misture o flocão com uma pitada de sal e só a água necessária para umedecer; deixe 2 minutos.","Cozinhe no micro-ondas em pote tampado por 3 minutos e solte com um garfo.","Aqueça a carne seca desfiada na frigideira por 2 minutos.","Na mesma frigideira, frite o ovo até a clara firmar.","Sirva o cuscuz com a carne seca e o ovo por cima.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal","água"] },
  cafe52: { nome: "Pão de queijo recheado com frango e mussarela e shake de whey", categoria: 'cafe', itens: [{ a: 'paoQueijo', q: [2, 2, 2, 1] }, { a: 'frango', q: [25, 40, 40, 40] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 100, 150, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Pães de queijo assados e abertos, recheados com frango e mussarela derretida.", tempo: 15, passos: ["Leve os pães de queijo à airfryer a 180 graus por 8 minutos, ou ao forno a 200 graus por 12 minutos, se forem congelados.","Desfie o frango.","Abra cada pão de queijo ao meio e recheie com o frango e a mussarela.","Volte à airfryer a 180 graus por 2 minutos, até a mussarela derreter.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"] },
  cafe53: { nome: "Mingau de farinha láctea com whey", categoria: 'cafe', itens: [{ a: 'leite', q: [250, 300, 350, 250] }, { a: 'farinhaLactea', q: [30, 35, 35, 25] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Mingau de farinha láctea com banana; whey e creatina entram com o mingau morno.", tempo: 8, passos: ["Dissolva a farinha láctea no leite frio, em uma tigela própria para micro-ondas, mexendo com um garfo até não ter grumos.","Leve ao micro-ondas por 2 minutos, mexendo na metade, sem deixar ferver.","Mexa e cozinhe mais 1 minuto, até engrossar.","Deixe amornar 2 minutos e junte o whey e a creatina, mexendo bem para não empelotar.","Corte a banana por cima."], etiquetas: ["doce","vegetariano"] },
  cafe54: { nome: "Mingau de aveia com maçã e canela e whey", categoria: 'cafe', itens: [{ a: 'leite', q: [250, 300, 350, 250] }, { a: 'aveia', q: [35, 40, 40, 25] }, { a: 'macaFruta', q: [1, 1, 1, 1] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Mingau de aveia com maçã picada e canela; whey e creatina entram com o mingau morno.", tempo: 10, passos: ["Pique a maçã em cubinhos.","Aqueça o leite no micro-ondas por 2 minutos, sem ferver.","Misture a aveia e a maçã e cozinhe mais 2 minutos, mexendo na metade.","Deixe amornar 2 minutos e junte o whey e a creatina, mexendo bem.","Polvilhe a canela por cima."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  cafe55: { nome: "Iogurte com granola e morangos e whey", categoria: 'cafe', itens: [{ a: 'iogurte', q: [230, 230, 280, 250] }, { a: 'granola', q: [50, 60, 60, 40] }, { a: 'morango', q: [110, 140, 150, 110] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Iogurte com whey e creatina, morangos e granola por cima.", tempo: 5, passos: ["Lave os morangos, tire as folhas e corte em fatias.","Misture o whey e a creatina no iogurte até ficar liso.","Monte no pote: iogurte, morangos e a granola por cima, para não amolecer."], etiquetas: ["doce","vegetariano"] },
  cafe56: { nome: "Iogurte com manga, aveia e mel e whey", categoria: 'cafe', itens: [{ a: 'iogurte', q: [210, 240, 280, 240] }, { a: 'manga', q: [120, 140, 160, 110] }, { a: 'aveia', q: [30, 35, 35, 25] }, { a: 'mel', q: [15, 15, 15, 10] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Iogurte com whey e creatina, manga em cubos, aveia e mel.", tempo: 5, passos: ["Corte a manga em cubos, sem casca nem caroço.","Misture o whey e a creatina no iogurte até ficar liso.","Junte a manga e a aveia e finalize com o fio de mel."], etiquetas: ["doce","vegetariano"] },
  cafe57: { nome: "Pão francês com frango desfiado e requeijão e shake de whey", categoria: 'cafe', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'frango', q: [40, 50, 50, 40] }, { a: 'requeijao', q: [10, 10, 10, 10] }, { a: 'leite', q: [200, 250, 300, 150] }, { a: 'whey', q: [30, 30, 30, 30] }, { a: 'creatina', q: [5, 5, 5, 5] }], preparo: "Pão francês na chapa, recheado com frango desfiado e requeijão.", tempo: 8, passos: ["Desfie o frango e misture com o requeijão e uma pitada de sal.","Abra o pão francês ao meio e recheie com o frango.","Leve à sanduicheira ou à frigideira tampada por 2 a 3 minutos, até aquecer e dourar.","Bata no liquidificador o leite, o whey e a creatina por 20 segundos."], etiquetas: ["salgado"], temperos: ["sal"] },
  lanche31: { nome: "Coxinha de frango com suco", categoria: 'lanche', itens: [{ a: 'coxinha', q: [2, 2, 2, 1] }, { a: 'sucoLaranja', q: [50, 100, 150, 300] }], preparo: "Coxinha assada na airfryer ou comprada na padaria, com suco na garrafinha.", tempo: 12, passos: ["Compre a coxinha pronta na padaria ou use coxinha caseira congelada.","Aqueça na airfryer a 180 graus por 6 minutos, para tirar a gordura e deixar crocante.","Deixe amornar 5 minutos e embrulhe em papel alumínio.","Esprema 1 laranja num copinho com tampa."], etiquetas: ["salgado","besteira"], levar: "Coxinha embrulhada para comer em até 3 horas. Depois disso, geladeira do trabalho. Suco no copinho, também gelado.", airfryer: "Airfryer a 180 graus por 6 minutos, virando na metade." },
  lanche32: { nome: "Joelho de presunto e queijo com suco", categoria: 'lanche', itens: [{ a: 'joelho', q: [1, 1, 1, 1] }, { a: 'sucoLaranja', q: [250, 350, 400, 200] }], preparo: "Joelho comprado na padaria e esquentado na airfryer.", tempo: 12, passos: ["Compre o joelho de presunto e queijo na padaria ou use um caseiro congelado.","Aqueça na airfryer a 170 graus por 6 minutos.","Deixe amornar 5 minutos e embrulhe em papel alumínio.","Encha a garrafinha com suco de laranja."], etiquetas: ["salgado","besteira"], levar: "Embrulhado, para comer em até 3 horas. Depois, geladeira do trabalho. Suco na garrafinha gelada.", airfryer: "Airfryer a 170 graus por 6 minutos." },
  lanche33: { nome: "Empada de frango com suco", categoria: 'lanche', itens: [{ a: 'empada', q: [1, 2, 2, 1] }, { a: 'sucoLaranja', q: [300, 50, 100, 250] }], preparo: "Empada comprada na padaria, aquecida na airfryer.", tempo: 10, passos: ["Compre a empada de frango na padaria ou use uma caseira congelada.","Aqueça na airfryer a 160 graus por 5 minutos.","Deixe esfriar 5 minutos antes de embalar.","Embrulhe em papel alumínio e leve o suco em uma garrafinha."], etiquetas: ["salgado","besteira"], levar: "Empada embrulhada para comer em até 3 horas. Depois, geladeira do trabalho. Suco na garrafinha gelada.", airfryer: "Airfryer a 160 graus por 5 minutos." },
  lanche34: { nome: "Esfiha assada de frango com suco", categoria: 'lanche', itens: [{ a: 'esfihaFrango', q: [1, 1, 1, 1] }, { a: 'sucoLaranja', q: [100, 200, 250, 100] }], preparo: "Esfiha assada em casa ou comprada pronta, com suco na garrafinha.", tempo: 15, passos: ["Compre a esfiha de frango pronta na padaria, ou use a caseira do freezer.","Aqueça no forno a 200 graus por 8 minutos ou na airfryer a 180 graus por 5 minutos.","Deixe amornar 5 minutos e embrulhe em papel alumínio.","Esprema 2 laranjas num copinho com tampa."], etiquetas: ["salgado","besteira"], levar: "Esfiha embrulhada para comer em até 3 horas. Depois, geladeira do trabalho. Suco no copinho, gelado.", airfryer: "Airfryer a 180 graus por 5 minutos." },
  lanche35: { nome: "Pão de queijo recheado com catupiry e leite", categoria: 'lanche', itens: [{ a: 'paoQueijo', q: [1, 1, 2, 1] }, { a: 'catupiry', q: [5, 10, 5, 5] }, { a: 'leite', q: [200, 200, 100, 150] }], preparo: "Pão de queijo quente aberto e recheado com catupiry.", tempo: 15, passos: ["Asse os pães de queijo na airfryer a 180 graus por 8 minutos.","Deixe amornar 2 minutos e abra cada um ao meio com uma faca.","Recheie com o catupiry e feche.","Embrulhe em papel alumínio e despeje o leite na garrafa térmica."], etiquetas: ["salgado","besteira","vegetariano"], levar: "Pães embrulhados para comer em até 3 horas. Depois, geladeira do trabalho. Leite em garrafa térmica gelada.", airfryer: "Airfryer a 180 graus por 8 minutos." },
  lanche36: { nome: "Sanduíche natural de frango com cenoura e alface", categoria: 'lanche', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'frango', q: [50, 70, 70, 40] }, { a: 'cenoura', q: [30, 25, 50, 30] }, { a: 'alface', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [5, 5, 10, 5] }], preparo: "Frango desfiado com requeijão, cenoura ralada e alface.", tempo: 8, passos: ["Desfie o frango da marmita e misture com o requeijão e uma pitada de sal.","Rale a cenoura fina e escorra o excesso de água.","Espalhe o frango em uma fatia de pão e cubra com a cenoura e a folha de alface seca.","Feche com a outra fatia e embrulhe apertado."], etiquetas: ["salgado"], temperos: ["sal"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, sem esquentar." },
  lanche37: { nome: "Wrap de frango com tomate e alface", categoria: 'lanche', itens: [{ a: 'wrap', q: [1, 1, 1, 1] }, { a: 'frango', q: [50, 70, 80, 50] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'alface', q: [2, 2, 2, 2] }, { a: 'requeijao', q: [10, 10, 10, 5] }], preparo: "Frango, tomate e alface enrolados no wrap.", tempo: 10, passos: ["Desfie o frango e misture com o requeijão e uma pitada de sal.","Seque bem as folhas de alface e as rodelas de tomate com papel toalha.","Espalhe o frango no disco de wrap, cubra com a alface e o tomate.","Dobre as laterais, enrole apertado e embrulhe em papel alumínio."], etiquetas: ["salgado"], temperos: ["sal"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche38: { nome: "Sanduíche de peito de peru com queijo e tomate", categoria: 'lanche', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'peitoPeru', q: [2, 3, 3, 1] }, { a: 'queijoPrato', q: [1, 1, 1, 1] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'alface', q: [1, 1, 1, 1] }], preparo: "Peito de peru, queijo prato, tomate e alface no pão de forma.", tempo: 5, passos: ["Seque as rodelas de tomate e a folha de alface com papel toalha.","Em uma fatia de pão, monte o queijo, o peito de peru, o tomate e a alface.","Feche com a outra fatia e pressione de leve.","Embrulhe em papel alumínio."], etiquetas: ["salgado"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche39: { nome: "Bolo de cenoura caseiro com leite na garrafa", categoria: 'lanche', itens: [{ a: 'bolo', q: [1, 1, 1, 1] }, { a: 'cenoura', q: [40, 35, 10, 10] }, { a: 'leite', q: [50, 100, 150, 50] }], preparo: "Fatia de bolo de cenoura caseiro com leite na garrafa térmica.", tempo: 5, passos: ["No domingo, bata no liquidificador 3 cenouras médias descascadas, 3 ovos, meia xícara de óleo e 1 xícara de açúcar. Esses ingredientes do bolo inteiro não pesam na porção: o item bolo já representa a fatia.","Misture à massa 2 xícaras de farinha de trigo e 1 colher de sopa de fermento. Asse em forma untada a 180 graus por 40 minutos e guarde em pote fechado.","Corte uma fatia, espalhe a cenoura ralada por cima (ou misture-a à massa antes de assar) e embrulhe em papel alumínio.","Despeje o leite na garrafa térmica gelada.","Leve a fatia e o leite na mochila."], etiquetas: ["doce","vegetariano"], levar: "Bolo embrulhado na mochila, aguenta o dia. Leite em garrafa térmica gelada." },
  lanche40: { nome: "Pão sírio com frango e requeijão", categoria: 'lanche', itens: [{ a: 'paoSirio', q: [1, 1, 1, 1] }, { a: 'frango', q: [35, 50, 60, 30] }, { a: 'requeijao', q: [5, 5, 10, 5] }], preparo: "Frango desfiado com requeijão no pão sírio.", tempo: 8, passos: ["Desfie o frango da marmita e misture com o requeijão e uma pitada de sal.","Abra o pão sírio ao meio, formando um bolso.","Recheie com a mistura e dobre as pontas.","Embrulhe em papel alumínio."], etiquetas: ["salgado"], temperos: ["sal"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche41: { nome: "Pão de queijo com requeijão e achocolatado", categoria: 'lanche', itens: [{ a: 'paoQueijo', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [10, 10, 5, 5] }, { a: 'leite', q: [100, 150, 200, 100] }, { a: 'achocolatado', q: [10, 10, 10, 10] }], preparo: "Pão de queijo quente aberto com requeijão, com achocolatado gelado na garrafa.", tempo: 15, passos: ["Asse o pão de queijo na airfryer a 180 graus por 8 minutos.","Deixe amornar 2 minutos, abra ao meio e passe só um fio de requeijão.","Feche e embrulhe bem apertado em papel alumínio, ainda morno, para manter a maciez.","Bata o leite com o achocolatado até dissolver e despeje na garrafa térmica."], etiquetas: ["salgado","besteira","vegetariano"], levar: "Pão de queijo bem embrulhado: fica bom em temperatura ambiente por até 3 horas, sem esquentar de novo. Depois, geladeira do trabalho. Achocolatado em garrafa térmica gelada.", airfryer: "Airfryer a 180 graus por 8 minutos." },
  lanche42: { nome: "Mini sanduíche de mortadela com catupiry", categoria: 'lanche', itens: [{ a: 'bisnaguinha', q: [3, 3, 3, 2] }, { a: 'mortadela', q: [1, 1, 1, 1] }, { a: 'catupiry', q: [5, 15, 25, 20] }], preparo: "Três bisnaguinhas recheadas com mortadela e catupiry.", tempo: 6, passos: ["Abra cada bisnaguinha ao meio sem separar as metades.","Passe o catupiry no miolo de cada uma.","Divida a mortadela em três pedaços e coloque um em cada pão.","Feche e arrume em um pote com tampa."], etiquetas: ["salgado","besteira"], levar: "Pote fechado, aguenta 3 horas na mochila. Depois, geladeira do trabalho." },
  lanche43: { nome: "Bolo com doce de leite e leite", categoria: 'lanche', itens: [{ a: 'bolo', q: [1, 1, 1, 1] }, { a: 'doceLeite', q: [5, 15, 10, 5] }, { a: 'leite', q: [50, 50, 100, 50] }], preparo: "Fatia de bolo recheada com doce de leite e leite gelado na garrafa.", tempo: 5, passos: ["Corte uma fatia de bolo simples e abra ao meio na horizontal.","Passe o doce de leite no meio e feche.","Embrulhe em papel alumínio.","Despeje o leite na garrafa térmica gelada."], etiquetas: ["doce","besteira","vegetariano"], levar: "Bolo embrulhado, aguenta o dia na mochila. Leite em garrafa térmica gelada." },
  lanche44: { nome: "Esfiha de carne com catupiry", categoria: 'lanche', itens: [{ a: 'esfiha', q: [1, 1, 1, 1] }, { a: 'catupiry', q: [10, 25, 30, 5] }], preparo: "Esfiha de carne assada com catupiry por cima.", tempo: 14, passos: ["Compre a esfiha de carne pronta na padaria ou use a caseira do freezer.","Cubra a esfiha só com um fio de catupiry, para não escorrer depois de fria.","Asse na airfryer a 180 graus por 6 minutos, até o catupiry derreter.","Deixe amornar 5 minutos e embrulhe bem apertada em papel alumínio."], etiquetas: ["salgado","besteira"], levar: "Esfiha bem embrulhada: fica boa em temperatura ambiente por até 3 horas, sem esquentar de novo. Depois, geladeira do trabalho.", airfryer: "Airfryer a 180 graus por 6 minutos." },
  lanche45: { nome: "Wrap de ovo com tomate e alface", categoria: 'lanche', itens: [{ a: 'wrap', q: [1, 1, 1, 1] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'alface', q: [1, 1, 1, 1] }, { a: 'maionese', q: [10, 20, 30, 5] }], preparo: "Ovo cozido amassado com maionese, tomate e alface no wrap.", tempo: 15, passos: ["Cozinhe o ovo em água fervente por 10 minutos, esfrie, descasque e amasse com um garfo.","Misture o ovo com a maionese e uma pitada de sal.","Seque o tomate e a alface com papel toalha.","Espalhe o ovo no disco de wrap e cubra com o tomate e a alface.","Dobre as laterais, enrole apertado e embrulhe em papel alumínio."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"], levar: "Ovo estraga rápido: leve na geladeira do trabalho e coma em até 4 horas." },
  lanche46: { nome: "Sanduíche de queijo minas com cenoura e alface", categoria: 'lanche', itens: [{ a: 'paoForma', q: [2, 2, 2, 2] }, { a: 'minas', q: [35, 50, 50, 30] }, { a: 'cenoura', q: [30, 10, 60, 25] }, { a: 'alface', q: [1, 1, 1, 1] }], preparo: "Queijo minas, cenoura ralada e alface no pão de forma.", tempo: 6, passos: ["Corte o queijo minas em fatias finas.","Rale a cenoura fina e escorra o excesso de água.","Monte o pão de forma com o queijo, a cenoura e a folha de alface seca.","Feche, pressione de leve e embrulhe em papel alumínio."], etiquetas: ["salgado","vegetariano"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche47: { nome: "Pão francês com peito de peru, maionese e alface", categoria: 'lanche', itens: [{ a: 'paoFrances', q: [1, 1, 1, 1] }, { a: 'peitoPeru', q: [3, 3, 3, 3] }, { a: 'maionese', q: [10, 20, 25, 5] }, { a: 'alface', q: [2, 2, 2, 2] }, { a: 'tomate', q: [2, 2, 2, 2] }], preparo: "Pão francês recheado com peito de peru, maionese, alface e tomate.", tempo: 8, passos: ["Passe a maionese no pão francês aberto ao meio.","Seque a alface e o tomate com papel toalha.","Abra o pão francês ao meio e recheie com o peito de peru dobrado, a alface e o tomate.","Embrulhe em papel alumínio."], etiquetas: ["salgado"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche48: { nome: "Pão de hambúrguer com peito de peru, queijo prato, alface e tomate", categoria: 'lanche', itens: [{ a: 'paoHamburguer', q: [1, 1, 1, 1] }, { a: 'peitoPeru', q: [1, 3, 3, 1] }, { a: 'queijoPrato', q: [1, 1, 1, 1] }, { a: 'alface', q: [1, 1, 1, 1] }, { a: 'tomate', q: [2, 2, 2, 1] }], preparo: "Pão de hambúrguer frio com peito de peru, queijo prato, alface e tomate.", tempo: 5, passos: ["Abra o pão de hambúrguer ao meio e coloque o queijo prato na metade de baixo.","Cubra com o peito de peru dobrado.","Cubra com a alface e o tomate secos com papel toalha.","Feche e embrulhe em papel alumínio."], etiquetas: ["salgado"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche49: { nome: "Wrap de peito de peru com queijo e cenoura", categoria: 'lanche', itens: [{ a: 'wrap', q: [1, 1, 1, 1] }, { a: 'peitoPeru', q: [3, 3, 3, 2] }, { a: 'queijoPrato', q: [1, 1, 1, 1] }, { a: 'cenoura', q: [10, 70, 130, 10] }, { a: 'alface', q: [2, 2, 2, 2] }], preparo: "Peito de peru, queijo prato, cenoura ralada e alface no wrap.", tempo: 7, passos: ["Rale a cenoura fina e escorra o excesso de água.","Coloque o queijo prato e o peito de peru sobre o disco de wrap.","Cubra com a cenoura e a alface seca.","Dobre as laterais, enrole apertado e embrulhe em papel alumínio."], etiquetas: ["salgado"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche50: { nome: "Wrap mexicano de carne moída com tomate", categoria: 'lanche', itens: [{ a: 'wrap', q: [1, 1, 1, 1] }, { a: 'moida', q: [30, 40, 60, 40] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'alface', q: [1, 1, 1, 1] }, { a: 'catupiry', q: [15, 20, 10, 5] }], preparo: "Carne moída da semana com tomate, alface e catupiry enrolados no wrap.", receita: 'carneMoida', tempo: 8, passos: ["Separe a carne moída da semana, já refogada e fria.","Tempere a carne com uma pitada de páprica e cominho.","Espalhe o catupiry no disco de wrap e cubra com a carne, o tomate e a alface secos.","Dobre as laterais, enrole apertado e embrulhe em papel alumínio."], etiquetas: ["salgado"], temperos: ["páprica","cominho"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche51: { nome: "Wrap de presunto, mussarela e alface", categoria: 'lanche', itens: [{ a: 'wrap', q: [1, 1, 1, 1] }, { a: 'presunto', q: [2, 2, 2, 1] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [10, 20, 25, 10] }, { a: 'alface', q: [2, 2, 2, 2] }], preparo: "Presunto, mussarela, requeijão e alface enrolados no wrap.", tempo: 5, passos: ["Espalhe o requeijão no disco de wrap e coloque a mussarela e o presunto.","Cubra com a alface seca.","Dobre as laterais e enrole apertado.","Embrulhe em papel alumínio."], etiquetas: ["salgado"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche52: { nome: "Vitamina de banana com aveia na garrafa", categoria: 'lanche', itens: [{ a: 'leite', q: [150, 150, 200, 150] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'aveia', q: [15, 25, 20, 10] }], preparo: "Banana, aveia e leite batidos e levados na garrafa térmica.", tempo: 5, passos: ["Bata o leite, a banana e a aveia no liquidificador por 40 segundos.","Despeje na garrafa térmica gelada.","Feche bem."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica com gelo por dentro ou bolsa térmica. Beba em até 4 horas." },
  lanche53: { nome: "Vitamina de manga com iogurte na garrafa", categoria: 'lanche', itens: [{ a: 'iogurte', q: [160, 170, 180, 160] }, { a: 'leite', q: [100, 100, 150, 100] }, { a: 'manga', q: [100, 110, 110, 80] }, { a: 'mel', q: [5, 10, 5, 5] }], preparo: "Manga, iogurte e leite batidos, com um fio de mel.", tempo: 5, passos: ["Bata o iogurte, o leite, a manga e o mel no liquidificador por 40 segundos.","Despeje na garrafa térmica gelada.","Feche bem e beba em até 4 horas."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica com gelo por dentro ou bolsa térmica. Beba em até 4 horas." },
  lanche54: { nome: "Vitamina de mamão com aveia na garrafa", categoria: 'lanche', itens: [{ a: 'leite', q: [200, 200, 250, 200] }, { a: 'mamao', q: [80, 120, 130, 100] }, { a: 'aveia', q: [15, 15, 15, 10] }, { a: 'mel', q: [5, 10, 5, 5] }], preparo: "Mamão, aveia e leite batidos e levados na garrafa térmica.", tempo: 5, passos: ["Bata o leite, o mamão, a aveia e o mel no liquidificador por 40 segundos.","Despeje na garrafa térmica gelada.","Feche bem e beba em até 4 horas."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica com gelo por dentro ou bolsa térmica. Beba em até 4 horas." },
  lanche55: { nome: "Iogurte batido de morango com aveia", categoria: 'lanche', itens: [{ a: 'iogurte', q: [100, 120, 140, 110] }, { a: 'leite', q: [100, 100, 100, 100] }, { a: 'morango', q: [80, 80, 110, 80] }, { a: 'aveia', q: [20, 25, 25, 15] }, { a: 'mel', q: [5, 5, 5, 5] }], preparo: "Iogurte, leite, morango e aveia batidos na garrafa.", tempo: 5, passos: ["Bata o iogurte, o leite, o morango lavado, a aveia e o mel no liquidificador por 40 segundos.","Despeje na garrafa térmica gelada.","Feche bem e beba em até 4 horas."], etiquetas: ["doce","vegetariano"], levar: "Garrafa térmica com gelo por dentro ou bolsa térmica. Beba em até 4 horas." },
  lanche56: { nome: "Iogurte com granola e morango no pote", categoria: 'lanche', itens: [{ a: 'iogurte', q: [170, 180, 180, 180] }, { a: 'granola', q: [30, 35, 40, 25] }, { a: 'morango', q: [60, 70, 70, 60] }], preparo: "Iogurte com morango picado e granola separada para não amolecer.", tempo: 5, passos: ["Lave o morango, seque e corte em pedaços.","Coloque o iogurte e o morango em um pote com tampa.","Ponha a granola em um potinho separado, para não amolecer.","Na hora de comer, misture a granola no iogurte."], etiquetas: ["doce","vegetariano"], levar: "Iogurte com morango na geladeira do trabalho. Granola em potinho na mochila." },
  lanche57: { nome: "Iogurte com granola e manga picada", categoria: 'lanche', itens: [{ a: 'iogurte', q: [130, 130, 150, 130] }, { a: 'granola', q: [20, 25, 25, 20] }, { a: 'manga', q: [110, 120, 140, 90] }], preparo: "Iogurte com manga em cubos e granola crocante.", tempo: 3, passos: ["Corte a manga em cubos, sem casca nem caroço.","Coloque o iogurte e a manga em um pote com tampa.","Ponha a granola em um potinho separado.","Na hora, misture a granola no iogurte com a manga."], etiquetas: ["doce","vegetariano"], levar: "Iogurte com manga na geladeira do trabalho. Granola em potinho na mochila." },
  lanche58: { nome: "Cuscuz no pote com queijo minas e tomate", categoria: 'lanche', itens: [{ a: 'cuscuz', q: [140, 170, 170, 110] }, { a: 'minas', q: [25, 25, 30, 30] }, { a: 'tomate', q: [2, 2, 2, 2] }], preparo: "Cuscuz com cubos de queijo minas e tomate.", tempo: 12, passos: ["Hidrate o cuscuz com água quente e uma pitada de sal; ele pode estar pronto do dia anterior.","Corte o queijo minas em cubos pequenos.","Coloque o cuscuz no pote e cubra com o queijo.","Leve as rodelas de tomate separadas, em outro potinho, para o cuscuz não ficar mole."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"], levar: "Pote fechado na geladeira do trabalho. Come frio ou morno, em até 4 horas." },
  lanche59: { nome: "Biscoito cream cracker com peito de peru e requeijão", categoria: 'lanche', itens: [{ a: 'creamCracker', q: [40, 40, 50, 30] }, { a: 'peitoPeru', q: [3, 3, 3, 4] }, { a: 'requeijao', q: [5, 15, 5, 10] }], preparo: "Biscoito com requeijão e peito de peru dobrado.", tempo: 4, passos: ["Coloque o cream cracker em um pote com tampa.","Guarde o requeijão em um potinho pequeno.","Dobre o peito de peru em um pote separado.","Na hora, passe o requeijão no biscoito e cubra com o peito de peru."], etiquetas: ["salgado"], levar: "Requeijão e peito de peru na geladeira do trabalho. Biscoito em pote fechado na mochila." },
  lanche60: { nome: "Morango com pasta de amendoim", categoria: 'lanche', itens: [{ a: 'morango', q: [280, 280, 340, 230] }, { a: 'pastaAmendoim', q: [25, 30, 30, 25] }], preparo: "Morangos inteiros para molhar na pasta de amendoim.", tempo: 4, passos: ["Lave os morangos, seque bem e tire as folhinhas.","Arrume em um pote com tampa.","Coloque a pasta de amendoim em um potinho e molhe os morangos na hora."], etiquetas: ["doce","vegetariano"], levar: "Aguenta 3 horas na mochila. Depois disso, geladeira do trabalho." },
  lanche61: { nome: "Banana com pasta de amendoim e granola", categoria: 'lanche', itens: [{ a: 'banana', q: [1, 1, 1, 1] }, { a: 'pastaAmendoim', q: [5, 10, 10, 5] }, { a: 'granola', q: [30, 30, 35, 25] }], preparo: "Banana inteira com pasta de amendoim e granola crocante.", tempo: 3, passos: ["Coloque a pasta de amendoim em um potinho com tampa.","Ponha a granola em outro potinho.","Leve a banana inteira, com casca.","Na hora, passe a pasta na banana em pedaços e polvilhe a granola."], etiquetas: ["doce","vegetariano"], levar: "Aguenta o dia todo na mochila, sem geladeira." },
  lanche62: { nome: "Pão sírio com peito de peru, catupiry e alface", categoria: 'lanche', itens: [{ a: 'paoSirio', q: [1, 1, 1, 1] }, { a: 'peitoPeru', q: [2, 2, 2, 2] }, { a: 'catupiry', q: [10, 25, 30, 5] }, { a: 'alface', q: [2, 2, 2, 2] }], preparo: "Pão sírio recheado com peito de peru, catupiry e alface.", tempo: 5, passos: ["Abra o pão sírio ao meio, formando um bolso.","Passe o catupiry por dentro.","Recheie com o peito de peru dobrado e a alface seca.","Dobre as pontas e embrulhe em papel alumínio."], etiquetas: ["salgado"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche63: { nome: "Pão sírio com queijo minas, tomate e alface", categoria: 'lanche', itens: [{ a: 'paoSirio', q: [1, 1, 1, 1] }, { a: 'minas', q: [20, 35, 40, 15] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'alface', q: [2, 2, 2, 2] }], preparo: "Pão sírio com queijo minas, tomate e alface, à moda árabe.", tempo: 6, passos: ["Corte o queijo minas em fatias finas.","Seque o tomate e a alface com papel toalha.","Abra o pão sírio ao meio e recheie com o queijo, o tomate e a alface.","Dobre as pontas e embrulhe em papel alumínio."], etiquetas: ["salgado","vegetariano"], levar: "Embrulhado, na geladeira do trabalho. Come em até 4 horas, frio." },
  lanche64: { nome: "Bisnaguinhas com peito de peru e alface", categoria: 'lanche', itens: [{ a: 'bisnaguinha', q: [3, 3, 3, 3] }, { a: 'peitoPeru', q: [2, 2, 2, 2] }, { a: 'requeijao', q: [5, 20, 25, 5] }, { a: 'alface', q: [1, 1, 1, 1] }], preparo: "Três bisnaguinhas com peito de peru, requeijão e alface.", tempo: 6, passos: ["Abra cada bisnaguinha ao meio sem separar as metades.","Passe o requeijão no miolo.","Recheie com o peito de peru e um pedaço de alface seca em cada uma.","Feche e arrume em um pote com tampa."], etiquetas: ["salgado"], levar: "Pote fechado, aguenta 3 horas na mochila. Depois, geladeira do trabalho." },
  lanche65: { nome: "Mamão com iogurte e aveia", categoria: 'lanche', itens: [{ a: 'mamao', q: [140, 150, 160, 110] }, { a: 'iogurte', q: [160, 170, 200, 150] }, { a: 'aveia', q: [20, 25, 25, 20] }, { a: 'mel', q: [5, 5, 5, 5] }], preparo: "Mamão em cubos com iogurte, aveia e mel.", tempo: 5, passos: ["Corte o mamão em cubos e coloque em um pote com tampa.","Cubra com o iogurte.","Ponha a aveia em um potinho separado.","Leve o mel em um potinho pequeno e misture tudo na hora."], etiquetas: ["doce","vegetariano"], levar: "Pote com mamão e iogurte na geladeira do trabalho. Aveia e mel separados na mochila." },
  almoco31: { nome: "Lasanha de frango com catupiry", categoria: 'almoco', itens: [{ a: 'macarrao', q: [190, 210, 230, 150] }, { a: 'frango', q: [60, 80, 80, 90] }, { a: 'catupiry', q: [15, 15, 20, 15] }, { a: 'molhoTomate', q: [70, 90, 80, 60] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'presunto', q: [2, 2, 2, 2] }], preparo: "Camadas de massa, frango desfiado com catupiry, molho, presunto e queijo. Assa no domingo e corta em porções.", tempo: 70, passos: ["Cozinhe o frango em água com sal por 15 minutos e desfie. Misture com o catupiry e alho em pó.","Aqueça o molho de tomate com 1 copo de água por 3 minutos: ele precisa ficar ralo para cozinhar a massa.","Em travessa: molho, massa de lasanha direto ao forno, presunto, mussarela e frango com catupiry. Repita e termine com molho e queijo.","Forno a 200 graus, 30 minutos coberta com papel-alumínio e 10 sem ele.","Espere esfriar por 30 minutos, corte em porções e passe para os potes. Congele as que vão passar de 4 dias."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (6 se vier do congelador), tampa entreaberta." },
  almoco32: { nome: "Nhoque à bolonhesa gratinado", categoria: 'almoco', itens: [{ a: 'nhoque', q: [180, 210, 230, 150] }, { a: 'moida', q: [50, 60, 60, 70] }, { a: 'molhoTomate', q: [90, 70, 80, 70] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'parmesao', q: [5, 5, 5, 5] }], preparo: "Nhoque com bolonhesa, gratinado no forno com mussarela e parmesão.", receita: 'bolonhesa', tempo: 50, passos: ["Molho à bolonhesa: veja o preparo de domingo.","Cozinhe o nhoque em água fervente com sal até boiar, cerca de 2 minutos. Escorra.","Misture o nhoque com metade do molho em refratário e cubra com o resto do molho.","Distribua a mussarela, o parmesão e uma pitada de orégano. Forno a 220 graus por 12 minutos, até gratinar.","Deixe esfriar e divida nos potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","orégano","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco33: { nome: "Nhoque com frango e molho de tomate", categoria: 'almoco', itens: [{ a: 'nhoque', q: [240, 270, 280, 200] }, { a: 'frango', q: [80, 90, 100, 100] }, { a: 'molhoTomate', q: [90, 90, 110, 90] }, { a: 'parmesao', q: [5, 5, 5, 10] }], preparo: "Frango em cubos no molho de tomate, sobre o nhoque, com parmesão.", tempo: 35, passos: ["Corte o frango em cubos, tempere com sal e alho em pó e doure em frigideira antiaderente por 6 minutos.","Junte o molho de tomate, uma pitada de orégano e 1 copo de água e cozinhe por 8 minutos em fogo baixo.","Cozinhe o nhoque em água fervente com sal até boiar, cerca de 2 minutos. Escorra e passe em água fria.","Divida o nhoque nos potes e cubra com o frango ao molho. Parmesão por cima."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","orégano","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta, mexendo na metade." },
  almoco34: { nome: "Panqueca caseira de carne moída", categoria: 'almoco', itens: [{ a: 'farinhaTrigo', q: [50, 50, 60, 40] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 150, 150, 100] }, { a: 'moida', q: [70, 90, 90, 80] }, { a: 'molhoTomate', q: [70, 60, 70, 50] }, { a: 'mussarela', q: [2, 2, 2, 2] }], preparo: "Massa de panqueca feita em casa, recheio de carne moída, molho e queijo por cima.", receita: 'carneMoida', tempo: 60, passos: ["Bata no liquidificador a farinha, o ovo, o leite e uma pitada de sal, até ficar liso. Descanse 10 minutos.","Em frigideira antiaderente, 3 colheres de massa por vez, 1 minuto de cada lado, sem óleo.","Carne moída da semana: veja o preparo de domingo. Recheie cada panqueca e enrole.","Arrume em refratário, cubra com o molho de tomate, uma pitada de orégano e a mussarela. Forno a 200 graus por 12 minutos.","Deixe esfriar e divida nos potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","orégano"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco35: { nome: "Escondidinho de carne seca", categoria: 'almoco', itens: [{ a: 'pure', q: [320, 380, 400, 270] }, { a: 'carneSeca', q: [70, 70, 80, 80] }, { a: 'catupiry', q: [5, 10, 5, 5] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Carne seca desfiada embaixo, purê por cima, catupiry e queijo gratinados.", receita: 'pureBatata', tempo: 60, passos: ["Dessalgue a carne seca: ferva por 10 minutos, troque a água e ferva de novo por 30. Escorra e desfie.","Refogue a carne desfiada em frigideira antiaderente por 5 minutos com alho em pó e pimenta-do-reino.","Purê de batata: veja o preparo de domingo.","Em refratário próprio para forno, monte uma camada de carne, uma de catupiry, o purê e a mussarela por cima.","Forno a 220 graus por 10 minutos, até dourar. Deixe esfriar por 10 minutos, corte em porções e passe para os potes que vão ao micro-ondas."], etiquetas: ["salgado","marmita"], temperos: ["alho em pó","pimenta-do-reino","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco36: { nome: "Macarrão de forno com presunto e queijo", categoria: 'almoco', itens: [{ a: 'macarrao', q: [250, 290, 300, 230] }, { a: 'presunto', q: [2, 2, 2, 2] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'molhoTomate', q: [60, 80, 90, 60] }, { a: 'cremeLeite', q: [20, 20, 30, 25] }], preparo: "Macarrão com molho, creme de leite, presunto e queijo, gratinado no forno.", tempo: 45, passos: ["Cozinhe o macarrão em água com sal, 3 minutos a menos que o tempo da embalagem. Escorra.","Misture o molho de tomate com o creme de leite, uma pitada de orégano e uma pitada de sal.","Em refratário: macarrão, molho, presunto picado e metade da mussarela. Misture bem.","Cubra com o resto da mussarela. Forno a 200 graus por 20 minutos, até gratinar.","Deixe esfriar e divida nos potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","orégano","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco37: { nome: "Frango à parmegiana assado com arroz", categoria: 'almoco', itens: [{ a: 'frango', q: [80, 100, 100, 100] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'farinhaRosca', q: [10, 15, 20, 10] }, { a: 'parmesao', q: [5, 5, 5, 5] }, { a: 'molhoTomate', q: [60, 80, 70, 60] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'arroz', q: [160, 170, 190, 120] }], preparo: "Filé de frango empanado e assado, coberto com molho e queijo, sem fritura.", receita: 'arrozDaSemana', tempo: 55, passos: ["Corte o frango em filés finos e tempere com sal e alho em pó.","Passe no ovo batido e na farinha de rosca misturada com o parmesão.","Airfryer a 200 graus por 12 minutos, virando na metade. Sem airfryer, forno a 220 graus por 20 minutos.","Cubra cada filé com o molho de tomate, uma pitada de orégano e a mussarela e volte por 3 minutos, até derreter.","Arroz da semana: veja o preparo de domingo. Divida o arroz nos potes e coloque o frango ao lado."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","orégano"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta; o empanado perde a crocância, mas o molho mantém o frango macio.", airfryer: "Filé empanado na airfryer a 200 graus por 12 minutos, virando na metade." },
  almoco38: { nome: "Salada caesar com frango e arroz", categoria: 'almoco', itens: [{ a: 'alface', q: [8, 8, 8, 8] }, { a: 'frango', q: [110, 130, 130, 140] }, { a: 'crouton', q: [20, 25, 25, 15] }, { a: 'parmesao', q: [10, 10, 10, 10] }, { a: 'maionese', q: [10, 15, 20, 15] }, { a: 'arroz', q: [220, 220, 240, 170] }], preparo: "Frango e arroz esquentam; a alface, o molho e os croutons vão separados e se montam na hora.", receita: 'frangoDaSemana', tempo: 40, passos: ["Frango grelhado da semana: veja o preparo de domingo. Corte em tiras.","Arroz da semana: veja o preparo de domingo. Divida o arroz e o frango juntos em um pote.","Misture a maionese com metade do parmesão ralado, alho em pó, pimenta-do-reino e 1 colher de chá de água. Guarde em potinho com tampa.","Lave e seque bem a alface. Rasgue em pedaços e guarde em pote separado, com papel toalha por cima.","Croutons em saquinho à parte, e o resto do parmesão por cima na hora de comer."], etiquetas: ["salgado","marmita"], temperos: ["alho em pó","pimenta-do-reino","água"], levar: "Três potes na geladeira do trabalho: frango com arroz, alface com o molho à parte e croutons no saquinho. Micro-ondas por 2 minutos só no pote do frango e do arroz; depois, junte a alface fria com o molho e os croutons por cima." },
  almoco39: { nome: "Carne de panela com batata ao murro", categoria: 'almoco', itens: [{ a: 'carnePanela', q: [110, 120, 130, 140] }, { a: 'batata', q: [250, 300, 320, 230] }, { a: 'arroz', q: [180, 200, 210, 130] }, { a: 'azeite', q: [5, 5, 5, 5] }], preparo: "Carne de panela desfiada, batata assada e amassada no forno, arroz ao lado.", receita: 'arrozDaSemana', tempo: 70, passos: ["Cozinhe a carne de panela na pressão com água, sal e alho em pó por 40 minutos depois que chiar. Desfie com dois garfos.","Cozinhe a batata com casca por 15 minutos em água com sal, até ficar macia.","Amasse cada batata de leve com o fundo de um copo, regue com o azeite, sal e orégano.","Forno a 220 graus por 20 minutos, até as bordas dourarem.","Arroz da semana: veja o preparo de domingo. Monte os potes com arroz, carne com um pouco do caldo e batata."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","orégano","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta; o caldo da carne mantém tudo macio." },
  almoco40: { nome: "Frango agridoce com amendoim e arroz", categoria: 'almoco', itens: [{ a: 'frango', q: [130, 140, 150, 170] }, { a: 'amendoim', q: [10, 10, 10, 5] }, { a: 'ketchup', q: [20, 25, 25, 20] }, { a: 'arroz', q: [240, 260, 280, 200] }, { a: 'maisena', q: [5, 10, 10, 5] }], preparo: "Frango em cubos em molho agridoce de ketchup, com amendoim por cima.", receita: 'arrozDaSemana', tempo: 35, passos: ["Corte o frango em cubos e tempere com sal, alho em pó e pimenta-do-reino.","Doure o frango em frigideira antiaderente por 8 minutos, mexendo.","Esfarele o biscoito maisena e misture com o ketchup, 1/2 copo de água e uma pitada de páprica. Despeje na frigideira e deixe 3 minutos até engrossar.","Desligue o fogo e misture o amendoim torrado.","Arroz da semana: veja o preparo de domingo. Divida o arroz nos potes e coloque o frango com molho por cima."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","pimenta-do-reino","páprica","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta; leve o amendoim em saquinho e junte por cima depois de esquentar." },
  almoco41: { nome: "Arroz de forno de linguiça", categoria: 'almoco', itens: [{ a: 'arroz', q: [240, 260, 270, 180] }, { a: 'linguica', q: [60, 80, 90, 90] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'cremeLeite', q: [15, 15, 15, 10] }], preparo: "Arroz misturado com linguiça e creme de leite, gratinado com mussarela.", tempo: 40, passos: ["Grelhe a linguiça em rodelas finas por 6 minutos, até dourar.","Misture o arroz com a linguiça, o creme de leite, sal e orégano.","Passe para um refratário e cubra com a mussarela.","Forno a 200 graus por 15 minutos, até gratinar.","Deixe esfriar por 10 minutos e divida nos potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","orégano"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta, mexendo na metade." },
  almoco42: { nome: "Risoto de frango", categoria: 'almoco', itens: [{ a: 'arroz', q: [290, 320, 340, 240] }, { a: 'frango', q: [100, 120, 120, 120] }, { a: 'parmesao', q: [10, 10, 10, 15] }, { a: 'cremeLeite', q: [20, 20, 25, 15] }], preparo: "Arroz cremoso com frango desfiado, creme de leite e parmesão.", tempo: 35, passos: ["Cozinhe o frango em água com sal por 15 minutos e desfie.","Em panela, aqueça o arroz cozido com 1 copo de caldo do frango, alho em pó e pimenta-do-reino por 5 minutos, mexendo, até ficar cremoso.","Junte o frango desfiado e o creme de leite e mexa por 2 minutos.","Desligue o fogo e misture metade do parmesão. Guarde o resto para a hora de comer.","Divida nos potes e deixe esfriar com a tampa aberta."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","pimenta-do-reino","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio com 1 colher de água por cima, tampa entreaberta, mexendo na metade para voltar a ficar cremoso. Leve o resto do parmesão em saquinho e polvilhe na hora de comer." },
  almoco43: { nome: "Macarrão rosé gratinado com frango", categoria: 'almoco', itens: [{ a: 'macarrao', q: [250, 270, 280, 210] }, { a: 'frango', q: [80, 90, 100, 110] }, { a: 'molhoTomate', q: [90, 90, 80, 40] }, { a: 'cremeLeite', q: [20, 20, 25, 15] }, { a: 'parmesao', q: [5, 10, 10, 10] }], preparo: "Macarrão com frango em molho rosé, gratinado com parmesão.", tempo: 40, passos: ["Cozinhe o macarrão em água com sal, 3 minutos a menos que o tempo da embalagem. Escorra.","Aqueça o molho de tomate com o creme de leite e uma pitada de orégano por 3 minutos, até ficar rosado.","Corte o frango em cubos, tempere com sal e alho em pó e grelhe por 8 minutos.","Misture o macarrão, o frango e o molho em refratário. Polvilhe o parmesão.","Forno a 200 graus por 15 minutos. Deixe esfriar e divida nos potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","orégano","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco44: { nome: "Nhoque ao sugo com almôndegas", categoria: 'almoco', itens: [{ a: 'nhoque', q: [220, 240, 260, 180] }, { a: 'moida', q: [70, 80, 80, 90] }, { a: 'molhoTomate', q: [70, 110, 120, 100] }, { a: 'parmesao', q: [10, 10, 10, 10] }], preparo: "Almôndegas de carne moída crua assadas e servidas com nhoque no molho de tomate.", tempo: 50, passos: ["Misture a carne moída crua com sal, alho em pó e pimenta-do-reino. Modele bolinhas do tamanho de uma noz.","Asse em forno a 200 graus por 15 minutos, virando na metade.","Cozinhe o nhoque em água fervente com sal até boiar, cerca de 2 minutos. Escorra.","Aqueça o molho de tomate com as almôndegas por 5 minutos em fogo baixo e junte o nhoque.","Divida nos potes e polvilhe o parmesão por cima."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","pimenta-do-reino","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco45: { nome: "Picadinho de carne com purê", categoria: 'almoco', itens: [{ a: 'patinho', q: [90, 110, 110, 120] }, { a: 'molhoTomate', q: [70, 50, 70, 50] }, { a: 'pure', q: [230, 250, 270, 190] }, { a: 'arroz', q: [130, 140, 150, 100] }], preparo: "Carne em cubos pequenos ao molho de tomate, purê e arroz.", receita: 'pureBatata', tempo: 50, passos: ["Purê de batata: veja o preparo de domingo.","Corte o patinho em cubos pequenos e tempere com sal, alho em pó e páprica.","Doure a carne na panela de pressão por 5 minutos, em duas levas.","Junte o molho de tomate e 1 copo de água, tampe e cozinhe por 25 a 30 minutos depois que chiar. Abra só depois de sair toda a pressão.","Divida purê, arroz e picadinho nos potes, cada um no seu canto."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco46: { nome: "Peito de frango assado ao alho com batata", categoria: 'almoco', itens: [{ a: 'frango', q: [140, 150, 160, 160] }, { a: 'batata', q: [260, 290, 290, 210] }, { a: 'arroz', q: [170, 200, 220, 150] }, { a: 'azeite', q: [5, 5, 5, 5] }], preparo: "Peito de frango e batata assados juntos no forno, com arroz.", receita: 'arrozDaSemana', tempo: 60, passos: ["Tempere o frango com sal, alho em pó e páprica. Deixe 15 minutos.","Em assadeira, junte o frango e a batata em gomos regados com o azeite e sal.","Cubra com papel-alumínio. Forno a 200 graus por 25 minutos; tire o papel e asse mais 15, virando a batata.","Deixe o frango descansar 10 minutos e corte em tiras.","Arroz da semana: veja o preparo de domingo. Monte os potes com arroz, frango e batata."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta; a tira de frango fica mais macia que o filé inteiro." },
  almoco47: { nome: "Almôndegas de frango ao molho com purê", categoria: 'almoco', itens: [{ a: 'frango', q: [120, 140, 140, 150] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'farinhaRosca', q: [15, 15, 20, 10] }, { a: 'molhoTomate', q: [80, 100, 110, 80] }, { a: 'pure', q: [270, 300, 320, 220] }], preparo: "Almôndegas de frango assadas, no molho de tomate, sobre purê.", receita: 'pureBatata', tempo: 55, passos: ["Purê de batata: veja o preparo de domingo.","Pique o frango cru em pedaços e bata no liquidificador em pulsos, até ficar moído. Misture com o ovo, a farinha de rosca, sal e alho em pó.","Modele bolinhas e asse em forno a 200 graus por 18 minutos, virando na metade.","Aqueça o molho de tomate, junte as almôndegas e deixe 5 minutos.","Divida o purê e as almôndegas com molho nos potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta." },
  almoco48: { nome: "Escondidinho de frango com catupiry", categoria: 'almoco', itens: [{ a: 'pure', q: [340, 390, 420, 290] }, { a: 'frango', q: [110, 120, 120, 130] }, { a: 'catupiry', q: [15, 15, 20, 15] }, { a: 'mussarela', q: [1, 1, 1, 1] }], preparo: "Frango desfiado com catupiry, coberto de purê e queijo gratinado.", receita: 'pureBatata', tempo: 45, passos: ["Purê de batata: veja o preparo de domingo.","Cozinhe o frango em água com sal por 15 minutos e desfie. Misture com o catupiry e alho em pó.","Em refratários individuais, espalhe o frango com catupiry no fundo.","Cubra com o purê, alise com as costas da colher e coloque a mussarela.","Forno a 220 graus por 10 minutos, até gratinar. Deixe esfriar antes de tampar."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco49: { nome: "Carne seca desfiada com purê cremoso", categoria: 'almoco', itens: [{ a: 'carneSeca', q: [60, 70, 70, 80] }, { a: 'pure', q: [270, 290, 320, 210] }, { a: 'arroz', q: [130, 140, 150, 110] }], preparo: "Carne seca dessalgada e refogada, purê e arroz.", receita: 'pureBatata', tempo: 50, passos: ["Na véspera, ponha a carne seca de molho em água na geladeira por 12 horas, trocando a água 3 vezes.","Purê de batata: veja o preparo de domingo.","Cozinhe a carne seca dessalgada na panela de pressão com água nova por 30 minutos depois que chiar. Escorra e desfie.","Refogue a carne seca desfiada em frigideira por 5 minutos com cebola em pó e pimenta-do-reino, sem sal.","Divida purê, arroz e carne seca nos potes."], etiquetas: ["salgado","marmita"], temperos: ["cebola em pó","pimenta-do-reino","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco50: { nome: "Arroz refogado com frango e cenoura ralada crua", categoria: 'almoco', itens: [{ a: 'arroz', q: [300, 330, 350, 250] }, { a: 'cenoura', q: [50, 50, 40, 40] }, { a: 'frango', q: [110, 130, 140, 140] }, { a: 'azeite', q: [5, 5, 5, 5] }], preparo: "Arroz refogado com frango em cubos e cenoura ralada crua por cima.", tempo: 30, passos: ["Corte o frango em cubos e tempere com sal, alho em pó e páprica. Grelhe por 8 minutos.","Aqueça o azeite e refogue o arroz cozido por 2 minutos, mexendo.","Misture o frango, ajuste o sal e deixe mais 2 minutos.","Rale a cenoura bem fina, crua, e guarde à parte.","Divida o arroz com frango nos potes, deixe esfriar com a tampa aberta e ponha a cenoura ralada por cima na hora de servir."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta, mexendo na metade. Leve a cenoura ralada em potinho e junte por cima depois de esquentar." },
  almoco51: { nome: "Polenta cremosa com ragu de carne de panela", categoria: 'almoco', itens: [{ a: 'polenta', q: [380, 410, 440, 300] }, { a: 'carnePanela', q: [90, 100, 100, 110] }, { a: 'molhoTomate', q: [80, 70, 100, 90] }, { a: 'parmesao', q: [5, 10, 10, 10] }], preparo: "Polenta firme com ragu de carne desfiada no molho de tomate e parmesão.", tempo: 60, passos: ["Cozinhe a carne de panela na pressão com água, sal e alho em pó por 40 minutos depois que chiar e desfie.","Junte a carne ao molho de tomate e deixe 10 minutos em fogo baixo, até virar um ragu.","Aqueça a polenta com 1/2 copo de água, mexendo, até ficar firme. Passe para os potes.","Cubra com o ragu e polvilhe o parmesão."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco52: { nome: "Bife com arroz e ovo cozido", categoria: 'almoco', itens: [{ a: 'patinho', q: [110, 130, 140, 140] }, { a: 'arroz', q: [240, 260, 270, 170] }, { a: 'ovo', q: [1, 1, 1, 1] }], preparo: "Bife grelhado com tempero de cebola, arroz e ovo cozido.", receita: 'arrozDaSemana', tempo: 35, passos: ["Tempere os bifes com sal, cebola em pó, alho em pó e pimenta-do-reino.","Sele em frigideira antiaderente bem quente, 2 minutos de cada lado. Corte em tiras.","Cozinhe o ovo por 9 minutos em água fervente, passe em água gelada e descasque.","Arroz da semana: veja o preparo de domingo. Divida o arroz nos potes, com o bife em tiras. Guarde o ovo descascado em um potinho separado."], etiquetas: ["salgado","marmita"], temperos: ["sal","cebola em pó","alho em pó","pimenta-do-reino","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos, tampa entreaberta, só o pote do arroz e do bife. O ovo vai no potinho à parte: coma frio ou corte ao meio antes de esquentar, porque ovo inteiro estoura no micro-ondas." },
  almoco53: { nome: "Sobrecoxa ao molho de tomate com macarrão", categoria: 'almoco', itens: [{ a: 'sobrecoxa', q: [100, 110, 110, 120] }, { a: 'molhoTomate', q: [70, 70, 90, 60] }, { a: 'macarrao', q: [230, 260, 280, 190] }], preparo: "Sobrecoxa assada sem pele, desossada no molho de tomate, com macarrão.", tempo: 55, passos: ["Tempere a sobrecoxa com sal, alho em pó e páprica. Tire a pele.","Forno a 200 graus por 35 minutos, virando na metade. Desosse e desfie em pedaços grandes.","Cozinhe o macarrão em água com sal, 2 minutos a menos que o tempo da embalagem. Escorra.","Aqueça o molho de tomate, junte a sobrecoxa e deixe 5 minutos.","Divida o macarrão nos potes e cubra com a sobrecoxa e o molho."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 3 minutos, tampa entreaberta, mexendo na metade." },
  almoco54: { nome: "Estrogonofe de carne com arroz e batata palha", categoria: 'almoco', itens: [{ a: 'patinho', q: [110, 120, 130, 130] }, { a: 'cremeLeite', q: [25, 25, 25, 20] }, { a: 'molhoTomate', q: [30, 40, 60, 40] }, { a: 'ketchup', q: [15, 20, 20, 10] }, { a: 'arroz', q: [210, 240, 250, 170] }, { a: 'batataPalha', q: [5, 5, 5, 5] }], preparo: "Tiras de carne em molho cremoso de tomate, arroz e batata palha à parte.", receita: 'arrozDaSemana', tempo: 35, passos: ["Corte o patinho em tiras finas e tempere com sal, alho em pó e páprica.","Doure a carne em frigideira bem quente por 4 minutos, em duas levas.","Junte o molho de tomate, o ketchup e 1/2 copo de água e cozinhe por 5 minutos.","Desligue o fogo e misture o creme de leite.","Arroz da semana: veja o preparo de domingo. Divida o arroz e o estrogonofe nos potes. Leve a batata palha em saquinho."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta; a batata palha vai por cima depois de esquentar, para ficar crocante." },
  almoco55: { nome: "Wrap de frango com catupiry gratinado ao molho", categoria: 'almoco', itens: [{ a: 'wrap', q: [2, 2, 2, 2] }, { a: 'frango', q: [120, 170, 180, 110] }, { a: 'molhoTomate', q: [70, 80, 70, 60] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'catupiry', q: [15, 10, 20, 15] }], preparo: "Wrap recheado de frango com catupiry, coberto de molho e queijo gratinado.", tempo: 40, passos: ["Cozinhe o frango em água com sal por 15 minutos e desfie. Misture com o catupiry e alho em pó.","Espalhe o recheio de frango em cada massa de wrap e enrole.","Em refratário, cubra os rolinhos com o molho de tomate e a mussarela.","Forno a 200 graus por 15 minutos, até gratinar.","Deixe esfriar antes de passar para os potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco56: { nome: "Lasanha bolonhesa de frango moído", categoria: 'almoco', itens: [{ a: 'macarrao', q: [200, 220, 230, 140] }, { a: 'frango', q: [60, 80, 90, 100] }, { a: 'molhoTomate', q: [70, 90, 110, 100] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'presunto', q: [2, 2, 2, 2] }, { a: 'parmesao', q: [5, 5, 5, 5] }], preparo: "Camadas de massa, bolonhesa de frango moído, presunto e queijo. Assa no domingo e corta em porções.", tempo: 70, passos: ["Pique o frango cru e bata no liquidificador em pulsos, até ficar moído. Doure em panela por 8 minutos com sal e alho em pó.","Junte o molho de tomate e 1 copo de água e deixe 5 minutos em fogo baixo: o molho precisa ficar ralo.","Pré-cozinhe a massa de lasanha em água com sal por 3 minutos e escorra.","Em travessa: molho de frango, massa de lasanha, presunto e mussarela. Repita e termine com molho, mussarela e parmesão.","Forno a 200 graus, 30 minutos coberta com papel-alumínio e 10 sem ele.","Espere esfriar por 30 minutos, corte em porções e passe para os potes. Congele as que passarem de 4 dias."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (6 se vier do congelador), tampa entreaberta." },
  almoco57: { nome: "Macarrão à carbonara caseira com bacon", categoria: 'almoco', itens: [{ a: 'macarrao', q: [270, 300, 320, 240] }, { a: 'bacon', q: [15, 20, 20, 15] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'parmesao', q: [10, 10, 10, 15] }], preparo: "Macarrão com creme de ovo e parmesão e bacon crocante de airfryer.", tempo: 30, passos: ["Bacon na airfryer a 200 graus por 8 minutos, até ficar crocante. Pique.","Cozinhe o macarrão em água com sal, 2 minutos a menos que o tempo da embalagem. Escorra, guardando 1/2 copo da água.","Bata o ovo com metade do parmesão e bastante pimenta-do-reino. Junte 3 colheres da água quente do cozimento, aos poucos, mexendo.","Leve o creme de ovo ao fogo baixo, mexendo sem parar por 2 a 3 minutos, até engrossar como um creme, sem ferver para não talhar.","Misture o macarrão ao creme, fora do fogo. Junte o bacon e o resto do parmesão.","Divida nos potes e deixe esfriar com a tampa aberta."], etiquetas: ["salgado","marmita"], temperos: ["sal","pimenta-do-reino","água"], levar: "Pote na geladeira do trabalho; coma em até 3 dias. Micro-ondas por 2 minutos com 1 colher de água por cima, em potência média, tampa entreaberta, mexendo na metade para o ovo não talhar.", airfryer: "Bacon na airfryer a 200 graus por 8 minutos." },
  almoco58: { nome: "Frango ao requeijão com batata palha e arroz", categoria: 'almoco', itens: [{ a: 'frango', q: [140, 140, 150, 160] }, { a: 'requeijao', q: [20, 25, 25, 20] }, { a: 'batataPalha', q: [5, 10, 10, 5] }, { a: 'arroz', q: [250, 270, 290, 210] }], preparo: "Frango em cubos em molho de requeijão, com batata palha à parte.", receita: 'arrozDaSemana', tempo: 35, passos: ["Corte o frango em cubos e tempere com sal, alho em pó e páprica.","Grelhe em frigideira antiaderente por 8 minutos, mexendo.","Baixe o fogo, junte o requeijão e 2 colheres de água e mexa por 2 minutos, até formar um molho cremoso.","Arroz da semana: veja o preparo de domingo. Divida o arroz e o frango com requeijão nos potes.","Leve a batata palha em saquinho à parte."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","páprica","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta; a batata palha vai por cima depois de esquentar." },
  almoco59: { nome: "Polenta de forno com frango e queijo", categoria: 'almoco', itens: [{ a: 'polenta', q: [340, 380, 400, 280] }, { a: 'frango', q: [70, 90, 100, 100] }, { a: 'molhoTomate', q: [70, 60, 70, 50] }, { a: 'mussarela', q: [2, 2, 2, 2] }], preparo: "Polenta em camadas com frango desfiado, molho de tomate e queijo gratinado.", tempo: 45, passos: ["Cozinhe o frango em água com sal por 15 minutos e desfie.","Misture o frango ao molho de tomate com alho em pó.","Em refratário, faça uma camada de polenta, uma de frango com molho e termine com polenta.","Cubra com a mussarela. Forno a 200 graus por 15 minutos, até gratinar.","Deixe esfriar e divida nos potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","água"], levar: "Pote na geladeira do trabalho, ou congelado. Micro-ondas por 3 minutos (5 se vier do congelador), tampa entreaberta." },
  almoco60: { nome: "Macarrão ao alho e azeite com tiras de bife", categoria: 'almoco', itens: [{ a: 'macarrao', q: [240, 270, 300, 200] }, { a: 'patinho', q: [80, 90, 90, 100] }, { a: 'azeite', q: [5, 5, 5, 5] }, { a: 'parmesao', q: [5, 5, 5, 5] }], preparo: "Macarrão passado no azeite com alho em pó, tiras de bife e parmesão.", tempo: 30, passos: ["Tempere os bifes com sal e pimenta-do-reino e sele em frigideira bem quente, 2 minutos de cada lado. Corte em tiras.","Cozinhe o macarrão em água com sal, 2 minutos a menos que o tempo da embalagem. Escorra.","Aqueça o azeite com alho em pó por 1 minuto e passe o macarrão nele, mexendo.","Junte as tiras de bife e o parmesão. Divida nos potes."], etiquetas: ["salgado","marmita"], temperos: ["sal","alho em pó","pimenta-do-reino","água"], levar: "Pote na geladeira do trabalho. Micro-ondas por 2 minutos e meio, tampa entreaberta, mexendo na metade." },
  jantar31: { nome: "Pizza caseira de mussarela", categoria: 'jantar', itens: [{ a: 'massaPizza', q: [1, 1, 1, 1] }, { a: 'molhoTomate', q: [70, 25, 130, 25] }, { a: 'mussarela', q: [3, 4, 4, 3] }], preparo: "Massa de pizza pronta, molho e mussarela no forno ou na airfryer.", tempo: 18, passos: ["Ligue o forno a 220 graus por 10 minutos.","Passe o molho de tomate na massa pronta e tempere com orégano.","Cubra com a mussarela, de ponta a ponta.","Asse por 10 a 12 minutos, até a borda dourar e o queijo borbulhar."], etiquetas: ["salgado","besteira","vegetariano"], temperos: ["orégano"], airfryer: "Na airfryer a 180 graus por 8 minutos, se o disco couber na cesta." },
  jantar32: { nome: "Pizza de frango com catupiry", categoria: 'jantar', itens: [{ a: 'massaPizza', q: [1, 1, 1, 1] }, { a: 'molhoTomate', q: [25, 25, 50, 20] }, { a: 'frango', q: [60, 50, 70, 50] }, { a: 'catupiry', q: [20, 20, 20, 20] }, { a: 'mussarela', q: [1, 2, 2, 1] }], preparo: "Frango da semana desfiado, catupiry e mussarela sobre massa pronta.", receita: 'frangoDaSemana', tempo: 20, passos: ["Ligue o forno a 220 graus por 10 minutos.","Passe o molho de tomate na massa pronta.","Espalhe o frango da semana desfiado e a mussarela.","Asse por 10 minutos, tire do forno e ponha o catupiry em colheradas por cima.","Volte ao forno por 2 minutos e tempere com orégano."], etiquetas: ["salgado","besteira"], temperos: ["orégano"], airfryer: "Na airfryer a 180 graus por 8 minutos, se o disco couber na cesta." },
  jantar33: { nome: "Hambúrguer com alface, tomate e batata na airfryer", categoria: 'jantar', itens: [{ a: 'paoHamburguer', q: [1, 1, 1, 1] }, { a: 'moida', q: [60, 60, 70, 60] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'alface', q: [2, 2, 2, 2] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'ketchup', q: [15, 15, 5, 5] }, { a: 'batataFrita', q: [60, 80, 90, 60] }], preparo: "Disco de carne na frigideira, batata frita na airfryer.", tempo: 22, passos: ["Ponha a batata frita congelada na airfryer a 200 graus por 15 minutos, sacudindo na metade.","Modele a carne moída crua com sal e alho em pó em um disco do tamanho do pão.","Grelhe na frigideira bem quente, 4 minutos de cada lado, com a mussarela por cima no final.","Aqueça o pão por 1 minuto e monte com ketchup, alface, tomate e o disco."], etiquetas: ["salgado","besteira"], temperos: ["sal","alho em pó"], airfryer: "Batata frita na airfryer a 200 graus por 15 minutos, sacudindo na metade." },
  jantar34: { nome: "Cachorro-quente com batata palha", categoria: 'jantar', itens: [{ a: 'paoHotDog', q: [1, 1, 1, 1] }, { a: 'salsicha', q: [2, 2, 2, 2] }, { a: 'molhoTomate', q: [50, 60, 60, 60] }, { a: 'ketchup', q: [20, 15, 25, 20] }, { a: 'batataPalha', q: [15, 25, 30, 10] }], preparo: "Salsicha no molho, pão quente e batata palha por cima.", tempo: 10, passos: ["Ferva a salsicha no molho de tomate com orégano por 3 minutos.","Aqueça o pão de cachorro-quente por 1 minuto na frigideira.","Recheie com as salsichas e o molho.","Finalize com ketchup e a batata palha."], etiquetas: ["salgado","besteira"], temperos: ["orégano"] },
  jantar35: { nome: "Nuggets caseiros de frango com batata frita", categoria: 'jantar', itens: [{ a: 'frango', q: [80, 90, 90, 100] }, { a: 'cenoura', q: [15, 15, 20, 15] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'farinhaRosca', q: [20, 30, 25, 20] }, { a: 'batataFrita', q: [90, 90, 110, 70] }], preparo: "Nuggets de frango com cenoura escondida, na airfryer, com batata frita.", receita: 'frangoDaSemana', tempo: 25, passos: ["Processe o frango da semana, já cozido, até ficar bem desfiado. Misture com a cenoura ralada, sal, alho em pó e 1 colher de sopa da farinha de rosca, para dar liga.","Com as mãos molhadas, modele nuggets achatados. Passe no ovo batido e depois no resto da farinha de rosca.","Ponha a batata frita congelada na airfryer a 200 graus por 15 minutos, sacudindo na metade.","Depois de 5 minutos, junte os nuggets na cesta e deixe os 10 minutos finais, virando na metade, até dourar."], etiquetas: ["salgado","besteira"], temperos: ["sal","alho em pó"], airfryer: "Batata frita a 200 graus por 15 minutos; os nuggets entram aos 5 minutos e terminam juntos, virando na metade." },
  jantar36: { nome: "Bife com batata frita na airfryer", categoria: 'jantar', itens: [{ a: 'patinho', q: [80, 80, 90, 100] }, { a: 'batataFrita', q: [120, 140, 150, 100] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'ketchup', q: [15, 15, 5, 5] }], preparo: "Bife na frigideira, batata crocante na airfryer.", tempo: 20, passos: ["Ponha a batata frita congelada na airfryer a 200 graus por 15 minutos, sacudindo na metade.","Tempere o bife com sal e alho em pó.","Aqueça a frigideira bem quente e grelhe o bife 3 minutos de cada lado.","Sirva com a batata, o tomate em rodelas e o ketchup."], etiquetas: ["salgado","besteira"], temperos: ["sal","alho em pó"], airfryer: "Batata frita na airfryer a 200 graus por 15 minutos, sacudindo na metade." },
  jantar37: { nome: "Crepe de frango com queijo", categoria: 'jantar', itens: [{ a: 'farinhaTrigo', q: [40, 50, 50, 30] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'leite', q: [50, 50, 100, 50] }, { a: 'frango', q: [70, 80, 80, 80] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'requeijao', q: [10, 10, 15, 10] }], preparo: "Massa batida no liquidificador, recheio de frango da semana e queijo.", receita: 'frangoDaSemana', tempo: 20, passos: ["Bata no liquidificador a farinha, o ovo, o leite e uma pitada de sal até ficar liso.","Aqueça uma frigideira antiaderente e despeje metade da massa, girando para espalhar fino.","Vire quando soltar do fundo, depois de cerca de 1 minuto, e doure o outro lado.","Misture o frango da semana desfiado com o requeijão, recheie e ponha a mussarela.","Dobre e tampe a frigideira por 1 minuto para o queijo derreter."], etiquetas: ["salgado"], temperos: ["sal"] },
  jantar38: { nome: "Pão sírio recheado com carne moída", categoria: 'jantar', itens: [{ a: 'paoSirio', q: [1, 1, 1, 1] }, { a: 'moida', q: [100, 130, 140, 90] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'tomate', q: [2, 2, 2, 2] }, { a: 'alface', q: [1, 1, 1, 1] }], preparo: "Carne moída da semana com queijo dentro do pão sírio.", receita: 'carneMoida', tempo: 8, passos: ["Esquente a carne moída da semana no micro-ondas por 2 minutos.","Abra o pão sírio ao meio, como um bolso, e aqueça na frigideira seca por 30 segundos.","Recheie com a carne, a mussarela, o tomate e a alface.","Volte à frigideira por 1 minuto de cada lado para derreter o queijo."], etiquetas: ["salgado"] },
  jantar39: { nome: "Salada caesar com frango", categoria: 'jantar', itens: [{ a: 'alface', q: [8, 8, 8, 8] }, { a: 'frango', q: [80, 80, 90, 90] }, { a: 'parmesao', q: [10, 10, 15, 10] }, { a: 'crouton', q: [40, 50, 50, 30] }, { a: 'maionese', q: [10, 10, 10, 10] }, { a: 'paoFrances', q: [1, 1, 1, 1] }], preparo: "Alface, frango da semana, croutons e parmesão, com pão para fechar a conta.", receita: 'frangoDaSemana', tempo: 10, passos: ["Esquente o frango da semana por 1 minuto e corte em tiras.","Misture a maionese com metade do parmesão, pimenta-do-reino e 1 colher de água para virar o molho.","Rasgue a alface em um prato fundo e junte o frango e o molho.","Finalize com os croutons e o resto do parmesão.","Aqueça o pão francês e sirva ao lado."], etiquetas: ["salgado"], temperos: ["pimenta-do-reino","água"] },
  jantar40: { nome: "Omelete com presunto e tomate e arroz", categoria: 'jantar', itens: [{ a: 'ovo', q: [3, 3, 4, 4] }, { a: 'presunto', q: [2, 2, 2, 2] }, { a: 'tomate', q: [3, 3, 3, 3] }, { a: 'arroz', q: [210, 250, 220, 130] }], preparo: "Omelete recheado com presunto e tomate, arroz da marmita ao lado.", tempo: 10, passos: ["Bata os ovos com sal e orégano.","Aqueça uma frigideira antiaderente em fogo médio e despeje os ovos.","Quando firmar embaixo, espalhe o presunto e o tomate em rodelas em uma metade.","Dobre o omelete e tampe por 1 minuto.","Esquente o arroz no micro-ondas por 2 minutos e sirva junto."], etiquetas: ["salgado"], temperos: ["sal","orégano"] },
  jantar41: { nome: "Pizza caseira de calabresa", categoria: 'jantar', itens: [{ a: 'massaPizza', q: [1, 1, 1, 1] }, { a: 'molhoTomate', q: [40, 20, 30, 20] }, { a: 'mussarela', q: [2, 3, 3, 2] }, { a: 'calabresa', q: [25, 25, 35, 25] }], preparo: "Massa pronta com molho, mussarela e rodelas de calabresa.", tempo: 20, passos: ["Ligue o forno a 220 graus por 10 minutos.","Passe o molho de tomate na massa de pizza e tempere com orégano.","Cubra com a mussarela e espalhe a calabresa em rodelas finas.","Asse por 10 a 12 minutos, até a borda dourar e a calabresa soltar a gordura."], etiquetas: ["salgado","besteira"], temperos: ["orégano"], airfryer: "Na airfryer a 180 graus por 8 minutos, se a massa de pizza couber na cesta." },
  jantar42: { nome: "X-bacon caseiro com batata na airfryer", categoria: 'jantar', itens: [{ a: 'paoHamburguer', q: [1, 1, 1, 1] }, { a: 'moida', q: [50, 60, 50, 50] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'bacon', q: [15, 15, 15, 15] }, { a: 'batataFrita', q: [50, 60, 80, 50] }], preparo: "Hambúrguer com bacon crocante e batata frita, tudo na airfryer e na frigideira.", tempo: 22, passos: ["Ponha a batata frita congelada na airfryer a 200 graus por 15 minutos, sacudindo na metade.","Junte o bacon na cesta nos últimos 6 minutos, até ficar crocante.","Modele a carne moída crua com sal e alho em pó em um disco do tamanho do pão e grelhe 4 minutos de cada lado, com a mussarela por cima no final.","Aqueça o pão por 1 minuto e monte com o disco e o bacon."], etiquetas: ["salgado","besteira"], temperos: ["sal","alho em pó"], airfryer: "Batata frita a 200 graus por 15 minutos, sacudindo na metade; o bacon entra nos últimos 6 minutos." },
  jantar43: { nome: "Cachorro-quente gratinado de forno", categoria: 'jantar', itens: [{ a: 'paoHotDog', q: [1, 2, 2, 1] }, { a: 'salsicha', q: [2, 1, 2, 2] }, { a: 'molhoTomate', q: [15, 80, 20, 80] }, { a: 'mussarela', q: [2, 2, 1, 1] }], preparo: "Pão com salsicha, molho e mussarela gratinada no forno.", tempo: 15, passos: ["Ligue o forno a 200 graus.","Abra o pão de cachorro-quente ao meio e passe o molho de tomate com orégano.","Ponha as salsichas e cubra com a mussarela.","Asse por 8 minutos, até o queijo borbulhar e o pão dourar."], etiquetas: ["salgado","besteira"], temperos: ["orégano"], airfryer: "Na airfryer a 180 graus por 5 minutos, até o queijo derreter." },
  jantar44: { nome: "Hambúrguer de frango empanado", categoria: 'jantar', itens: [{ a: 'paoHamburguer', q: [1, 1, 1, 1] }, { a: 'milanesaFrango', q: [120, 140, 160, 120] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'maionese', q: [15, 15, 15, 5] }, { a: 'alface', q: [2, 2, 2, 2] }, { a: 'tomate', q: [2, 2, 2, 2] }], preparo: "Filé de frango empanado crocante na airfryer, no pão com maionese.", tempo: 22, passos: ["Tempere a milanesa de frango com sal e páprica.","Leve à airfryer a 200 graus por 12 minutos, virando na metade.","Ponha a mussarela por cima nos últimos 2 minutos.","Aqueça o pão por 1 minuto e passe a maionese.","Monte com a alface, o tomate e a milanesa."], etiquetas: ["salgado","besteira"], temperos: ["sal","páprica"], airfryer: "Milanesa na airfryer a 200 graus por 12 minutos, virando na metade, sem óleo." },
  jantar45: { nome: "Batata recheada com bacon e queijo", categoria: 'jantar', itens: [{ a: 'batata', q: [390, 430, 460, 340] }, { a: 'bacon', q: [25, 30, 25, 15] }, { a: 'mussarela', q: [2, 2, 3, 3] }, { a: 'requeijao', q: [20, 20, 15, 15] }], preparo: "Batata no micro-ondas, recheio de bacon crocante, requeijão e mussarela.", tempo: 22, passos: ["Lave a batata, fure com um garfo e leve ao micro-ondas por 8 minutos, virando na metade.","Leve o bacon à airfryer a 200 graus por 6 minutos, até ficar crocante, e pique.","Abra a batata ao meio, misture a polpa com o requeijão e tempere com sal.","Junte o bacon, cubra com a mussarela e volte ao micro-ondas por 1 minuto."], etiquetas: ["salgado","besteira"], temperos: ["sal"], airfryer: "Bacon na airfryer a 200 graus por 6 minutos, até ficar crocante." },
  jantar46: { nome: "Crepioca de queijo e presunto", categoria: 'jantar', itens: [{ a: 'ovo', q: [3, 3, 3, 3] }, { a: 'tapioca', q: [80, 100, 90, 70] }, { a: 'mussarela', q: [1, 1, 2, 1] }, { a: 'presunto', q: [3, 3, 3, 3] }], preparo: "Ovo e goma de tapioca na frigideira, recheio de presunto e queijo.", tempo: 8, passos: ["Bata os ovos com a tapioca hidratada e uma pitada de sal.","Despeje em frigideira antiaderente em fogo médio e espalhe fino.","Quando firmar, vire, ponha o presunto e a mussarela em uma metade.","Dobre e tampe por 1 minuto para o queijo derreter."], etiquetas: ["salgado"], temperos: ["sal"] },
  jantar47: { nome: "Tapioca de ovo mexido com queijo coalho", categoria: 'jantar', itens: [{ a: 'tapioca', q: [90, 110, 120, 80] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'queijoCoalho', q: [1, 1, 1, 1] }], preparo: "Tapioca com ovo mexido e queijo coalho dourado.", tempo: 10, passos: ["Espalhe a tapioca hidratada em frigideira quente, em camada fina, até soltar do fundo. Tire para um prato.","Corte o queijo coalho em fatias e doure na mesma frigideira 1 minuto de cada lado.","Mexa os ovos com sal na frigideira até firmar.","Recheie a tapioca com o ovo e o queijo coalho saindo da frigideira, dobre e sirva quente."], etiquetas: ["salgado","vegetariano"], temperos: ["sal"] },
  jantar48: { nome: "Wrap de frango com requeijão e alface", categoria: 'jantar', itens: [{ a: 'wrap', q: [2, 2, 2, 2] }, { a: 'frango', q: [150, 180, 200, 130] }, { a: 'requeijao', q: [15, 15, 20, 20] }, { a: 'alface', q: [3, 3, 3, 3] }, { a: 'tomate', q: [2, 2, 2, 2] }], preparo: "Frango da semana desfiado com requeijão, alface e tomate no wrap.", receita: 'frangoDaSemana', tempo: 8, passos: ["Esquente o frango da semana no micro-ondas por 1 minuto e desfie.","Misture o frango com o requeijão e tempere com pimenta-do-reino.","Espalhe no centro de cada wrap e junte a alface e o tomate.","Enrole e doure na frigideira seca 1 minuto de cada lado, com a emenda para baixo primeiro."], etiquetas: ["salgado"], temperos: ["pimenta-do-reino"] },
  jantar49: { nome: "Pão sírio com omelete e queijo minas", categoria: 'jantar', itens: [{ a: 'paoSirio', q: [1, 1, 1, 1] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'minas', q: [80, 100, 110, 70] }, { a: 'tomate', q: [2, 2, 2, 2] }], preparo: "Omelete dobrado dentro do pão sírio com queijo minas e tomate.", tempo: 10, passos: ["Bata os ovos com sal e orégano.","Despeje em frigideira antiaderente e, quando firmar, ponha o queijo minas em pedaços e dobre.","Abra o pão sírio ao meio e aqueça na frigideira seca por 30 segundos.","Recheie com o omelete e o tomate em rodelas."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","orégano"] },
  jantar50: { nome: "Macarrão ao sugo com carne moída e parmesão", categoria: 'jantar', itens: [{ a: 'macarrao', q: [200, 220, 250, 160] }, { a: 'moida', q: [70, 80, 80, 80] }, { a: 'molhoTomate', q: [90, 90, 70, 80] }, { a: 'parmesao', q: [5, 5, 5, 10] }], preparo: "Macarrão com carne moída da semana no molho de tomate e parmesão por cima.", receita: 'carneMoida', tempo: 14, passos: ["Cozinhe o macarrão em água com sal conforme a embalagem e escorra.","Numa panela, esquente o molho de tomate com orégano e junte a carne moída da semana por 3 minutos.","Misture o macarrão ao molho e mexa por 1 minuto.","Finalize com o parmesão."], etiquetas: ["salgado"], temperos: ["sal","orégano","água"] },
  jantar51: { nome: "Arroz de frigideira com ovo e carne moída", categoria: 'jantar', itens: [{ a: 'arroz', q: [200, 240, 250, 160] }, { a: 'moida', q: [90, 90, 100, 100] }, { a: 'ovo', q: [1, 1, 1, 1] }], preparo: "Arroz e carne moída da semana salteados, com ovo mexido junto.", receita: 'carneMoida', tempo: 8, passos: ["Aqueça uma frigideira e junte o arroz e a carne moída da semana, mexendo por 3 minutos.","Abra um espaço no meio e quebre o ovo, mexendo até firmar.","Misture tudo, tempere com sal, cominho e pimenta-do-reino e sirva."], etiquetas: ["salgado"], temperos: ["sal","cominho","pimenta-do-reino"] },
  jantar52: { nome: "Sanduíche de forno com frango e mussarela", categoria: 'jantar', itens: [{ a: 'paoFrances', q: [2, 2, 2, 2] }, { a: 'frango', q: [50, 80, 110, 50] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'molhoTomate', q: [20, 30, 10, 10] }], preparo: "Pão aberto com frango da semana, molho e mussarela gratinada.", receita: 'frangoDaSemana', tempo: 12, passos: ["Ligue o forno a 200 graus.","Abra os pães ao meio e passe o molho de tomate com orégano.","Espalhe o frango da semana desfiado e cubra com a mussarela.","Asse por 6 a 8 minutos, até o queijo dourar."], etiquetas: ["salgado"], temperos: ["orégano"] },
  jantar53: { nome: "Purê gratinado com frango desfiado", categoria: 'jantar', itens: [{ a: 'pure', q: [290, 300, 330, 230] }, { a: 'frango', q: [90, 110, 110, 110] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'requeijao', q: [10, 10, 15, 10] }], preparo: "Purê com frango da semana e queijo gratinado na airfryer.", receita: 'frangoDaSemana', tempo: 10, passos: ["Esquente o purê no micro-ondas por 3 minutos, mexendo na metade.","Esquente o frango da semana por 1 minuto, desfie e misture com o requeijão.","Passe o purê para um refratário pequeno, cubra com o frango e a mussarela.","Gratine na airfryer a 200 graus por 5 minutos, até o queijo dourar, e tempere com pimenta-do-reino."], etiquetas: ["salgado"], temperos: ["pimenta-do-reino"], airfryer: "Gratine na airfryer a 200 graus por 5 minutos." },
  jantar54: { nome: "Cuscuz com ovo e queijo coalho", categoria: 'jantar', itens: [{ a: 'cuscuz', q: [180, 230, 260, 160] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'queijoCoalho', q: [1, 1, 1, 1] }], preparo: "Cuscuz de micro-ondas com ovos mexidos e queijo coalho dourado.", tempo: 10, passos: ["Hidrate o cuscuz em um pote com água e sal conforme a embalagem.","Leve ao micro-ondas por 3 minutos, tampado, e solte com um garfo.","Doure o queijo coalho na frigideira 1 minuto de cada lado.","Mexa os ovos com sal na mesma frigideira até firmar e sirva sobre o cuscuz com o queijo."], etiquetas: ["salgado","vegetariano"], temperos: ["sal","água"] },
  jantar55: { nome: "Cuscuz cremoso com frango e requeijão", categoria: 'jantar', itens: [{ a: 'cuscuz', q: [300, 340, 350, 250] }, { a: 'frango', q: [90, 90, 100, 110] }, { a: 'requeijao', q: [15, 15, 20, 15] }], preparo: "Cuscuz com frango da semana desfiado e requeijão derretido.", receita: 'frangoDaSemana', tempo: 8, passos: ["Hidrate o cuscuz em um pote com água e sal conforme a embalagem.","Leve ao micro-ondas por 3 minutos, tampado, e solte com um garfo.","Esquente o frango da semana por 1 minuto e desfie.","Misture o frango e o requeijão ao cuscuz quente e tempere com pimenta-do-reino."], etiquetas: ["salgado"], temperos: ["sal","água","pimenta-do-reino"] },
  jantar56: { nome: "Sobrecoxa com batata assada na airfryer", categoria: 'jantar', itens: [{ a: 'sobrecoxa', q: [140, 150, 160, 150] }, { a: 'batata', q: [370, 420, 460, 280] }], preparo: "Sobrecoxa sem osso e batata em cubos assadas juntas na airfryer.", tempo: 25, passos: ["Corte a batata em cubos pequenos e cozinhe no micro-ondas por 5 minutos, com tampa.","Tempere a sobrecoxa com sal, alho em pó e páprica.","Leve a sobrecoxa à airfryer a 180 graus por 18 minutos, virando na metade.","Junte a batata temperada com sal nos últimos 8 minutos, sacudindo a cesta uma vez."], etiquetas: ["salgado"], temperos: ["sal","alho em pó","páprica"], airfryer: "Sobrecoxa a 180 graus por 18 minutos; a batata entra nos últimos 8 minutos." },
  jantar57: { nome: "Crepe de carne moída com queijo", categoria: 'jantar', itens: [{ a: 'farinhaTrigo', q: [30, 50, 50, 30] }, { a: 'ovo', q: [1, 1, 1, 1] }, { a: 'leite', q: [100, 100, 100, 50] }, { a: 'moida', q: [70, 60, 80, 70] }, { a: 'mussarela', q: [2, 2, 2, 2] }], preparo: "Massa de crepe batida, recheio de carne moída da semana e queijo.", receita: 'carneMoida', tempo: 18, passos: ["Bata no liquidificador a farinha, o ovo, o leite e uma pitada de sal até ficar liso.","Aqueça uma frigideira antiaderente e espalhe metade da massa bem fina; vire depois de 1 minuto.","Esquente a carne moída da semana por 2 minutos e recheie o crepe.","Ponha a mussarela, dobre e tampe a frigideira por 1 minuto."], etiquetas: ["salgado"], temperos: ["sal"] },
  jantar58: { nome: "Polenta com carne moída e queijo", categoria: 'jantar', itens: [{ a: 'polenta', q: [260, 290, 310, 200] }, { a: 'moida', q: [50, 60, 70, 70] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'molhoTomate', q: [35, 30, 25, 25] }], preparo: "Polenta cremosa com carne moída da semana, molho de tomate e queijo.", receita: 'carneMoida', tempo: 12, passos: ["Ferva água com sal e despeje a polenta aos poucos, mexendo sem parar por 5 minutos.","Esquente a carne moída da semana com o molho de tomate por 3 minutos.","Ponha a polenta no prato, cubra com a carne e o molho.","Finalize com a mussarela e tampe 1 minuto para derreter."], etiquetas: ["salgado"], temperos: ["sal","água"] },
  jantar59: { nome: "Mexidão de linguiça com ovo e arroz", categoria: 'jantar', itens: [{ a: 'linguica', q: [60, 70, 80, 80] }, { a: 'arroz', q: [180, 200, 210, 120] }, { a: 'ovo', q: [2, 2, 2, 2] }], preparo: "Arroz, linguiça em rodelas e ovos mexidos tudo na mesma frigideira.", tempo: 15, passos: ["Corte a linguiça em rodelas e doure na frigideira por 5 minutos, até soltar a gordura.","Junte o arroz e mexa por 2 minutos.","Quebre os ovos por cima e mexa até firmar.","Tempere com sal, cominho e pimenta-do-reino."], etiquetas: ["salgado"], temperos: ["sal","cominho","pimenta-do-reino"], airfryer: "Linguiça em rodelas na airfryer a 180 graus por 8 minutos, sacudindo na metade." },
  jantar60: { nome: "Mexidão de macarrão com frango e queijo", categoria: 'jantar', itens: [{ a: 'macarrao', q: [150, 180, 200, 120] }, { a: 'frango', q: [50, 50, 60, 60] }, { a: 'mussarela', q: [2, 2, 2, 2] }, { a: 'ovo', q: [1, 1, 1, 1] }], preparo: "Macarrão com frango da semana, ovo mexido e queijo derretido.", receita: 'frangoDaSemana', tempo: 15, passos: ["Cozinhe o macarrão em água com sal conforme a embalagem e escorra.","Aqueça a frigideira e junte o frango da semana desfiado por 2 minutos.","Quebre o ovo e mexa até firmar, depois junte o macarrão.","Cubra com a mussarela picada, tampe 1 minuto e tempere com pimenta-do-reino."], etiquetas: ["salgado"], temperos: ["sal","pimenta-do-reino","água"] },
  jantar61: { nome: "Tapioca de peito de peru com queijo minas", categoria: 'jantar', itens: [{ a: 'tapioca', q: [130, 140, 160, 100] }, { a: 'peitoPeru', q: [4, 4, 4, 4] }, { a: 'minas', q: [50, 60, 60, 70] }, { a: 'tomate', q: [2, 2, 2, 2] }], preparo: "Tapioca recheada com peito de peru, queijo minas e tomate.", tempo: 6, passos: ["Aqueça uma frigideira antiaderente e espalhe a tapioca hidratada em camada fina.","Quando soltar do fundo, vire e ponha o peito de peru e o queijo minas em uma metade.","Junte o tomate em rodelas, dobre e tampe 1 minuto."], etiquetas: ["salgado"] },
  jantar62: { nome: "Nhoque ao sugo com carne moída", categoria: 'jantar', itens: [{ a: 'nhoque', q: [200, 220, 240, 170] }, { a: 'moida', q: [50, 60, 60, 70] }, { a: 'molhoTomate', q: [80, 60, 70, 40] }, { a: 'parmesao', q: [5, 5, 5, 5] }], preparo: "Nhoque pronto no molho de tomate com carne moída da semana e parmesão.", receita: 'carneMoida', tempo: 10, passos: ["Esquente o molho de tomate com orégano e a carne moída da semana por 3 minutos.","Ferva água com sal e cozinhe o nhoque por 2 minutos, até subir.","Escorra e misture o nhoque ao molho.","Finalize com o parmesão."], etiquetas: ["salgado"], temperos: ["sal","orégano","água"] },
  jantar63: { nome: "Pizza de pão sírio com presunto e mussarela", categoria: 'jantar', itens: [{ a: 'paoSirio', q: [1, 1, 1, 1] }, { a: 'molhoTomate', q: [15, 50, 150, 25] }, { a: 'mussarela', q: [5, 5, 5, 4] }, { a: 'presunto', q: [4, 4, 4, 4] }], preparo: "Pão sírio como massa de pizza, com molho, presunto e queijo.", tempo: 10, passos: ["Passe o molho de tomate no pão sírio e tempere com orégano.","Cubra com a mussarela e o presunto picado.","Leve à frigideira tampada em fogo baixo por 5 minutos, até o queijo derreter e o fundo dourar."], etiquetas: ["salgado"], temperos: ["orégano"] },
  jantar64: { nome: "Omelete recheado de frango com arroz", categoria: 'jantar', itens: [{ a: 'ovo', q: [3, 3, 3, 3] }, { a: 'frango', q: [40, 50, 70, 60] }, { a: 'mussarela', q: [1, 1, 1, 1] }, { a: 'arroz', q: [130, 160, 170, 90] }], preparo: "Omelete com frango da semana desfiado e queijo, arroz ao lado.", receita: 'frangoDaSemana', tempo: 10, passos: ["Esquente o frango da semana por 1 minuto e desfie.","Bata os ovos com sal e despeje em frigideira antiaderente em fogo médio.","Quando firmar, ponha o frango e a mussarela em uma metade e dobre.","Esquente o arroz no micro-ondas por 2 minutos e sirva junto."], etiquetas: ["salgado"], temperos: ["sal"] },
  jantar65: { nome: "Wrap de ovo mexido com presunto e queijo", categoria: 'jantar', itens: [{ a: 'wrap', q: [1, 2, 2, 1] }, { a: 'ovo', q: [2, 2, 2, 2] }, { a: 'presunto', q: [3, 3, 3, 3] }, { a: 'mussarela', q: [3, 2, 3, 3] }, { a: 'tomate', q: [2, 2, 2, 2] }], preparo: "Ovos mexidos com presunto, queijo e tomate enrolados no wrap.", tempo: 10, passos: ["Mexa os ovos com sal na frigideira até firmar.","Ponha o ovo, o presunto, a mussarela e o tomate em rodelas no centro de cada wrap.","Enrole e doure na frigideira seca 1 minuto de cada lado, com a emenda para baixo primeiro."], etiquetas: ["salgado"], temperos: ["sal"] },
  ceia31: { nome: "Açaí na tigela com banana e granola", categoria: 'ceia', itens: [{ a: 'acai', q: [80, 80, 110, 80] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'granola', q: [25, 30, 30, 20] }, { a: 'leite', q: [50, 50, 50, 50] }], preparo: "Bata o açaí com o leite e cubra com banana e granola.", tempo: 8, passos: ["Deixe a polpa de açaí 5 minutos fora do congelador, para amolecer um pouco.","Bata no liquidificador o açaí com o leite, usando o socador, até ficar grosso e liso.","Passe para uma tigela e fatie a banana por cima.","Finalize com a granola, na hora de comer, para ela não amolecer.","Coma de colher, devagar. Use açaí puro, sem xarope de guaraná."], etiquetas: ["doce","vegetariano"] },
  ceia32: { nome: "Açaí batido com leite e banana", categoria: 'ceia', itens: [{ a: 'acai', q: [60, 80, 120, 70] }, { a: 'leite', q: [250, 250, 250, 200] }, { a: 'banana', q: [1, 1, 1, 1] }], preparo: "Bata tudo até ficar gelado e cremoso, para beber.", tempo: 5, passos: ["Coloque o leite no liquidificador primeiro e depois o açaí, ainda congelado, em pedaços.","Junte a banana em pedaços.","Bata por 1 minuto, até ficar liso e gelado.","Beba em copo alto, devagar. Use açaí puro, sem xarope de guaraná."], etiquetas: ["doce","vegetariano"] },
  ceia33: { nome: "Mingau de aveia com canela", categoria: 'ceia', itens: [{ a: 'leite', q: [200, 200, 250, 200] }, { a: 'aveia', q: [25, 30, 30, 25] }, { a: 'mel', q: [15, 15, 10, 5] }], preparo: "Cozinhe a aveia no leite, adoce com mel e polvilhe canela.", tempo: 8, passos: ["Misture o leite e a aveia em uma panela pequena.","Leve ao fogo baixo e mexa por 4 a 5 minutos, até ficar cremoso.","Desligue o fogo, junte o mel e uma pitada de canela.","Deixe amornar 2 minutos e tome de colher, em uma caneca."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia34: { nome: "Iogurte com morango e mel", categoria: 'ceia', itens: [{ a: 'iogurte', q: [320, 320, 350, 300] }, { a: 'morango', q: [170, 180, 200, 140] }, { a: 'mel', q: [15, 20, 20, 15] }], preparo: "Iogurte na tigela com morango picado e fio de mel.", tempo: 4, passos: ["Lave os morangos, tire as folhinhas e corte em pedaços pequenos.","Coloque o iogurte em uma tigela.","Espalhe o morango por cima.","Finalize com o mel em fio e coma de colher."], etiquetas: ["doce","vegetariano"] },
  ceia35: { nome: "Vitamina de abacate com leite", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 300, 300, 250] }, { a: 'abacate', q: [35, 50, 40, 40] }, { a: 'leitePo', q: [15, 10, 15, 10] }], preparo: "Bata o abacate com o leite e o leite em pó até ficar cremosa.", tempo: 5, passos: ["Tire a casca e o caroço do abacate e pegue a polpa madura.","Coloque no liquidificador com o leite e o leite em pó.","Bata por 40 segundos, até ficar bem cremosa.","Sirva gelada, com 2 pedras de gelo, e beba devagar."], etiquetas: ["doce","vegetariano"], temperos: ["gelo"] },
  ceia36: { nome: "Leite quente com mel e canela com biscoito", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 250, 250] }, { a: 'mel', q: [5, 15, 15, 5] }, { a: 'creamCracker', q: [20, 20, 25, 15] }], preparo: "Leite morno com mel e canela, e biscoito cream cracker para acompanhar.", tempo: 5, passos: ["Aqueça o leite em uma panela pequena em fogo baixo, por 3 minutos, ou no micro-ondas por 1 minuto e 30 segundos.","Não deixe ferver, só ficar bem quente.","Passe para uma caneca, junte o mel e mexa até dissolver.","Polvilhe uma pitada de canela e coma com o biscoito cream cracker."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia37: { nome: "Mingau de Mucilon com banana amassada", categoria: 'ceia', itens: [{ a: 'leite', q: [200, 200, 250, 200] }, { a: 'mucilon', q: [15, 20, 20, 10] }, { a: 'banana', q: [1, 1, 1, 1] }], preparo: "Mingau morno de Mucilon com banana amassada.", tempo: 6, passos: ["Misture o Mucilon com um pouco do leite frio em uma panela, até não ter grumos.","Junte o resto do leite e leve ao fogo baixo, mexendo por 3 a 4 minutos, até engrossar.","Amasse a banana com um garfo e misture no mingau.","Passe para uma tigela, polvilhe canela e coma morno, de colher."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia38: { nome: "Mingau de Farinha Láctea com mamão", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 250, 250] }, { a: 'farinhaLactea', q: [20, 20, 25, 15] }, { a: 'mamao', q: [60, 110, 110, 60] }], preparo: "Mingau de Farinha Láctea com mamão amassado por cima.", tempo: 7, passos: ["Dissolva a Farinha Láctea em um pouco do leite frio, em uma panela.","Junte o resto do leite e mexa em fogo baixo por 3 minutos, até engrossar.","Amasse o mamão com um garfo.","Sirva o mingau morno com o mamão amassado por cima."], etiquetas: ["doce","vegetariano"] },
  ceia39: { nome: "Mamão amassado com aveia e leite quente", categoria: 'ceia', itens: [{ a: 'leite', q: [200, 200, 250, 200] }, { a: 'mamao', q: [100, 150, 120, 100] }, { a: 'aveia', q: [25, 25, 25, 20] }], preparo: "Aveia cozida no leite com mamão amassado.", tempo: 6, passos: ["Tire a casca e as sementes do mamão e amasse com um garfo em uma tigela.","Aqueça o leite com a aveia em uma panela pequena, em fogo baixo, por 3 minutos, mexendo sempre.","Junte o mamão amassado e mexa por mais 1 minuto.","Polvilhe canela e coma morno."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia40: { nome: "Creme de abacate com doce de leite", categoria: 'ceia', itens: [{ a: 'abacate', q: [30, 40, 40, 25] }, { a: 'leite', q: [250, 250, 300, 250] }, { a: 'doceLeite', q: [25, 30, 25, 20] }], preparo: "Abacate batido com leite e doce de leite, bem cremoso.", tempo: 5, passos: ["Tire a casca e o caroço do abacate maduro.","Coloque no liquidificador com o leite e o doce de leite.","Bata por 40 segundos, até virar um creme liso.","Sirva em um copo ou tigela, gelado, e tome de colher ou devagar."], etiquetas: ["doce","vegetariano"] },
  ceia41: { nome: "Creme gelado de iogurte com doce de leite", categoria: 'ceia', itens: [{ a: 'iogurte', q: [270, 310, 320, 260] }, { a: 'doceLeite', q: [30, 30, 35, 25] }, { a: 'leite', q: [50, 50, 50, 50] }], preparo: "Iogurte cremoso misturado com doce de leite, gelado por 10 minutos.", tempo: 15, passos: ["Dissolva o doce de leite no leite morno, mexendo com uma colher.","Misture o iogurte nessa calda até ficar uniforme.","Distribua em um copo ou potinho.","Leve ao congelador por 10 minutos, até gelar bem, e coma de colher."], etiquetas: ["doce","vegetariano"] },
  ceia42: { nome: "Cuscuz doce com leite e mel", categoria: 'ceia', itens: [{ a: 'cuscuz', q: [120, 140, 130, 100] }, { a: 'leite', q: [150, 150, 200, 150] }, { a: 'mel', q: [10, 10, 10, 10] }], preparo: "Cuscuz de milho morno com leite quente e fio de mel.", tempo: 5, passos: ["Esquente o cuscuz pronto no micro-ondas por 1 minuto, em uma tigela.","Aqueça o leite por 1 minuto e meio, sem deixar ferver.","Despeje o leite sobre o cuscuz e deixe 1 minuto, para amolecer.","Finalize com o mel e uma pitada de canela. Coma de colher."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia43: { nome: "Açaí cremoso batido com leite em pó", categoria: 'ceia', itens: [{ a: 'acai', q: [110, 140, 140, 70] }, { a: 'leite', q: [200, 200, 200, 200] }, { a: 'leitePo', q: [15, 15, 20, 15] }], preparo: "Açaí batido com leite e leite em pó, para tomar de copo.", tempo: 6, passos: ["Deixe a polpa de açaí 5 minutos fora do congelador, para amolecer.","Coloque no liquidificador com o leite e o leite em pó.","Bata por 40 segundos, até ficar liso e cremoso.","Sirva em copo alto e beba devagar. Use açaí puro, sem guaraná."], etiquetas: ["doce","vegetariano"] },
  ceia44: { nome: "Vitamina de mamão com iogurte e mel", categoria: 'ceia', itens: [{ a: 'iogurte', q: [250, 270, 300, 260] }, { a: 'mamao', q: [220, 240, 250, 190] }, { a: 'mel', q: [15, 15, 15, 10] }], preparo: "Mamão batido com iogurte e mel.", tempo: 4, passos: ["Corte o mamão em pedaços, sem casca e sem sementes.","Coloque no liquidificador com o iogurte e o mel.","Bata por 40 segundos, até ficar liso.","Sirva gelada, com 2 pedras de gelo se quiser, e beba devagar."], etiquetas: ["doce","vegetariano"], temperos: ["gelo"] },
  ceia45: { nome: "Vitamina rosa de morango e banana", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 300, 200] }, { a: 'morango', q: [100, 160, 130, 130] }, { a: 'banana', q: [1, 1, 1, 1] }], preparo: "Morango e banana batidos com leite.", tempo: 4, passos: ["Lave os morangos e tire as folhinhas.","Coloque no liquidificador com a banana em pedaços e o leite.","Bata por 40 segundos, até ficar rosada e lisa.","Beba gelada ou ao natural, devagar."], etiquetas: ["doce","vegetariano"] },
  ceia46: { nome: "Iogurte batido com abacate e mel", categoria: 'ceia', itens: [{ a: 'iogurte', q: [300, 330, 350, 300] }, { a: 'abacate', q: [30, 35, 30, 25] }, { a: 'mel', q: [25, 25, 30, 20] }], preparo: "Iogurte batido com abacate e mel, cremoso.", tempo: 4, passos: ["Tire a polpa do abacate maduro.","Coloque no liquidificador com o iogurte e o mel.","Bata por 30 segundos, até ficar um creme liso.","Sirva em copo ou tigela e coma de colher."], etiquetas: ["doce","vegetariano"] },
  ceia47: { nome: "Mingau de aveia com banana e pasta de amendoim", categoria: 'ceia', itens: [{ a: 'leite', q: [150, 150, 200, 150] }, { a: 'aveia', q: [15, 20, 20, 15] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'pastaAmendoim', q: [5, 5, 5, 5] }], preparo: "Mingau de aveia com banana e pasta de amendoim.", tempo: 8, passos: ["Leve o leite e a aveia ao fogo baixo, mexendo por 4 minutos, até engrossar.","Fatie a banana e junte no mingau no último minuto.","Desligue o fogo e misture a pasta de amendoim até dissolver.","Sirva morno, em tigela, e coma devagar."], etiquetas: ["doce","vegetariano"] },
  ceia48: { nome: "Iogurte batido com maçã e canela", categoria: 'ceia', itens: [{ a: 'iogurte', q: [160, 200, 180, 180] }, { a: 'leite', q: [150, 150, 200, 100] }, { a: 'macaFruta', q: [1, 1, 1, 1] }, { a: 'mel', q: [5, 5, 5, 5] }], preparo: "Maçã sem casca batida com iogurte, leite, mel e canela.", tempo: 5, passos: ["Descasque a maçã, tire as sementes e corte em pedaços.","Coloque no liquidificador com o iogurte, o leite e o mel.","Bata por 40 segundos, até ficar liso.","Sirva em copo e polvilhe canela por cima."], etiquetas: ["doce","vegetariano"], temperos: ["canela"] },
  ceia49: { nome: "Leite morno com doce de leite e biscoito maisena", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 250, 250] }, { a: 'doceLeite', q: [15, 20, 20, 15] }, { a: 'maisena', q: [15, 15, 20, 10] }], preparo: "Leite morno com doce de leite e biscoito maisena para molhar.", tempo: 5, passos: ["Aqueça o leite no micro-ondas por 1 minuto e 30 segundos, sem ferver.","Junte o doce de leite e mexa até dissolver.","Passe para uma caneca.","Coma o biscoito maisena molhando no leite."], etiquetas: ["doce","vegetariano"] },
  ceia50: { nome: "Vitamina cremosa de mamão com leite em pó", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 300, 300, 250] }, { a: 'mamao', q: [140, 120, 110, 90] }, { a: 'leitePo', q: [10, 10, 15, 10] }], preparo: "Mamão batido com leite e leite em pó.", tempo: 4, passos: ["Corte o mamão em pedaços, sem casca e sem sementes.","Coloque no liquidificador com o leite e o leite em pó.","Bata por 40 segundos, até ficar espessa e lisa.","Beba gelada, devagar."], etiquetas: ["doce","vegetariano"] },
  ceia51: { nome: "Mingau de Mucilon com morango", categoria: 'ceia', itens: [{ a: 'leite', q: [250, 250, 300, 250] }, { a: 'mucilon', q: [20, 25, 25, 20] }, { a: 'morango', q: [110, 110, 80, 40] }], preparo: "Mingau de Mucilon com morango picado por cima.", tempo: 7, passos: ["Dissolva o Mucilon em um pouco do leite frio, em uma panela.","Junte o resto do leite e mexa em fogo baixo por 3 minutos, até engrossar.","Lave e pique os morangos.","Sirva o mingau morno com o morango por cima."], etiquetas: ["doce","vegetariano"] },
  ceia52: { nome: "Vitamina de banana com achocolatado", categoria: 'ceia', itens: [{ a: 'leite', q: [200, 250, 250, 200] }, { a: 'banana', q: [1, 1, 1, 1] }, { a: 'achocolatado', q: [15, 10, 15, 10] }], preparo: "Banana batida com leite e achocolatado.", tempo: 4, passos: ["Quebre a banana em pedaços no liquidificador.","Junte o leite e o achocolatado.","Bata por 40 segundos, até ficar liso.","Beba gelada ou aqueça o copo no micro-ondas por 40 segundos."], etiquetas: ["doce","vegetariano"] },
  ceia53: { nome: "Iogurte com manga picada e granola", categoria: 'ceia', itens: [{ a: 'iogurte', q: [190, 200, 210, 190] }, { a: 'manga', q: [120, 110, 130, 90] }, { a: 'granola', q: [15, 20, 20, 15] }, { a: 'mel', q: [5, 5, 5, 5] }], preparo: "Iogurte com manga picada, granola e fio de mel.", tempo: 4, passos: ["Corte a manga em cubos pequenos, sem casca nem caroço.","Coloque o iogurte em uma tigela e junte a manga.","Cubra com a granola, só na hora de comer, para não amolecer.","Finalize com o mel em fio e coma de colher."], etiquetas: ["doce","vegetariano"] },
} as const satisfies Record<string, Prato>

export type IdPrato = keyof typeof PRATOS
